import type { Action, Call, Claim, Id, World } from "./types";
import { Rng } from "./rng";
import { generateWorld } from "./worldgen";
import { K, alternatives, believed, describeKey, describeValue, trustIn } from "./beliefs";
import { applyWant, connectCall, hear, log, operatorLearns, reliefMinute, tick } from "./tick";
import { pleaStance, willComply } from "./ai";
import type { Response } from "./ai";
import { clock, composeRelay, him, his } from "./text";

export function newGame(seed: string): World {
  return generateWorld(seed);
}

export function advance(world: World, minutes: number): void {
  for (let i = 0; i < minutes && world.status === "playing"; i++) tick(world);
}

/** Calls the operator can act on right now. */
export function pendingCalls(world: World): Call[] {
  return Object.values(world.calls)
    .filter((c) => c.state === "ringing" || c.state === "held" || c.state === "message")
    .sort((a, b) => a.placedAt - b.placedAt);
}

export function liveCalls(world: World): Call[] {
  return Object.values(world.calls)
    .filter((c) => c.state === "connected")
    .sort((a, b) => (a.connectedAt ?? 0) - (b.connectedAt ?? 0));
}

/** Can this party take a call right now? Returns a reason if not. */
export function reachable(world: World, toId: Id): string | null {
  const a = world.actors[toId];
  if (!a) return "No such line.";
  if (a.status === "arrested") return `${a.short} has been arrested.`;
  if (a.status === "dead") return "The line is dead.";
  if (a.busyWith) return "Engaged.";
  if (!world.locations[a.locationId]?.hasLine) return "No line at that location.";
  const unit = Object.values(world.units).find((u) => u.commanderId === a.id);
  if (unit?.moving && (a.role === "colonel" || a.role === "airfield_major")) return `${a.short} has left ${world.locations[unit.moving.from]!.name}. No answer.`;
  return null;
}

export function applyAction(world: World, action: Action): void {
  if (world.status !== "playing" && action.type !== "tick") return;
  const rng = Rng.fromState(world.rng);
  const t = world.player.tally;
  const call = "callId" in action && action.callId ? world.calls[action.callId] : undefined;
  const caller = call ? world.actors[call.callerId] : undefined;
  const requested = call ? world.actors[call.requestedId] : undefined;
  const stamp = clock(world.minute);

  switch (action.type) {
    case "tick":
      tick(world);
      return;

    case "break": {
      const b = world.breaks[world.breaks.length - 1];
      if (!b || b.minute !== world.minute) return;
      b.reliefConnected = reliefBreak(world, 5);
      return;
    }

    case "connect": {
      if (!call || !caller || (call.state !== "ringing" && call.state !== "held")) break;
      if (call.requestedId === "operator") break;
      if (connectCall(world, call, call.requestedId, rng)) t.connected++;
      break;
    }

    case "misroute": {
      if (!call || !caller || (call.state !== "ringing" && call.state !== "held")) break;
      if (action.toId === call.requestedId || action.toId === call.callerId) break;
      if (connectCall(world, call, action.toId, rng)) {
        t.misrouted++;
        t.connected++;
      }
      break;
    }

    case "hold": {
      if (!call || call.state !== "ringing") break;
      call.state = "held";
      call.heldAt = world.minute;
      t.held++;
      if (isConsequential(call)) {
        log(world, "exchange", `${stamp} You told ${caller!.short} all trunks were busy and left the lamp burning.`, [caller!.id], { fingerprint: true });
      }
      break;
    }

    case "refuse": {
      if (!call || !caller || (call.state !== "ringing" && call.state !== "held")) break;
      call.state = "refused";
      caller.busyWith = null;
      caller.nextCallAt = world.minute + 10;
      caller.suspicion = Math.min(100, caller.suspicion + (call.intent.urgency > 0.7 ? 6 : 3) * (world.watchers.length ? 2 : 1));
      t.refused++;
      const who = requested?.short ?? "the operator";
      log(world, "exchange", `${stamp} You told ${caller.short} the line to ${who} was down.${isConsequential(call) ? ` ${describeLost(world, call)}` : ""}`, [caller.id], { fingerprint: isConsequential(call) });
      if (call.intent.kind === "order" && (caller.done[`${call.intent.tag}#n`] ?? 0) >= 2 && requested) {
        const mins = Math.round(30 + rng.next() * 20);
        world.runners.push({ fromId: caller.id, toId: requested.id, claims: call.intent.claims, want: call.intent.want, arriveAt: world.minute + mins, tag: call.intent.tag });
        log(world, "move", `${caller.short} gives up on the telephone and sends a runner to ${requested.short}.`, [caller.id], { secret: true });
      }
      break;
    }

    case "listen": {
      for (const c of Object.values(world.calls)) {
        if (c.state === "connected" && c.listening && c.id !== action.callId) c.listening = false;
      }
      if (action.callId) {
        const c = world.calls[action.callId];
        if (c && c.state === "connected") {
          if (!c.listening) {
            c.listening = true;
            if (c.heardFrom === undefined) {
              c.heardFrom = c.spoken;
              t.listened++;
            }
            // Catch up on claims already spoken while we were listening before.
          }
        }
      }
      break;
    }

    case "cut": {
      if (!call || call.state !== "connected") break;
      const callee = world.actors[call.connectedToId!]!;
      call.state = "cut";
      call.listening = false;
      caller!.busyWith = null;
      callee.busyWith = null;
      caller!.nextCallAt = world.minute + 6;
      callee.nextCallAt = world.minute + 3;
      const mult = world.watchers.length ? 2 : 1;
      caller!.suspicion = Math.min(100, caller!.suspicion + 8 * mult);
      callee.suspicion = Math.min(100, callee.suspicion + 8 * mult);
      t.cut++;
      log(world, "exchange", `${stamp} You pulled the cord on ${caller!.short} and ${callee.short} mid-sentence.${call.wantApplied ? "" : ` ${describeLost(world, call)}`}`, [caller!.id, callee.id], { fingerprint: true });
      break;
    }

    case "take_message": {
      if (!call || !caller || (call.state !== "ringing" && call.state !== "held")) break;
      if (call.requestedId === "operator") break;
      call.state = "message";
      caller.busyWith = null;
      caller.nextCallAt = world.minute + 12;
      t.messagesTaken++;
      // The operator hears everything the caller wanted to say.
      for (const c of call.intent.claims) operatorLearns(world, c, caller.id);
      log(world, "exchange", `${stamp} You told ${caller.short} that ${requested?.short ?? "the party"} could not be reached and took the message down.`, [caller.id]);
      break;
    }

    case "relay": {
      if (!call || !caller || call.state !== "message" || !requested) break;
      const altered = !sameClaims(action.claims, call.intent.claims);
      call.relayed = { claims: action.claims, altered, deliveredAt: world.minute };
      if (altered) t.messagesAltered++;
      const conf = trustIn(requested, "exchange") * Math.max(0.3, trustIn(requested, caller.id)) * 1.2;
      const response: Response =
        call.intent.kind === "plead"
          ? { stance: pleaStance(world, requested) }
          : call.intent.want
            ? { stance: willComply(world, caller, requested, { ...call.intent, claims: action.claims }, rng) }
            : { stance: "noted" };
      call.transcript = composeRelay(world, call, requested, action.claims, call.intent.want, response);
      call.spoken = call.transcript.length;
      call.response = response;
      for (const c of action.claims) hear(world, requested, c, "exchange", conf, call.id);
      if (call.intent.want && response.stance === "agree") {
        applyWant(world, requested, call.intent.want, caller.id, `Relayed by the exchange from ${caller.short}.`);
        call.wantApplied = true;
      }
      if (call.intent.kind === "plead" && response.stance === "agree") {
        requested.done["peace"] = world.minute;
        call.wantApplied = true;
        log(world, "move", `${requested.short} gives ${his(requested)} word to the Archbishop, through the exchange: no blood tonight.`, [requested.id], { secret: true });
      } else if (call.intent.kind === "plead") {
        // Delivered too early. The Archbishop will ring once more, later.
        caller.done[`${call.intent.tag}#n`] = 0;
        caller.nextCallAt = world.minute + 30;
      }
      caller.done[`${call.intent.tag}#ok`] = 1;
      call.state = "ended";
      log(
        world,
        "exchange",
        `${stamp} You rang ${requested.short} and passed on ${caller.short}'s message${altered ? ", with changes of your own" : ""}. ${requested.short} ${response.stance === "agree" ? "will act on it" : response.stance === "refuse" ? "refused" : "took note"}.`,
        [caller.id, requested.id],
        { fingerprint: true },
      );
      break;
    }

    case "drop_message": {
      if (!call || !caller || call.state !== "message") break;
      call.state = "ended";
      log(world, "exchange", `${stamp} You put ${caller.short}'s message in the drawer and forgot it. ${describeLost(world, call)}`, [caller.id], { fingerprint: true });
      break;
    }

    case "answer": {
      if (!call || !caller || call.state !== "ringing" || call.requestedId !== "operator") break;
      call.state = "ended";
      call.operatorAnswer = action.answer;
      caller.busyWith = null;
      caller.nextCallAt = world.minute + 10;
      t.answered++;
      if (call.intent.tag === "family") {
        const f = world.family;
        f.knownAt = world.minute;
        const line =
          f.where === "bridge"
            ? `${stamp} ${f.name} rang from the bridge guardroom. The Bridge Company has been stood to. You told him to keep his head down and said nothing to anyone.`
            : f.where === "square"
              ? `${stamp} ${f.name} rang from the University. If the union calls people out, he is going. You told him to stay where he was. He will not.`
              : `${stamp} Mother rang. The Prefecture has been asking which room ${f.name} sleeps in. You told her it was nothing. It is not nothing.`;
        log(world, "civil", line, [caller.id], { hand: true });
        break;
      }
      if (action.answer === "unknown") {
        log(world, "exchange", `${stamp} ${caller.short} asked you what you knew. You said you were only the operator.`, [caller.id]);
      } else {
        hear(world, caller, action.answer, "exchange", trustIn(caller, "exchange"), call.id);
        const lie = world.facts[action.answer.key] !== undefined && world.facts[action.answer.key] !== action.answer.value;
        log(world, "exchange", `${stamp} ${caller.short} asked you what you knew. You told ${him(caller)} ${lower(describe(world, action.answer))}.${lie ? " It was not true." : ""}`, [caller.id], { fingerprint: true });
      }
      break;
    }
  }
  world.rng = rng.state();
}

function isConsequential(call: Call): boolean {
  return call.intent.kind === "order" || call.intent.kind === "persuade" || call.intent.kind === "request";
}

function describeLost(world: World, call: Call): string {
  const caller = world.actors[call.callerId]!;
  const target = world.actors[call.requestedId];
  if (!target) return "";
  const w = call.intent.want;
  if (w) {
    switch (w.action) {
      case "move":
        return `${target.short} never received the order to move ${world.units[w.unitId ?? ""]?.name ?? `${his(target)} men`} to ${world.locations[w.target ?? ""]?.name ?? "the city"}.`;
      case "hold":
        return `${target.short} never heard ${caller.short} ask ${him(target)} to keep ${his(target)} men where they were.`;
      case "close_bridge":
        return `The order to close the bridge never reached the Bridge Company.`;
      case "open_bridge":
        return `The request to keep the bridge open never reached the Bridge Company.`;
      case "broadcast":
        return `Radio House never got its instructions.`;
      case "stand_down":
        return `${target.short} was never asked to stand ${his(target)} men down.`;
      case "mobilise":
        return `The call to bring people into the streets never arrived.`;
      case "shelter":
        return `Nobody told the President to leave.`;
      case "arrest":
        return w.target === "list" ? `The Prefect never got the names for first light.` : w.target === "government" ? `The order to take the Minister and the Prefect never reached the Major.` : w.target === "a_colonel" ? `The order to arrest the Colonel never reached the General.` : "";
    }
  }
  if (call.intent.kind === "persuade") return `${caller.short} never got to make his case to ${target.short}.`;
  return "";
}

function sameClaims(a: Claim[], b: Claim[]): boolean {
  if (a.length !== b.length) return false;
  const key = (c: Claim) => `${c.key}=${c.value}`;
  const sa = a.map(key).sort().join("|");
  const sb = b.map(key).sort().join("|");
  return sa === sb;
}

function describe(world: World, c: Claim): string {
  return `${describeKey(world, c.key)} was ${describeValue(world, c.key, c.value)}`;
}

function lower(s: string): string {
  return s.charAt(0).toLowerCase() + s.slice(1);
}

/**
 * The relief operator has the board for a few minutes: she connects whatever is ringing, as the regulations
 * say, and does not listen. Returns the connections she made, for the break card.
 */
export function reliefBreak(world: World, minutes = 5): string[] {
  const made: string[] = [];
  for (let i = 0; i < minutes && world.status === "playing"; i++) made.push(...reliefMinute(world));
  return made;
}

/** Options the operator can offer when answering a direct question. */
export function answerOptions(world: World, call: Call): { claim: Claim; label: string; known: boolean }[] {
  const key = call.intent.askKey ?? K.coup;
  const known = world.player.knowledge[key]?.value;
  return alternatives(world, key).map((v) => ({
    claim: { key, value: v },
    label: describeValue(world, key, v),
    known: known !== undefined && known === v,
  }));
}

export { believed, K };
