import type { World } from "../sim/types";
import { clock } from "../sim/text";
import { connectedCount } from "../sim/tick";
import { h, replaceChildren } from "./dom";
import type { UiActions, UiState } from "./state";

function avgSuspicion(w: World, ids: string[]): number {
  return ids.reduce((s, id) => s + (w.actors[id]?.suspicion ?? 0), 0) / ids.length;
}

function suspicionWord(v: number): string {
  if (v >= 70) return "coming for you";
  if (v >= 40) return "watching the exchange";
  if (v >= 15) return "curious";
  return "quiet";
}

export function renderTopbar(root: HTMLElement, st: UiState, ui: UiActions, extra: { muted: boolean; toggleMute: () => void }): void {
  const w = st.world;
  const gov = avgSuspicion(w, ["a_minister", "a_prefect", "a_commandant"]);
  const plot = avgSuspicion(w, ["a_colonel", "a_major"]);
  const cords = connectedCount(w);
  const watchersHere = w.watchers.filter((x) => x.arrivedAt <= w.minute);

  const speedBtn = (sp: 0 | 1 | 2, label: string, title: string) =>
    h("button", { class: `speed${st.speed === sp ? " active" : ""}`, title, onclick: () => ui.setSpeed(sp) }, label);

  replaceChildren(
    root,
    h("div", { class: "brand" }, h("span", { class: "brand-title" }, "The Exchange"), h("span", { class: "brand-sub" }, `Castellane Central · night board · Mrs ${w.operator.surname}`)),
    h("div", { class: "clock", title: w.nightTitle }, clock(w.minute)),
    h(
      "div",
      { class: "speeds" },
      speedBtn(0, "❚❚", "Pause (space)"),
      speedBtn(1, "▶", "Normal: one minute every 2.5 seconds"),
      speedBtn(2, "▶▶", "Double speed"),
    ),
    h(
      "div",
      { class: "cords-meter", title: "Cord pairs in use. Six pairs; each connected call holds one." },
      h("span", { class: "meter-label" }, "cords"),
      h("span", { class: "meter-pips" }, Array.from({ length: w.player.cordPairs }, (_, i) => h("span", { class: `pip${i < cords ? " used" : ""}` }))),
    ),
    h(
      "div",
      { class: "susp" },
      suspLamp("Government", gov, "government"),
      suspLamp("Plotters", plot, "plotters"),
    ),
    watchersHere.length ? h("div", { class: "watcher", title: "Someone is watching the board. Everything you do is twice as risky." }, `Behind you: ${watchersHere.map((x) => x.name).join(", ")}.`) : null,
    h("div", { class: "spacer" }),
    h("button", { class: "act tiny", title: "The back pages: who everyone is, what you have heard, your notes. Pauses the night. (D)", onclick: () => ui.openDossier("city") }, "dossier"),
    h("button", { class: "act tiny", title: "The prologue and the regulations card.", onclick: () => ui.showPrologue(true) }, "regulations"),
    h("button", { class: "act tiny", title: extra.muted ? "Unmute" : "Mute", onclick: extra.toggleMute }, extra.muted ? "sound off" : "sound on"),
    h("a", { class: "seed", href: `?seed=${encodeURIComponent(st.seed)}`, title: "Permanent link to this night. Same seed, same night, until you act." }, `seed ${st.seed}`),
    h("button", { class: "act tiny", title: "Start a fresh night with a new seed.", onclick: () => ui.newNight() }, "new night"),
  );
}

function suspLamp(label: string, v: number, cls: string): HTMLElement {
  const level = v >= 70 ? 3 : v >= 40 ? 2 : v >= 15 ? 1 : 0;
  return h(
    "div",
    { class: `susp-lamp ${cls} level-${level}`, title: `${label} suspicion of the exchange: ${Math.round(v)}. ${suspicionWord(v)}.` },
    h("span", { class: "susp-dot" }),
    h("span", { class: "susp-label" }, label),
    h("span", { class: "susp-word" }, suspicionWord(v)),
  );
}
