import type { Actor, Call, Claim, Faction, Id, Intent, Loyalty, Unit, World } from "./types";
import { K, believed, believedWinner, trustIn } from "./beliefs";
import { opening } from "./text";
import type { Rng } from "./rng";

export type Stance = "agree" | "refuse" | "stall" | "alarmed" | "noted" | "confused" | "answer" | "unknown";

export interface Response {
  stance: Stance;
  answerClaims?: Claim[];
}

export interface CallWish {
  requestedId: Id;
  intent: Intent;
}

/* ------------------------------------------------------------------------------------------------
 * Sides
 * ---------------------------------------------------------------------------------------------- */

/** The side an actor is actually acting for right now. Undecided actors follow who they think is winning. */
export function effectiveSide(actor: Actor): Faction | null {
  if (actor.loyalty === "plotter") return "plotters";
  if (actor.loyalty === "loyalist") return "government";
  return believedWinner(actor);
}

export function unitOf(world: World, actor: Actor): Unit | undefined {
  return Object.values(world.units).find((u) => u.commanderId === actor.id);
}

export function travelsWithUnit(actor: Actor): boolean {
  return actor.role === "colonel" || actor.role === "airfield_major";
}

function coupKnown(actor: Actor): boolean {
  return believed(actor, K.coup) === "yes";
}

/** The Palace question, once settled. */
function decided(world: World): string | undefined {
  return world.facts["decided"] as string | undefined;
}
function decidedAt(world: World): number {
  return Number(world.facts["decided:at"] ?? 9999);
}

function superiorOf(callee: Actor, caller: Actor): boolean {
  // Who can give whom orders along the official chain.
  switch (callee.role) {
    case "bridge_captain":
      return caller.role === "general" || caller.role === "minister" || caller.role === "president";
    case "airfield_major":
      return caller.role === "colonel" || caller.role === "general" || caller.role === "minister";
    case "general":
      return caller.role === "minister" || caller.role === "president";
    case "guard_commandant":
      return caller.role === "president" || caller.role === "minister";
    case "prefect":
      return caller.role === "minister" || caller.role === "president";
    case "radio_director":
      return caller.role === "minister" || caller.role === "president";
    case "colonel":
      return caller.role === "general" || caller.role === "minister" || caller.role === "president";
    default:
      return false;
  }
}

/* ------------------------------------------------------------------------------------------------
 * Deciding to call
 * ---------------------------------------------------------------------------------------------- */

interface Step {
  tag: string;
  when: (w: World, a: Actor) => boolean;
  make: (w: World, a: Actor, rng: Rng) => CallWish | null;
  /** Maximum attempts before giving up (and perhaps sending a runner). */
  attempts?: number;
  /** Minutes between attempts. */
  retryAfter?: number;
}

function attempts(a: Actor, tag: string): number {
  return a.done[`${tag}#n`] ?? 0;
}
function succeeded(a: Actor, tag: string): boolean {
  return (a.done[`${tag}#ok`] ?? 0) > 0;
}
function lastTried(a: Actor, tag: string): number {
  return a.done[tag] ?? -9999;
}

function claimsOf(a: Actor, keys: string[]): Claim[] {
  const out: Claim[] = [];
  for (const k of keys) {
    const v = believed(a, k);
    if (v !== undefined) out.push({ key: k, value: v });
  }
  return out;
}

function wish(world: World, caller: Actor, requestedId: Id, intent: Omit<Intent, "opening">): CallWish {
  return { requestedId, intent: { ...intent, opening: opening(world, caller, requestedId, intent) } };
}

