/** Decide whether this actor wants to place a call right now. Does not mutate state. */
export function wantsToCall(world: World, actor: Actor, rng: Rng): CallWish | null {
  if (actor.status !== "free" || actor.busyWith) return null;
  if (world.minute < actor.nextCallAt) return null;
  const unit = unitOf(world, actor);
  if (unit?.moving && travelsWithUnit(actor)) return null;
  if (!world.locations[actor.locationId]?.hasLine) return null;

  if (actor.id === "a_family") return familyCall(world, actor);
  if (actor.role === "citizen") return citizenCall(world, actor, rng);

  const steps = STEPS[actor.role] ?? [];
  for (const s of steps) {
    if (succeeded(actor, s.tag)) continue;
    const n = attempts(actor, s.tag);
    if (n >= (s.attempts ?? 1)) continue;
    if (n > 0 && world.minute - lastTried(actor, s.tag) < (s.retryAfter ?? 15)) continue;
    if (!s.when(world, actor)) continue;
    const w = s.make(world, actor, rng);
    if (!w) continue;
    const target = world.actors[w.requestedId];
    if (w.requestedId !== "operator" && (!target || target.status !== "free")) continue;
    return w;
  }
  return null;
}

function citizenCall(world: World, actor: Actor, rng: Rng): CallWish | null {
  if ((actor.done["citizenDone"] ?? 0) > 0) return null;
  const targetRole = Object.keys(actor.done).find((k) => k.startsWith("need:"))?.slice(5);
  const target = Object.values(world.actors).find((a) => a.role === targetRole);
  if (!target) return null;
  // Some needs only exist once the night has made them.
  const spec = CITIZEN_NEEDS.find((n) => n.need === actor.need);
  if (spec?.after === "casualties" && world.casualties.length === 0) return null;
  if (spec?.after === "decided" && world.facts["decided"] === undefined) return null;
  // Citizens report what they can see: a moving unit near their district.
  const claims: Claim[] = [];
  const here = world.locations[actor.locationId]!;
  for (const u of Object.values(world.units)) {
    if (!u.moving) continue;
    const to = world.locations[u.moving.to]!;
    const from = world.locations[u.moving.from]!;
    const mx = (to.x + from.x) / 2;
    const my = (to.y + from.y) / 2;
    if (Math.hypot(mx - here.x, my - here.y) < 260 && rng.chance(0.7)) {
      claims.push({ key: K.unit(u.id), value: u.moving.to });
      break;
    }
  }
  if (!claims.length && Number(world.facts["shots"] ?? 0) > 0 && rng.chance(0.5)) claims.push({ key: K.coup, value: "yes" });
  const intent: Omit<Intent, "opening"> = { kind: "personal", tag: "citizen", claims, urgency: 0.5 + rng.next() * 0.4 };
  const w = wish(world, actor, target.id, intent);
  // Citizens have their own openings written in names.ts; swap in the one for this need.
  const needSpec = citizenOpening(actor);
  if (needSpec) w.intent.opening = needSpec;
  return w;
}

/** Someone of the operator's rings her line, once, early. Nobody else is meant to know who she is. */
function familyCall(world: World, actor: Actor): CallWish | null {
  if ((actor.done["family"] ?? 0) > 0) return null;
  const f = world.family;
  const op = world.operator.first;
  const when = f.where === "list" ? world.plan.startAt + 55 : world.plan.startAt + 9;
  if (world.minute < when) return null;
  let opening: string;
  switch (f.where) {
    case "bridge":
      opening = `${op}? It's me. Don't say my name. We've been stood to on the bridge, the Captain's had two calls and he won't say from whom. Don't tell Mother.`;
      break;
    case "square":
      opening = `${op}, it's me, I'm at the union office at the University. Something's happening. If they call everyone out I'm going. I wanted you to hear it from me.`;
      break;
    default: {
      const lodger = world.actors[f.actorId]!;
      opening = `${op}, it's Mother. Two men from the Prefecture were here asking which room ${f.name} sleeps in. I said I didn't know. Is ${lodger.gender === "f" ? "she" : "he"} in trouble?`;
    }
  }
  return {
    requestedId: "operator",
    intent: { kind: "personal", tag: "family", claims: [], opening, urgency: 0.95 },
  };
}

function citizenOpening(actor: Actor): string | null {
  // The opening is stored on the actor's need text via the CITIZEN_NEEDS table; look it up lazily.
  const spec = CITIZEN_OPENINGS[actor.need ?? ""];
  return spec ?? null;
}

import { CITIZEN_NEEDS } from "./names";
const CITIZEN_OPENINGS: Record<string, string> = Object.fromEntries(CITIZEN_NEEDS.map((n) => [n.need, n.opening[0]!]));

/* ------------------------------------------------------------------------------------------------
 * Responding to a call
 * ---------------------------------------------------------------------------------------------- */

/** How the connected party responds. Decided at connection time; the transcript is composed from it. */
export function decideResponse(world: World, call: Call, rng: Rng): Response {
  const caller = world.actors[call.callerId]!;
  const callee = world.actors[call.connectedToId!]!;
  if (call.misrouted) return { stance: "confused" };
  const intent = call.intent;
  switch (intent.kind) {
    case "order":
    case "request":
    case "persuade":
      return { stance: willComply(world, caller, callee, intent, rng) };
    case "inform": {
      const serious = intent.claims.some((c) => c.key === K.coup && c.value === "yes") && believed(callee, K.coup) !== "yes";
      return { stance: serious ? "alarmed" : "noted" };
    }
    case "ask": {
      const key = intent.askKey ?? K.coup;
      const b = callee.beliefs[key];
      if (!b || b.confidence < 0.3) return { stance: "unknown" };
      // Plotters lie about the President to anyone not on their side.
      if (callee.loyalty === "plotter" && effectiveSide(caller) !== "plotters" && key === K.president) {
        return { stance: "answer", answerClaims: [{ key, value: "loc_embassy" }] };
      }
      const extra: Claim[] = [];
      if (key !== K.coup && believed(callee, K.coup) === "yes") extra.push({ key: K.coup, value: "yes" });
      return { stance: "answer", answerClaims: [{ key, value: b.value }, ...extra] };
    }
    case "plead": {
      return { stance: pleaStance(world, callee) };
    }
    case "personal": {
      const answers: Claim[] = [];
      if (callee.role === "hospital_director") {
        const b = callee.beliefs[K.bridge];
        if (b) answers.push({ key: K.bridge, value: b.value });
      }
      if (callee.role === "editor" || callee.role === "union_boss") {
        const b = callee.beliefs[K.curfew];
        if (b) answers.push({ key: K.curfew, value: b.value });
      }
      return answers.length ? { stance: "answer", answerClaims: answers } : { stance: "noted" };
    }
  }
}

/**
 * Does a plea for no bloodshed land? The timid agree anywhere. The Colonel only agrees once he is in the square
 * looking at the Guard, and then only if the arithmetic or the crowd is against him, or he is not quite as bold
 * as he sounds. From the Fort he will not even discuss it.
 */
export function pleaStance(world: World, callee: Actor): Stance {
  if (callee.role !== "colonel") return callee.traits.boldness < 0.6 ? "agree" : "stall";
  const since = callee.done["standoff_palace"];
  // Not from the Fort, and not in the first flush of the standoff either: he needs to have looked at the gates.
  if (since === undefined || world.minute - since < 45) return "stall";
  const regiment = world.units["u_regiment"]!;
  const here = Object.values(world.units).filter((u) => !u.moving && u.at === regiment.at && u.strength > 0 && u.id !== regiment.id);
  const against = here.filter((u) => (effectiveSide(world.actors[u.commanderId]!) ?? (world.actors[u.commanderId]!.faction === "plotters" ? "plotters" : "government")) !== "plotters").reduce((s, u) => s + u.strength, 0);
  const crowd = Number(world.facts[K.crowd("loc_palace")] ?? 0);
  if (against > 1.1 * regiment.strength || crowd >= 300 || callee.traits.boldness < 0.8) return "agree";
  return "stall";
}

/** Would the callee do what the caller asks? Agree, refuse, or stall. */
export function willComply(world: World, caller: Actor, callee: Actor, intent: Intent, rng: Rng): Stance {
  const want = intent.want;
  const callerSide = effectiveSide(caller) ?? caller.faction;
  const calleeSide = effectiveSide(callee);
  const chain = superiorOf(callee, caller);
  const trust = trustIn(callee, caller.id);

  // Civil actors asked to mobilise or broadcast.
  if (callee.role === "union_boss") {
    if (callee.loyalty === "plotter") return "refuse";
    return callee.traits.boldness > 0.45 || trust > 0.6 ? "agree" : "stall";
  }
  if (callee.role === "radio_director") {
    // The radio does what the men in the building say, otherwise what the Ministry says.
    const holder = world.facts[K.control("loc_radio")];
    if (holder === "plotters") return callerSide === "plotters" ? "agree" : "refuse";
    if (callerSide === "government" && chain) return "agree";
    if (callerSide === "plotters") return callee.traits.obedience > 0.7 && calleeSide === "plotters" ? "agree" : "stall";
    return "refuse";
  }
  if (callee.role === "ambassador") {
    return want?.action === "shelter" ? "agree" : "noted";
  }
  if (callee.role === "president") {
    if (want?.action === "shelter") return believedWinner(callee) === "plotters" || callee.traits.boldness < 0.35 ? "agree" : "refuse";
    return "noted";
  }

  // Officers.
  if (callee.loyalty === "plotter") {
    if (callerSide === "plotters") return "agree";
    return chain && intent.kind === "order" && !coupKnown(callee) ? "stall" : "refuse";
  }
  if (callee.loyalty === "loyalist") {
    if (callerSide === "government") return chain || callee.traits.obedience > 0.4 ? "agree" : "stall";
    // A loyalist asked by a plotter: refuses, unless the plotter is in the chain and the loyalist doesn't yet know.
    if (chain && !coupKnown(callee) && callee.traits.obedience > 0.6) return "agree";
    return "refuse";
  }
  // Undecided: follows the chain if nothing is known; otherwise follows who seems to be winning.
  if (!coupKnown(callee)) {
    if (chain) return callee.traits.obedience > 0.35 ? "agree" : "stall";
    return callee.traits.obedience > 0.75 && trust > 0.6 ? "agree" : "stall";
  }
  const winner = believedWinner(callee);
  if (winner && winner === callerSide) return "agree";
  if (winner && winner !== callerSide) return callee.traits.boldness > 0.6 ? "refuse" : "stall";
  // Genuinely torn.
  if (chain && callee.traits.obedience > 0.6) return "agree";
  return rng.chance(callee.traits.boldness * 0.5) ? (callerSide === "government" ? "agree" : "refuse") : "stall";
}

/** Decide loyalty for an undecided actor when forced to act. Mutates loyalty if they come down on a side. */
export function commit(world: World, actor: Actor, side: Faction): void {
  const loyalty: Loyalty = side === "plotters" ? "plotter" : "loyalist";
  actor.loyalty = loyalty;
  world.facts[K.loyalty(actor.id)] = loyalty;
  actor.beliefs[K.loyalty(actor.id)] = { key: K.loyalty(actor.id), value: loyalty, confidence: 1, source: "seen", minute: world.minute };
}
