import { h } from "./dom";
import type { UiActions, UiState } from "./state";

/**
 * The prologue: where you are, who you are, and the regulations card the supervisor pinned above the board,
 * which is the only tutorial the game has. Shown before the first lamp and whenever "regulations" is pressed.
 */
export function renderPrologue(st: UiState, ui: UiActions): HTMLElement {
  const w = st.world;
  const op = w.operator;
  const started = w.minute > 0;
  return h(
    "div",
    { class: "modal-back" },
    h(
      "section",
      { class: "prologue paper", role: "dialog", "aria-modal": "true", "aria-label": "Prologue" },
      h("h1", { class: "prologue-title" }, "The Exchange"),
      h("div", { class: "prologue-sub" }, w.nightTitle),
      h(
        "div",
        { class: "prologue-text" },
        h("p", {}, `The Republic of Meridia. Castellane, the capital, on the river Oriel, with one bridge. The emergency decree is in its third year: the Prefecture may hold anyone for ninety days without charge, the newspaper passes a censor, the radio belongs to the state. ${w.story.context}`),
        h(
          "p",
          {},
          `You are ${op.name}, Mrs ${op.surname} to the board. Your husband was a sergeant-major who was never going to be an officer and knew it; he went north with the brigade in 1943 and the harbour was bombed that winter and he did not come back, and you have not slept well at night since. You raised ${w.family.name} alone on jobs in and around the exchange, and when he went up to the University you took the night shift, because the board is somewhere to be awake. He is in his last year. You believe in the country, mostly because you want him to have a long life in it.`,
        ),
        h(
          "p",
          {},
          `The night board is three floors above the Post and Telegraph, with a window on the bridge. Every trunk call in the city goes through it: the Palace, the Ministry, the Prefecture, the barracks, the Fort across the river, Radio House, the hospital, the Embassy, and every subscriber who can afford a telephone. You know every voice in the city by its first word. Since the decree the logbook goes to the Prefecture every morning, by way of the shift manager, and your rule for it is that nothing needs writing down unless it is serious and you cannot ignore it. You have ignored a good deal.`,
        ),
        h("p", {}, `It is ten o'clock, early autumn, the first cold under the door. The radio is playing the southern stations' dance music, the fast kind. There is talk, as there is always talk: ${w.story.rumours[0]} ${w.story.rumours[1]} The night board has heard all of it and written none of it down. Nobody will ask what you think.`),
      ),
      h(
        "div",
        { class: "regs" },
        h("h2", { class: "regs-title" }, "Regulations for the night operator"),
        h("div", { class: "regs-sub" }, "Post and Telegraph, Castellane Central. Pinned above the board by the supervisor."),
        h(
          "ol",
          { class: "regs-list" },
          h("li", {}, "A lamp lights when a subscriber lifts the receiver. Click the jack, or the row under the board, to hear what they want. A lamp left burning goes dark after some minutes and the subscriber complains."),
          h("li", {}, h("b", {}, "Connect"), " the caller to the party asked for. Six cord pairs. A pair is busy until the call ends."),
          h("li", {}, "If the party cannot be reached, say so: ", h("b", {}, "the line is down"), ". Or ", h("b", {}, "take a message"), ", in which case you hear everything they meant to say, and ring the party yourself later to pass it on, exactly as given."),
          h("li", {}, h("b", {}, "Hold"), " a caller only with cause: all trunks are busy. The lamp stays lit. They will not wait long."),
          h("li", {}, "The operator does not ", h("b", {}, "listen"), " to connected calls.", h("span", { class: "regs-hand" }, " Everyone listens. The click is what gets you caught.")),
          h("li", {}, "The operator connects a caller to no party but the one asked for.", h("span", { class: "regs-hand" }, " A misrouted caller says his first words to the wrong person before anyone notices.")),
          h("li", {}, `Relief at every hour, five minutes. The relief (${op.relief}, from the day shift) connects whatever is ringing. Clear the board before the hour.`),
          h("li", {}, "The shift ends at six. Sign the log."),
        ),
        h("div", { class: "regs-keys muted" }, "Space pauses. 1 and 2 set the speed. Esc cancels a misroute. The map shows the city as you have heard it, not as it is."),
      ),
      h("div", { class: "dawn-actions" }, h("button", { class: "act act-connect", onclick: () => ui.showPrologue(false) }, started ? "Back to the board" : "Take the board")),
    ),
  );
}
