import { clock } from "../sim/text";
import { h, replaceChildren } from "./dom";
import type { UiState } from "./state";

/** The small card under the map: who is hers, where they are, and what she knows. */
export function renderFamily(root: HTMLElement, st: UiState): void {
  const w = st.world;
  const f = w.family;
  if (f.knownAt === null) {
    replaceChildren(root);
    root.classList.add("hidden");
    return;
  }
  root.classList.remove("hidden");
  const rel = f.relation === "brother" ? "your brother" : f.relation === "son" ? "your son" : "your lodger";
  const where = f.where === "bridge" ? "with the Bridge Company, on the bridge" : f.where === "square" ? "at the University, and will go to the square if called" : "in the back room, and on a list at the Prefecture";
  let status: string;
  if (f.newsAt !== null) status = f.status === "wounded" ? `On the ward at St. Oda's since ${clock(f.newsAt)}.` : f.status === "dead" ? `The note from St. Oda's came at ${clock(f.newsAt)}.` : "";
  else status = `Rang you at ${clock(f.knownAt)}. Nothing since.`;
  replaceChildren(
    root,
    h("h2", { class: "col-title" }, "Yours"),
    h("div", { class: `family-line ${f.newsAt !== null ? f.status : ""}` }, h("b", {}, f.name), `, ${rel}: ${where}.`),
    h("div", { class: "family-status" }, status),
  );
}
