import type { Faction, Location, Unit, World } from "../sim/types";
import { K } from "../sim/beliefs";
import { clock } from "../sim/text";
import { s, replaceChildren, h } from "./dom";
import type { UiActions, UiState } from "./state";

/**
 * The city map. By default it shows what the operator has heard, not the truth: control colours come from
 * player.knowledge, falling back to how the city stood at dusk. A debug toggle shows ground truth.
 */

const UNIT_ABBR: Record<string, string> = {
  u_regiment: "Rgt",
  u_airfield: "Air",
  u_garrison: "Gar",
  u_bridge: "Br",
  u_guard: "Gd",
  u_police: "Pol",
};

export function renderMap(root: HTMLElement, st: UiState, ui: UiActions): void {
  const w = st.world;
  const truth = st.debugTruth;
  const svg = s("svg", { viewBox: "0 0 1000 700", class: "map", role: "img", "aria-label": "Map of Castellane" });

  // River: a band running roughly north to south at x = 400 with a bend.
  svg.appendChild(s("path", { d: "M 430 0 C 380 120, 420 260, 400 380 C 385 480, 360 600, 390 700 L 450 700 C 420 600, 445 480, 460 380 C 480 260, 440 120, 490 0 Z", class: "river" }));
  // Bridge deck.
  svg.appendChild(s("rect", { x: 392, y: 400, width: 70, height: 16, class: "bridge-deck" }));

  const known = (key: string) => w.player.knowledge[key];

  for (const loc of Object.values(w.locations)) {
    const isDistrict = loc.kind === "district";
    let control: Faction;
    if (truth) control = loc.control;
    else {
      const k = known(K.control(loc.id));
      control = k ? (k.value as Faction) : duskControl(loc);
    }
    const g = s("g", { class: `loc ${control}${isDistrict ? " district" : ""}${loc.id === "loc_exchange" ? " here" : ""}` });
    g.appendChild(s("circle", { cx: loc.x, cy: loc.y, r: isDistrict ? 7 : 13, class: "loc-dot" }));
    if (loc.id === "loc_exchange") g.appendChild(s("circle", { cx: loc.x, cy: loc.y, r: 19, class: "loc-ring" }));
    g.appendChild(s("text", { x: loc.x, y: loc.y + (isDistrict ? 20 : 30), class: `loc-label${isDistrict ? " small" : ""}`, "text-anchor": "middle" }, shortName(loc)));
    const t = s("title", {}, `${loc.name}: ${truth ? "truly" : "as far as you know"} held by ${factionWord(control)}`);
    g.appendChild(t);
    svg.appendChild(g);
  }

  // Bridge state.
  const bridgeKnown = truth ? w.facts[K.bridge] : known(K.bridge)?.value ?? "yes";
  if (bridgeKnown === "no") svg.appendChild(s("line", { x1: 392, y1: 396, x2: 462, y2: 420, class: "bridge-closed" }));

  // Units.
  const placed: Record<string, number> = {};
  for (const u of Object.values(w.units)) {
    let at: string | undefined;
    let moving = false;
    let stale = "";
    if (truth) {
      at = u.moving ? u.moving.to : u.at;
      moving = !!u.moving;
    } else {
      const k = known(K.unit(u.id));
      if (!k) continue;
      at = String(k.value);
      stale = ` (heard ${clock(k.minute)})`;
    }
    const loc = w.locations[at ?? ""];
    if (!loc) continue;
    const n = placed[loc.id] ?? 0;
    placed[loc.id] = n + 1;
    const x = loc.x + 18 + n * 26;
    const y = loc.y - 14;
    const side = unitSide(w, u);
    const g = s("g", { class: `unit ${side}${moving ? " moving" : ""}` });
    g.appendChild(s("rect", { x: x - 11, y: y - 8, width: 22, height: 16, rx: 2, class: "unit-box" }));
    g.appendChild(s("text", { x, y: y + 4, class: "unit-label", "text-anchor": "middle" }, UNIT_ABBR[u.id] ?? "U"));
    if (truth && u.moving) {
      const from = w.locations[u.moving.from]!;
      g.appendChild(s("line", { x1: from.x, y1: from.y, x2: loc.x, y2: loc.y, class: "unit-path" }));
    }
    g.appendChild(s("title", {}, `${u.name}${moving ? ", moving to" : ", at"} ${loc.name}${stale}`));
    svg.appendChild(g);
  }

  // President, if known to be elsewhere.
  const pres = truth ? w.facts[K.president] : known(K.president)?.value;
  if (pres && pres !== "loc_palace") {
    const loc = w.locations[String(pres)];
    const label = pres === "loc_fled" ? "President: fled" : `President here`;
    const x = loc ? loc.x : 900;
    const y = loc ? loc.y - 30 : 40;
    svg.appendChild(s("text", { x, y, class: "pres-label", "text-anchor": "middle" }, label));
  }

  // Keep the SVG stable between renders only if nothing changed? Cheap enough to rebuild: ~30 nodes.
  const legend = h(
    "div",
    { class: "map-legend" },
    h("span", { class: "swatch government" }, "government"),
    h("span", { class: "swatch plotters" }, "the coup"),
    h("span", { class: "swatch civil" }, "nobody"),
    h("button", { class: `act tiny${truth ? " active" : ""}`, title: "Debug: show the truth instead of what you have heard.", onclick: () => ui.toggleTruth() }, truth ? "truth" : "as heard"),
  );

  replaceChildren(root, h("h2", { class: "col-title" }, "Castellane"), svg, legend);
}

function duskControl(loc: Location): Faction {
  switch (loc.kind) {
    case "palace":
    case "ministry":
    case "prefecture":
    case "radio":
    case "barracks":
    case "fort":
    case "airfield":
    case "bridge":
    case "exchange":
      return "government";
    default:
      return "civil";
  }
}

function unitSide(w: World, u: Unit): Faction {
  const cmd = w.actors[u.commanderId]!;
  if (cmd.loyalty === "plotter") return "plotters";
  if (cmd.loyalty === "loyalist") return "government";
  return cmd.faction === "plotters" ? "plotters" : "government";
}

function factionWord(f: Faction): string {
  return f === "government" ? "the government" : f === "plotters" ? "the coup" : "no one in particular";
}

function shortName(loc: Location): string {
  return loc.name.replace(/^the /, "").replace(/^(St\. Oda's) Hospital$/, "$1").replace("Interior Ministry", "Ministry").replace("Central Exchange", "Exchange").replace("Courier offices", "Courier").replace("Fort Saint-Aurel", "Fort").replace("Kestrel Barracks", "Barracks").replace("Lantern Bridge", "Bridge");
}
