import type { ChronicleEntry, World } from "../sim/types";
import { clock } from "../sim/text";
import { h, pinnedToBottom, replaceChildren, scrollToBottom } from "./dom";
import type { UiState } from "./state";

/** The operator's logbook: the chronicle without the secret entries, newest at the bottom. */
export function renderLogbook(root: HTMLElement, st: UiState): void {
  const w = st.world;
  const entries = w.chronicle.filter((e) => !e.secret);
  const body = root.querySelector<HTMLElement>(".log-body");
  const wasPinned = body ? pinnedToBottom(body) : true;
  const list = h("div", { class: "log-body" }, entries.map((e) => logLine(w, e)));
  replaceChildren(root, h("h2", { class: "col-title" }, "Logbook"), list);
  if (wasPinned) scrollToBottom(list);
}

export function logLine(_w: World, e: ChronicleEntry): HTMLElement {
  const stamp = clock(e.minute);
  // Many entries already begin with the time; don't print it twice.
  const text = e.text.replace(/^\d\d:\d\d\.?\s+/, "");
  return h(
    "div",
    { class: `log-line kind-${e.kind}${e.fingerprint ? " fingerprint" : ""}${e.hand ? " hand" : ""}`, title: e.hand ? "In your own hand, not the record. You may be wrong." : undefined },
    h("span", { class: "log-time" }, stamp),
    h("span", { class: "log-text" }, text),
    e.fingerprint ? h("span", { class: "log-print", title: "Your fingerprint: a player action was the proximate cause." }, "✦") : e.hand ? h("span", { class: "log-print hand-mark", title: "In your own hand." }, "✎") : null,
  );
}
