import type { Call, Claim, World } from "../sim/types";
import { answerOptions, pendingCalls, reachable } from "../sim/game";
import { alternatives, describeKey, describeValue } from "../sim/beliefs";
import { clock, speakClaim, speakWant } from "../sim/text";
import { connectedCount } from "../sim/tick";
import { h, replaceChildren } from "./dom";
import type { UiActions, UiState } from "./state";

const ROLE_NAMES: Record<string, string> = {
  president: "President of the Republic",
  minister: "Interior Minister",
  prefect: "Prefect of Police",
  radio_director: "Director, State Radio",
  general: "Garrison commander",
  colonel: "Colonel, Armoured Regiment",
  airfield_major: "Major, Airfield Company",
  bridge_captain: "Captain, Bridge Company",
  guard_commandant: "Commandant, Presidential Guard",
  student_chair: "Student union chair",
  union_boss: "Rail union",
  archbishop: "Archbishop of Castellane",
  editor: "Editor, the Courier",
  hospital_director: "Director, St. Oda's",
  ambassador: "Ambassador",
  citizen: "Subscriber",
};

export function roleName(role: string): string {
  return ROLE_NAMES[role] ?? role;
}

/** The queue of lit lamps and the card for the selected call. */
export function renderCalls(root: HTMLElement, st: UiState, ui: UiActions): void {
  const w = st.world;
  const pending = pendingCalls(w);
  const selected = st.selectedCallId ? w.calls[st.selectedCallId] : undefined;

  const queue = h(
    "div",
    { class: "queue" },
    pending.length === 0
      ? h("div", { class: "queue-empty" }, w.status === "ended" ? "The board is dark." : "No lamps lit.")
      : pending.map((c) => queueItem(w, c, c.id === st.selectedCallId, ui)),
  );

  replaceChildren(root, queue, selected && pending.includes(selected) ? card(st, selected, ui) : null);
}

function queueItem(w: World, c: Call, selected: boolean, ui: UiActions): HTMLElement {
  const caller = w.actors[c.callerId]!;
  const waited = w.minute - c.placedAt;
  const stateText = c.state === "ringing" ? `ringing ${waited} min` : c.state === "held" ? `holding ${waited} min` : "message taken";
  return h(
    "button",
    { class: `queue-item ${c.state}${selected ? " selected" : ""}`, onclick: () => ui.selectCall(c.id) },
    h("span", { class: `queue-lamp ${c.state}` }),
    h("span", { class: "queue-who" }, caller.short),
    h("span", { class: "queue-for" }, c.requestedId === "operator" ? "for you" : `for ${w.actors[c.requestedId]?.short ?? "?"}`),
    h("span", { class: "queue-state" }, stateText),
  );
}

function card(st: UiState, c: Call, ui: UiActions): HTMLElement {
  const w = st.world;
  const caller = w.actors[c.callerId]!;
  const requested = w.actors[c.requestedId];
  const callerLoc = w.locations[caller.locationId]?.name ?? "";
  const urgent = c.intent.urgency > 0.7;

  const family = c.intent.tag === "family";
  const head = h(
    "div",
    { class: "card-head" },
    h("div", { class: "card-caller" }, h("span", { class: "card-name" }, family ? (w.family.where === "list" ? "Mother" : w.family.name) : caller.short), h("span", { class: "card-role" }, family ? (w.family.where === "list" ? "from home" : `${w.family.relation === "brother" ? "your brother" : "your son"}, ${callerLoc}`) : `${roleName(caller.role)}, ${callerLoc}`)),
    h(
      "div",
      { class: "card-asks" },
      c.requestedId === "operator"
        ? h("span", {}, "wants a word with the operator")
        : [h("span", { class: "card-asks-label" }, "asks for "), h("span", { class: "card-name" }, requested?.short ?? "?"), h("span", { class: "card-role" }, requested ? `, ${w.locations[requested.locationId]?.name ?? ""}` : "")],
    ),
  );

  const opening = h("blockquote", { class: "card-opening" }, `“${c.intent.opening}”`);
  const meta = h(
    "div",
    { class: "card-meta" },
    h("span", {}, `Lamp lit ${clock(c.placedAt)}`),
    urgent ? h("span", { class: "card-urgent" }, "urgent") : null,
    c.state === "held" ? h("span", {}, `On hold since ${clock(c.heldAt ?? c.placedAt)}`) : null,
    caller.need && c.intent.kind === "personal" ? h("span", { class: "card-need" }, `Wants to ${caller.need}.`) : null,
  );

  let body: HTMLElement;
  if (c.state === "message") body = relayPanel(st, c, ui);
  else if (c.intent.tag === "family") body = familyPanel(w, c, ui);
  else if (c.requestedId === "operator") body = answerPanel(w, c, ui);
  else body = routePanel(st, c, ui);

  return h("section", { class: `card ${c.state}` }, head, opening, meta, body);
}

function routePanel(st: UiState, c: Call, ui: UiActions): HTMLElement {
  const w = st.world;
  const requested = w.actors[c.requestedId];
  const busy = connectedCount(w) >= w.player.cordPairs;
  const why = reachable(w, c.requestedId);
  const cannot = busy ? "No free cord pair." : why;
  const misrouting = st.misrouteFor === c.id;

  const connect = h(
    "button",
    { class: "act act-connect", disabled: cannot ? true : undefined, title: cannot ?? `Plug ${w.actors[c.callerId]!.short} through to ${requested?.short ?? ""}`, onclick: () => ui.dispatch({ type: "connect", callId: c.id }) },
    "Connect",
  );
  const connectListen = h(
    "button",
    { class: "act act-connect", disabled: cannot ? true : undefined, title: cannot ?? "Plug them through and keep the headset on the line from the first word. Each minute carries a small chance of a click.", onclick: () => ui.connectAndListen(c.id) },
    "Connect and listen",
  );
  const hold = h(
    "button",
    { class: "act", disabled: c.state !== "ringing" ? true : undefined, title: "“All trunks are busy. Please hold.” The lamp stays lit; they may hang up.", onclick: () => ui.dispatch({ type: "hold", callId: c.id }) },
    "Hold",
  );
  const refuse = h(
    "button",
    { class: "act act-refuse", title: "“I'm sorry, that line is down.” They will believe it for a while.", onclick: () => ui.dispatch({ type: "refuse", callId: c.id }) },
    "Line is down",
  );
  const message = h(
    "button",
    { class: "act", title: "“I can't raise them. Give me the message and I'll pass it on.” You hear everything they wanted to say.", onclick: () => ui.dispatch({ type: "take_message", callId: c.id }) },
    "Take a message",
  );
  const misroute = h(
    "button",
    { class: `act${misrouting ? " active" : ""}`, disabled: busy ? true : undefined, title: busy ? "No free cord pair." : "Plug them through to someone else. The wrong party hears their opening words.", onclick: () => ui.beginMisroute(misrouting ? null : c.id) },
    misrouting ? "Cancel misroute" : "Misroute…",
  );

  return h(
    "div",
    { class: "card-actions" },
    cannot ? h("div", { class: "card-note" }, cannot) : null,
    misrouting ? h("div", { class: "card-note hint" }, "Choose a jack on the board.") : null,
    h("div", { class: "act-row" }, connect, connectListen, hold, refuse),
    h("div", { class: "act-row" }, message, misroute),
  );
}

function familyPanel(w: World, c: Call, ui: UiActions): HTMLElement {
  const f = w.family;
  const reply = f.where === "bridge" ? "“Keep your head down. I won't tell her.”" : f.where === "square" ? "“Stay where you are. Please.”" : "“It's nothing, Mother. Go to bed.”";
  return h(
    "div",
    { class: "card-actions" },
    h("div", { class: "card-note" }, "This one is yours. Nobody else on the board knows that."),
    h("div", { class: "act-row" }, h("button", { class: "act act-connect act-say", onclick: () => ui.dispatch({ type: "answer", callId: c.id, answer: "unknown" }) }, reply)),
  );
}

function answerPanel(w: World, c: Call, ui: UiActions): HTMLElement {
  const opts = answerOptions(w, c);
  const key = c.intent.askKey ?? "coup:underway";
  const heard = w.player.knowledge[key];
  return h(
    "div",
    { class: "card-actions" },
    h("div", { class: "card-note" }, `They want to know ${describeKey(w, key)}.`, heard ? ` You last heard it was ${describeValue(w, key, heard.value)} (${clock(heard.minute)}).` : " You have heard nothing about it."),
    h(
      "div",
      { class: "act-col" },
      h("button", { class: "act", onclick: () => ui.dispatch({ type: "answer", callId: c.id, answer: "unknown" }) }, "“I'm only the operator. I don't know.”"),
      opts.map((o) =>
        h(
          "button",
          { class: `act act-say${o.known ? " known" : ""}`, title: o.known ? "This is what you have heard." : "You have no grounds for this.", onclick: () => ui.dispatch({ type: "answer", callId: c.id, answer: o.claim }) },
          `“${capFirst(describeKey(w, key))} is ${o.label}.”`,
        ),
      ),
    ),
    h("div", { class: "act-row" }, h("button", { class: "act act-refuse", onclick: () => ui.dispatch({ type: "refuse", callId: c.id }) }, "Hang up on them")),
  );
}

function relayPanel(st: UiState, c: Call, ui: UiActions): HTMLElement {
  const w = st.world;
  const caller = w.actors[c.callerId]!;
  const requested = w.actors[c.requestedId];
  const draft = st.relayDrafts[c.id] ?? {};
  const claims: Claim[] = c.intent.claims.map((cl, i) => ({ key: cl.key, value: draft[i] ?? cl.value }));
  const altered = claims.some((cl, i) => cl.value !== c.intent.claims[i]!.value);
  const why = requested ? reachable(w, requested.id) : "No such line.";

  const rows = c.intent.claims.map((cl, i) => {
    const alts = alternatives(w, cl.key);
    const current = draft[i] ?? cl.value;
    const select = h("select", {
      class: `relay-select${current !== cl.value ? " altered" : ""}`,
      onchange: (e: Event) => {
        const v = (e.target as HTMLSelectElement).value;
        ui.setRelayDraft(c.id, i, typeof cl.value === "number" ? Number(v) : v);
      },
    });
    const values = alts.includes(cl.value) ? alts : [cl.value, ...alts];
    for (const v of values) {
      const opt = h("option", { value: String(v), selected: v === current ? true : undefined }, describeValue(w, cl.key, v) + (v === cl.value ? " (as said)" : ""));
      select.appendChild(opt);
    }
    return h("div", { class: "relay-row" }, h("span", { class: "relay-key" }, capFirst(describeKey(w, cl.key))), select);
  });

  const preview = claims.map((cl) => speakClaim(w, caller, cl)).join(" ") + (c.intent.want ? " " + speakWant(w, caller, c.intent.want) : "");

  const saidText = `${c.intent.claims.map((cl) => speakClaim(w, caller, cl)).join(" ")}${c.intent.want ? " " + speakWant(w, caller, c.intent.want) : ""}`.trim();
  return h(
    "div",
    { class: "card-actions relay" },
    h("div", { class: "card-note" }, saidText ? `${caller.short} said:` : `${caller.short} had nothing to pass on but the call itself.`),
    saidText ? h("blockquote", { class: "card-opening small" }, `“${saidText}”`) : null,
    rows.length ? h("div", { class: "relay-rows" }, h("div", { class: "card-note" }, "What you will tell them:"), rows) : null,
    rows.length ? h("blockquote", { class: `card-opening small${altered ? " altered" : ""}` }, `“Operator here. I have a message for you from ${caller.short}. ${preview}”`) : null,
    why ? h("div", { class: "card-note" }, `${requested?.short ?? "They"} cannot be rung right now: ${why}`) : null,
    h(
      "div",
      { class: "act-row" },
      h("button", { class: "act act-connect", disabled: why ? true : undefined, onclick: () => ui.dispatch({ type: "relay", callId: c.id, claims }) }, altered ? "Ring and relay, altered" : "Ring and relay"),
      h("button", { class: "act act-refuse", title: "Put the message in the drawer and forget it.", onclick: () => ui.dispatch({ type: "drop_message", callId: c.id }) }, "Drop it"),
    ),
  );
}

function capFirst(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}
