import type { Actor, Belief, BeliefSet, BeliefSource, Claim, Faction, Id, Minute, World } from "./types";

export const K = {
  control: (locId: Id) => `control:${locId}`,
  unit: (unitId: Id) => `unit:${unitId}`,
  president: "president:where",
  radio: "radio:voice",
  bridge: "bridge:open",
  loyalty: (actorId: Id) => `loyalty:${actorId}`,
  crowd: (locId: Id) => `crowd:${locId}`,
  curfew: "curfew",
  coup: "coup:underway",
};

export function truth(world: World, key: string): string | number | undefined {
  return world.facts[key];
}

export function believed(actor: Actor, key: string): string | number | undefined {
  return actor.beliefs[key]?.value;
}

export function belief(actor: Actor, key: string): Belief | undefined {
  return actor.beliefs[key];
}

/**
 * Adopt a claim into an actor's beliefs if it is credible enough to displace what is already there.
 * Returns true if the belief changed value.
 */
export function adopt(
  actor: Actor,
  claim: Claim,
  confidence: number,
  source: BeliefSource,
  minute: Minute,
  callId?: Id,
): boolean {
  if (confidence <= 0.05) return false;
  const existing = actor.beliefs[claim.key];
  if (existing) {
    // Direct observation only yields to newer direct observation.
    if (existing.source === "seen" && source !== "seen" && minute - existing.minute < 45) return false;
    // Beliefs fade: an old belief is easier to displace.
    const age = minute - existing.minute;
    const effective = existing.confidence * Math.max(0.35, 1 - age / 240);
    if (confidence < effective - 0.1 && existing.value !== claim.value) return false;
  }
  const changed = existing?.value !== claim.value;
  const b: Belief = { key: claim.key, value: claim.value, confidence: Math.min(1, confidence), source, minute };
  if (callId) b.callId = callId;
  actor.beliefs[claim.key] = b;
  return changed;
}

export function trustIn(actor: Actor, who: string): number {
  return actor.trust[who] ?? 0.4;
}

export function setTrust(actor: Actor, who: string, value: number): void {
  actor.trust[who] = Math.max(0, Math.min(1, value));
}

/** Which side does this actor believe is winning, if they have formed a view? */
export function believedWinner(actor: Actor): Faction | null {
  let score = 0; // positive favours plotters
  const radio = believed(actor, K.radio);
  if (radio === "plotters") score += 2;
  if (radio === "government") score -= 1;
  const pres = believed(actor, K.president);
  if (pres === "loc_embassy" || pres === "loc_fled") score += 2;
  if (pres === "loc_palace") score -= 0.5;
  const palace = believed(actor, K.control("loc_palace"));
  if (palace === "plotters") score += 3;
  if (palace === "government") score -= 1;
  const radioCtl = believed(actor, K.control("loc_radio"));
  if (radioCtl === "plotters") score += 1.5;
  if (radioCtl === "government") score -= 0.5;
  const general = believed(actor, K.loyalty("a_general"));
  if (general === "plotter") score += 2;
  if (general === "loyalist") score -= 2;
  if (believed(actor, K.coup) !== "yes") return null;
  if (score >= 2.5) return "plotters";
  if (score <= -1.5) return "government";
  return null;
}

/** Human-readable name for a fact value, used by text and the dossier. */
export function describeValue(world: World, key: string, value: string | number): string {
  if (key.startsWith("control:")) return factionName(value as Faction);
  if (key.startsWith("unit:")) return world.locations[value as string]?.name ?? String(value);
  if (key === K.president) {
    if (value === "loc_fled") return "out of the city";
    return world.locations[value as string]?.name ?? String(value);
  }
  if (key === K.radio) {
    if (value === "music") return "playing music";
    if (value === "silent") return "off the air";
    return `in ${factionName(value as Faction)} hands`;
  }
  if (key === K.bridge) return value === "yes" ? "open" : "closed";
  if (key.startsWith("loyalty:")) {
    if (value === "plotter") return "with the coup";
    if (value === "loyalist") return "with the government";
    return "undecided";
  }
  if (key.startsWith("crowd:")) return `${value} people`;
  if (key === K.curfew) return value === "yes" ? "in force" : "not declared";
  if (key === K.coup) return value === "yes" ? "under way" : "not happening";
  return String(value);
}

export function factionName(f: Faction): string {
  switch (f) {
    case "government":
      return "the government";
    case "plotters":
      return "the coup";
    case "civil":
      return "no one";
  }
}

export function describeKey(world: World, key: string): string {
  if (key.startsWith("control:")) return `who holds ${world.locations[key.slice(8)]?.name ?? key}`;
  if (key.startsWith("unit:")) return `where ${world.units[key.slice(5)]?.name ?? key} is`;
  if (key === K.president) return "where the President is";
  if (key === K.radio) return "who is on the radio";
  if (key === K.bridge) return "whether the bridge is open";
  if (key.startsWith("loyalty:")) return `where ${world.actors[key.slice(8)]?.short ?? key} stands`;
  if (key.startsWith("crowd:")) return `the crowd at ${world.locations[key.slice(6)]?.name ?? key}`;
  if (key === K.curfew) return "whether there is a curfew";
  if (key === K.coup) return "whether a coup is under way";
  return key;
}

/** Plausible alternative values for a claim key, used by the UI when the operator alters a message. */
export function alternatives(world: World, key: string): (string | number)[] {
  if (key.startsWith("control:")) return ["government", "plotters"];
  if (key.startsWith("unit:")) return Object.keys(world.locations).filter((id) => world.locations[id]!.kind !== "district");
  if (key === K.president) return ["loc_palace", "loc_embassy", "loc_ministry", "loc_barracks", "loc_fled"];
  if (key === K.radio) return ["government", "plotters", "music", "silent"];
  if (key === K.bridge) return ["yes", "no"];
  if (key.startsWith("loyalty:")) return ["loyalist", "plotter", "undecided"];
  if (key === K.curfew) return ["yes", "no"];
  if (key === K.coup) return ["yes", "no"];
  return [];
}

export function emptyBeliefs(): BeliefSet {
  return {};
}
