import type { Actor, Id, Location, World } from "./types";
import type { Rng } from "./rng";

/**
 * Who people are, as the exchange knows them. Portraits are what everyone on the night board knows; details are
 * the one thing this operator happens to know; tics are how they sound on the line. All generated once per night.
 */

export interface Dossier {
  portrait: string;
  detail: string;
  tic: string;
}

interface Spec {
  portrait: (a: Actor, p: Pron, w: WorldNames) => string;
  details: ((a: Actor, p: Pron, w: WorldNames) => string)[];
  tics: string[];
}

interface Pron {
  he: string;
  him: string;
  his: string;
}

/** Names the portraits refer to, resolved before the actors exist as a world. */
export interface WorldNames {
  minister: string;
  colonel: string;
  general: string;
  prefect: string;
  archbishop: string;
}

