const CITIZEN_DETAILS = [
  "Rings the exchange about once a month, usually about the gas.",
  "Has never been in the logbook before tonight.",
  "Knows your voice. Does not know your name.",
  "Rang once in March, the night of the Tannery Row, and hung up before you answered.",
  "Pays the telephone bill in coins at the Post Office counter, downstairs from you.",
];

export function makeDossier(rng: Rng, a: Actor, names: WorldNames, district: string): Dossier {
  const p: Pron = a.gender === "f" ? { he: "she", him: "her", his: "her" } : { he: "he", him: "him", his: "his" };
  const spec = SPECS[a.role];
  if (!spec) {
    return {
      portrait: `${a.name}, of ${district}. A subscriber.${a.need ? ` Tonight ${p.he} wants to ${a.need}.` : ""}`,
      detail: rng.pick(CITIZEN_DETAILS),
      tic: "",
    };
  }
  return {
    portrait: spec.portrait(a, p, names),
    detail: rng.pick(spec.details)(a, p, names),
    tic: rng.pick(spec.tics),
  };
}

export function describePlace(loc: Location): string {
  switch (loc.kind) {
    case "palace":
      return "The Palace. The President has not left it since 1959. The Guard holds the gates; the square in front takes six hundred people and has held them before.";
    case "ministry":
      return "The Interior Ministry. The decree lives here, and the list. The Minister's line is the busiest on the board after ten.";
    case "prefecture":
      return "The Prefecture. Ninety days without charge, renewable. The cells are in the basement; the Colonel's brother may or may not be in one.";
    case "radio":
      return "Radio House, west of the river. Whoever holds the building holds the bulletin. Tonight it is playing dance music.";
    case "barracks":
      return "Kestrel Barracks, on the hill above the better streets. The Garrison Battalion, eighty strong, and the General's horses.";
    case "fort":
      return "Fort Saint-Aurel, west of the river, named for a soldier saint. The Armoured Regiment, a hundred strong, with tanks from Aldermark.";
    case "airfield":
      return "The Airfield, west, forty minutes' flying from the passes. The Airfield Company and four aircraft. Under the Convention, Aldermark's for twenty years.";
    case "bridge":
      return "The Lantern Bridge, the only way across the Oriel. Two barriers, a guardroom with a telephone, and twenty-five men. You can see it from the window.";
    case "university":
      return "The University, west. The students meet at Gallows Green and keep a duplicator in a bathroom.";
    case "railyards":
      return "The Rail Yards. The union hall, the strike fund, the whistle that means everyone walks.";
    case "hospital":
      return "St. Oda's, named for a nurse saint. One ward takes gunshot wounds. The porters bring notes up your stairs.";
    case "embassy":
      return "The Embassy of Aldermark, east, with a flag on the car and the loan in the safe. Rooms on the second floor for guests who arrive with one suitcase.";
    case "cathedral":
      return "The Cathedral. The bells are rung at the right moment and not before.";
    case "newspaper":
      return "The Courier's offices. Two front pages set at all times: the bride and the widow.";
    case "exchange":
      return "The Central Exchange, three floors above the Post and Telegraph. You.";
    default:
      return `${cap(loc.name)}. A district. People who can afford a telephone, and tonight have reasons to use it.`;
  }
}

export function worldNames(actors: Record<Id, Actor>): WorldNames {
  return {
    minister: actors["a_minister"]!.short,
    colonel: actors["a_colonel"]!.short,
    general: actors["a_general"]!.short,
    prefect: actors["a_prefect"]!.short,
    archbishop: actors["a_archbishop"]!.short,
  };
}

function cap(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

export function voiceTic(world: World, a: Actor): string {
  return world.actors[a.id]?.dossier?.tic ?? "";
}
