import { clock } from "../sim/text";
import { h } from "./dom";
import type { UiActions, UiState } from "./state";

/** The hourly break card: five minutes away from the board, and what she heard. */
export function renderBreak(st: UiState, ui: UiActions): HTMLElement | null {
  if (st.activeBreak === null) return null;
  const b = st.world.breaks[st.activeBreak];
  if (!b) return null;
  const relief = st.world.operator.relief;
  return h(
    "div",
    { class: "modal-back soft" },
    h(
      "section",
      { class: "break paper", role: "dialog", "aria-modal": "true", "aria-label": "Break" },
      h("h1", { class: "break-title" }, `${clock(b.minute)}. ${relief} takes the board.`),
      h("p", { class: "break-sub muted" }, "Five minutes on the balcony. The regulations say the relief connects whatever is ringing, and she does."),
      h("div", { class: "break-lines" }, b.lines.map((l) => h("p", {}, l))),
      b.reliefConnected.length
        ? h("div", { class: "break-relief" }, h("h3", {}, "While you were away"), h("ul", { class: "dawn-list" }, b.reliefConnected.map((r) => h("li", {}, r))))
        : h("p", { class: "muted" }, `Nothing rang. ${relief} did her nails.`),
      h("div", { class: "dawn-actions" }, h("button", { class: "act act-connect", onclick: () => ui.endBreak() }, "Back to the board")),
    ),
  );
}
