import type { ChronicleEntry, World } from "../sim/types";
import { clock } from "../sim/text";
import { h } from "./dom";
import { logLine } from "./logbook";
import type { UiActions, UiState } from "./state";

const OUTCOME_TITLE = {
  coup_succeeded: "The coup has succeeded.",
  coup_failed: "The coup has failed.",
  standoff: "Dawn, and a standoff.",
} as const;

const FATE_TITLE = {
  unnoticed: "Nobody noticed you.",
  thanked: "You were thanked.",
  questioned: "You were questioned.",
  taken: "You were taken away.",
} as const;

/** The dawn summary, shown when the night ends. */
export function renderDawn(st: UiState, ui: UiActions): HTMLElement | null {
  const w = st.world;
  if (w.status !== "ended" || !w.ending || st.dawnDismissed) return null;
  const e = w.ending;
  const t = w.player.tally;
  const secrets = pickSecrets(w);

  return h(
    "div",
    { class: "modal-back" },
    h(
      "section",
      { class: "dawn paper", role: "dialog", "aria-modal": "true", "aria-label": "Dawn" },
      h("h1", { class: `dawn-title${e.ideal ? " ideal" : ""}` }, e.ideal ? "The night that did not happen." : e.removedAt !== undefined ? `Taken off the board at ${clock(e.removedAt)}.` : OUTCOME_TITLE[e.outcome]),
      h("h2", { class: "dawn-fate" }, e.ideal ? "Nobody died. Nobody was taken. Nobody noticed." : e.removedAt !== undefined ? OUTCOME_TITLE[e.outcome] : FATE_TITLE[e.fate]),
      h("p", { class: "dawn-summary" }, e.summary),
      h(
        "div",
        { class: "dawn-tally" },
        tally("connected", t.connected),
        tally("held", t.held),
        tally("refused", t.refused),
        tally("misrouted", t.misrouted),
        tally("listened", t.listened),
        tally("cut", t.cut),
        tally("messages", t.messagesTaken),
        tally("altered", t.messagesAltered),
        tally("answered", t.answered),
        tally("small mercies", t.smallMercies),
      ),
      e.morning.length ? h("h3", {}, "The morning after") : null,
      e.morning.length ? h("ul", { class: "dawn-list" }, e.morning.map((m) => h("li", {}, m))) : null,
      e.discovered.length ? h("h3", {}, "What they found out") : null,
      e.discovered.length ? h("ul", { class: "dawn-list cost" }, e.discovered.map((d) => h("li", {}, d.replace(/^\d\d:\d\d\s+/, "")))) : null,
      e.discovered.length === 0 ? h("p", { class: "dawn-note muted" }, "Nothing you did was noticed by the people who won.") : null,
      e.cost.length ? h("h3", {}, "The cost") : null,
      e.cost.length ? h("ul", { class: "dawn-list cost" }, e.cost.map((c) => h("li", {}, c))) : null,
      e.fingerprints.length ? h("h3", {}, "Your fingerprints") : null,
      e.fingerprints.length ? h("ul", { class: "dawn-list" }, e.fingerprints.map((f) => h("li", {}, f.replace(/^\d\d:\d\d\s+/, "")))) : null,
      secrets.length ? h("h3", {}, "What you never knew") : null,
      secrets.length ? h("div", { class: "dawn-secrets" }, secrets.map((s) => logLine(w, s))) : null,
      h("div", { class: "dawn-herword" }, h("span", { class: "who" }, `In her own hand. ${w.operator.name}, ${clock(w.minute)}.`), e.herWord),
      h(
        "div",
        { class: "dawn-actions" },
        h("button", { class: "act act-connect", onclick: () => ui.newNight() }, "Another night"),
        h("button", { class: "act", onclick: () => ui.newNight(st.seed) }, "Replay this seed"),
        h("button", { class: "act", onclick: () => ui.dismissDawn() }, "Look at the board"),
      ),
      h("div", { class: "dawn-seed muted" }, `Seed ${st.seed}`),
    ),
  );
}

function tally(label: string, n: number): HTMLElement {
  return h("span", { class: "tally" }, h("b", {}, String(n)), ` ${label}`);
}

const KIND_WEIGHT: Record<ChronicleEntry["kind"], number> = {
  control: 4,
  clash: 4,
  system: 3,
  move: 2,
  civil: 2,
  exchange: 2,
  radio: 1,
  call: 1,
};

/** Five to eight secret entries that explain the night, in time order. */
export function pickSecrets(w: World): ChronicleEntry[] {
  const secret = w.chronicle.filter((e) => e.secret);
  const scored = secret.map((e, i) => ({ e, i, score: KIND_WEIGHT[e.kind] + (e.text.includes("believes") ? -0.5 : 0) }));
  scored.sort((a, b) => b.score - a.score || a.i - b.i);
  const n = Math.min(8, Math.max(5, Math.min(secret.length, 8)));
  const chosen = scored.slice(0, n).sort((a, b) => a.i - b.i);
  return chosen.map((c) => c.e);
}
