import "./styles/main.css";
import type { Action, Id, World } from "./sim/types";
import { applyAction, newGame, pendingCalls } from "./sim/game";
import { Board } from "./ui/board";
import { renderCalls } from "./ui/callcard";
import { renderDawn } from "./ui/dawn";
import { renderBreak } from "./ui/break";
import { renderPrologue } from "./ui/prologue";
import { renderDossier } from "./ui/dossier";
import { renderFamily } from "./ui/family";
import { h, replaceChildren } from "./ui/dom";
import { renderHeadset } from "./ui/headset";
import { renderLogbook } from "./ui/logbook";
import { renderMap } from "./ui/map";
import type { Dispatch, Speed, UiActions, UiState } from "./ui/state";
import { renderTopbar } from "./ui/topbar";
import { BoardAudio } from "./ui/audio";

const MS_PER_MINUTE = 2500;

function randomSeed(): string {
  const words = ["lantern", "quay", "tram", "kestrel", "salt", "foundry", "cathedral", "copper", "midnight", "river", "rook", "ember", "gallows", "ferry", "varnish", "sparrow"];
  const a = words[Math.floor(Math.random() * words.length)]!;
  const b = words[Math.floor(Math.random() * words.length)]!;
  return `${a}-${b}-${Math.floor(Math.random() * 900 + 100)}`;
}

function seedFromUrl(): string | null {
  const s = new URLSearchParams(location.search).get("seed");
  return s && s.trim() ? s.trim() : null;
}

function freshState(seed: string): UiState {
  return {
    world: newGame(seed),
    seed,
    speed: 1,
    resumeSpeed: 1,
    selectedCallId: null,
    misrouteFor: null,
    relayDrafts: {},
    debugTruth: false,
    actions: [],
    seenChronicle: 0,
    rungFor: new Set(),
    dawnDismissed: false,
    seenBreaks: 0,
    activeBreak: null,
    prologue: true,
    dossier: null,
    notes: loadNotes(seed),
    lastListened: null,
  };
}

function loadNotes(seed: string): string {
  try {
    return localStorage.getItem(`hearsay-notes-${seed}`) ?? "";
  } catch {
    return "";
  }
}

function saveNotes(seed: string, text: string): void {
  try {
    localStorage.setItem(`hearsay-notes-${seed}`, text);
  } catch {
    /* private window or storage blocked: notes live for the session only */
  }
}

/* ------------------------------------------------------------------------------------------------ */

const app = document.getElementById("app")!;
const audio = new BoardAudio();

const topbar = h("header", { class: "topbar" });
const left = h("aside", { class: "col col-left" });
const mapEl = h("section", { class: "panel map-panel" });
const familyEl = h("section", { class: "panel family-panel paper hidden" });
const logEl = h("section", { class: "panel log-panel paper" });
left.append(mapEl, familyEl, logEl);
const center = h("main", { class: "col col-center" });
const boardWrap = h("section", { class: "board-wrap" });
const callsEl = h("section", { class: "panel calls-panel" });
center.append(boardWrap, callsEl);
const right = h("aside", { class: "col col-right panel paper headset-panel" });
const modalHost = h("div", { class: "modal-host" });
replaceChildren(app, topbar, h("div", { class: "columns" }, left, center, right), modalHost);

let st: UiState = freshState(seedFromUrl() ?? randomSeed());
st.speed = 0;
let board = new Board(st.world, uiActions());
boardWrap.appendChild(board.svg);

function uiActions(): UiActions {
  return {
    dispatch,
    selectCall(id: Id | null) {
      st.selectedCallId = id;
      st.misrouteFor = null;
      audio.unlock();
      render();
    },
    beginMisroute(id: Id | null) {
      st.misrouteFor = id;
      render();
    },
    setRelayDraft(callId, index, value) {
      const d = (st.relayDrafts[callId] ??= {});
      d[index] = value;
      render();
    },
    setSpeed(speed: Speed) {
      audio.unlock();
      st.speed = speed;
      if (speed !== 0) st.resumeSpeed = speed;
      render();
    },
    toggleTruth() {
      st.debugTruth = !st.debugTruth;
      render();
    },
    newNight(seed?: string) {
      const s = seed ?? randomSeed();
      const url = new URL(location.href);
      url.searchParams.set("seed", s);
      history.replaceState(null, "", url.toString());
      st = freshState(s);
      st.speed = 0;
      replaceChildren(boardWrap);
      board = new Board(st.world, uiActions());
      boardWrap.appendChild(board.svg);
      lastTick = performance.now();
      acc = 0;
      render();
    },
    dismissDawn() {
      st.dawnDismissed = true;
      render();
    },
    endBreak() {
      st.activeBreak = null;
      st.speed = st.resumeSpeed;
      lastTick = performance.now();
      acc = 0;
      render();
    },
    openDossier(page: string | null) {
      audio.unlock();
      const wasOpen = st.dossier !== null;
      st.dossier = page;
      if (page !== null && !wasOpen) {
        if (st.speed !== 0) st.resumeSpeed = st.speed;
        st.speed = 0;
      } else if (page === null && wasOpen && st.activeBreak === null && !st.prologue && st.world.status === "playing") {
        st.speed = st.resumeSpeed || 1;
        lastTick = performance.now();
        acc = 0;
      }
      render();
    },
    setNotes(text: string) {
      st.notes = text;
      saveNotes(st.seed, text);
    },
    connectAndListen(callId: Id) {
      dispatch({ type: "connect", callId });
      const c = st.world.calls[callId];
      if (c && c.state === "connected") dispatch({ type: "listen", callId });
    },
    showPrologue(show: boolean) {
      audio.unlock();
      st.prologue = show;
      if (show) {
        if (st.speed !== 0) st.resumeSpeed = st.speed;
        st.speed = 0;
      } else if (st.activeBreak === null && st.world.status === "playing") {
        st.speed = st.resumeSpeed || 1;
        lastTick = performance.now();
        acc = 0;
      }
      render();
    },
  };
}

/** A new break has been composed by the sim: the relief takes the board, then show the card. */
function takeBreakIfDue(): void {
  const w = st.world;
  if (w.breaks.length <= st.seenBreaks || w.status !== "playing") return;
  st.seenBreaks = w.breaks.length;
  st.actions.push({ minute: w.minute, action: { type: "break" } });
  applyAction(w, { type: "break" });
  worldSounds();
  st.activeBreak = w.breaks.length - 1;
  if (st.speed !== 0) st.resumeSpeed = st.speed;
  st.speed = 0;
  st.misrouteFor = null;
}

const ui = uiActions();

function dispatch(action: Action): void {
  audio.unlock();
  const before = snapshotForSound(st.world);
  st.actions.push({ minute: st.world.minute, action });
  applyAction(st.world, action);
  soundFor(action, before, st.world);
  if (action.type !== "tick") {
    st.misrouteFor = null;
    if (action.type === "relay" || action.type === "drop_message") delete st.relayDrafts[action.callId];
    if (action.type === "listen" && action.callId) st.lastListened = action.callId;
  }
  render();
}

function snapshotForSound(w: World): { connected: number } {
  return { connected: Object.values(w.calls).filter((c) => c.state === "connected").length };
}

function soundFor(action: Action, before: { connected: number }, w: World): void {
  const after = Object.values(w.calls).filter((c) => c.state === "connected").length;
  switch (action.type) {
    case "connect":
    case "misroute":
    case "relay":
      if (after > before.connected || action.type === "relay") audio.plug();
      else audio.click(0.3);
      break;
    case "cut":
      audio.unplug();
      break;
    case "tick":
    case "break":
      break;
    default:
      audio.click();
  }
}

/* ------------------------------------------------------------------------------------------------ */

function render(): void {
  const w = st.world;
  // Keep the selection on a call that can still be acted on.
  const pending = pendingCalls(w);
  if (!st.selectedCallId || !pending.some((c) => c.id === st.selectedCallId)) {
    st.selectedCallId = pending[0]?.id ?? null;
    if (st.misrouteFor && st.misrouteFor !== st.selectedCallId) st.misrouteFor = null;
  }
  if (w.status === "ended" && st.speed !== 0) st.speed = 0;

  renderTopbar(topbar, st, ui, { muted: audio.muted, toggleMute });
  board.render(st);
  renderCalls(callsEl, st, ui);
  renderHeadset(right, st, ui);
  renderMap(mapEl, st, ui);
  renderFamily(familyEl, st);
  renderLogbook(logEl, st);
  // Modals are built once so their fade-in does not restart on every render.
  const showDawn = w.status === "ended" && !!w.ending && !st.dawnDismissed;
  if (st.prologue) {
    if (!modalHost.querySelector(".prologue")) replaceChildren(modalHost, renderPrologue(st, ui));
  } else if (st.dossier !== null) {
    // The dossier re-renders on navigation; its page is part of the state.
    const open = modalHost.querySelector<HTMLElement>(".dossier");
    if (!open || open.dataset["page"] !== st.dossier) {
      const el = renderDossier(st, ui);
      el.querySelector<HTMLElement>(".dossier")!.dataset["page"] = st.dossier;
      replaceChildren(modalHost, el);
    }
  } else if (showDawn) {
    if (!modalHost.querySelector(".dawn")) replaceChildren(modalHost, renderDawn(st, ui));
  } else if (st.activeBreak !== null) {
    if (!modalHost.querySelector(".break")) replaceChildren(modalHost, renderBreak(st, ui));
  } else {
    replaceChildren(modalHost);
  }
  document.body.classList.toggle("paused", st.speed === 0 && w.status === "playing");
}

function toggleMute(): void {
  audio.unlock();
  audio.muted = !audio.muted;
  render();
}

/** Sounds that come from the world rather than the player's hand. */
function worldSounds(): void {
  const w = st.world;
  for (const c of pendingCalls(w)) {
    if (c.state === "ringing" && !st.rungFor.has(c.id)) {
      st.rungFor.add(c.id);
      audio.ring();
    }
  }
  for (let i = st.seenChronicle; i < w.chronicle.length; i++) {
    const e = w.chronicle[i]!;
    if (e.secret) continue;
    if (e.kind === "clash" || e.kind === "radio") audio.thud();
  }
  st.seenChronicle = w.chronicle.length;
}

/* ------------------------------------------------------------------------------------------------ */

let lastTick = performance.now();
let acc = 0;

function frame(now: number): void {
  const dt = now - lastTick;
  lastTick = now;
  if (st.speed > 0 && st.world.status === "playing" && document.visibilityState === "visible") {
    acc += dt * st.speed;
    let ticked = false;
    while (acc >= MS_PER_MINUTE && st.world.status === "playing") {
      acc -= MS_PER_MINUTE;
      st.actions.push({ minute: st.world.minute, action: { type: "tick" } });
      applyAction(st.world, { type: "tick" });
      ticked = true;
    }
    if (ticked) {
      worldSounds();
      takeBreakIfDue();
      render();
    }
  } else {
    acc = 0;
  }
  requestAnimationFrame(frame);
}

document.addEventListener("keydown", (e) => {
  if (e.target instanceof HTMLInputElement || e.target instanceof HTMLSelectElement) return;
  if (st.prologue) {
    if (e.key === " " || e.key === "Enter") {
      e.preventDefault();
      ui.showPrologue(false);
    }
    return;
  }
  if (e.target instanceof HTMLTextAreaElement) return;
  if (st.dossier !== null) {
    if (e.key === "Escape" || e.key === "d") ui.openDossier(null);
    return;
  }
  if (e.key === "d") {
    ui.openDossier("city");
    return;
  }
  if (st.activeBreak !== null) {
    if (e.key === " " || e.key === "Enter") {
      e.preventDefault();
      ui.endBreak();
    }
    return;
  }
  if (e.key === " ") {
    e.preventDefault();
    ui.setSpeed(st.speed === 0 ? st.resumeSpeed : 0);
  } else if (e.key === "Escape") {
    if (st.misrouteFor) ui.beginMisroute(null);
  } else if (e.key === "1") ui.setSpeed(1);
  else if (e.key === "2") ui.setSpeed(2);
});

// Debug handle for the console and for replays.
declare global {
  interface Window {
    hearsay: { state: () => UiState; actions: () => UiState["actions"]; select: (id: Id | null) => void; dispatch: Dispatch; ui: UiActions };
  }
}
window.hearsay = { state: () => st, actions: () => st.actions, select: (id) => ui.selectCall(id), dispatch, ui };

render();
requestAnimationFrame(frame);
