import type { Call, World } from "../sim/types";
import { liveCalls } from "../sim/game";
import { clock } from "../sim/text";
import { h, pinnedToBottom, replaceChildren, scrollToBottom } from "./dom";
import type { UiActions, UiState } from "./state";

/** Right column: the headset. Live calls, the transcript of the one you are listening to, cut and listen. */
export function renderHeadset(root: HTMLElement, st: UiState, ui: UiActions): void {
  const w = st.world;
  const live = liveCalls(w);
  const listening = live.find((c) => c.listening);

  const list = h(
    "div",
    { class: "live-list" },
    live.length === 0 ? h("div", { class: "muted" }, "No calls on the board.") : live.map((c) => liveItem(w, c, ui)),
  );

  const transcriptEl = root.querySelector<HTMLElement>(".transcript");
  const wasPinned = transcriptEl ? pinnedToBottom(transcriptEl) : true;

  // After a call ends, what you heard stays on the pad until you listen to something else.
  const last = !listening && st.lastListened ? w.calls[st.lastListened] : undefined;
  const transcript = h(
    "div",
    { class: "transcript" },
    listening
      ? transcriptLines(w, listening)
      : last && last.heardFrom !== undefined
        ? [h("div", { class: "muted headset-hook" }, last.state === "connected" ? "Headset on the hook. The line is still up." : `That call ended${last.endsAt !== null ? ` at ${clock(Math.min(last.endsAt, w.minute))}` : ""}. What you heard:`), transcriptLines(w, last)]
        : h("div", { class: "muted headset-hook" }, live.length ? "Headset on the hook. Choose a call to listen." : "Headset on the hook."),
  );

  replaceChildren(root, h("h2", { class: "col-title" }, "Headset"), list, transcript);
  if (wasPinned) scrollToBottom(transcript);
}

function liveItem(w: World, c: Call, ui: UiActions): HTMLElement {
  const caller = w.actors[c.callerId]!;
  const callee = w.actors[c.connectedToId!]!;
  const left = Math.max(0, (c.endsAt ?? w.minute) - w.minute);
  return h(
    "div",
    { class: `live-item${c.listening ? " listening" : ""}${c.misrouted ? " misrouted" : ""}` },
    h("div", { class: "live-who" }, h("span", {}, caller.short), h("span", { class: "live-arrow" }, c.misrouted ? " ⇢ " : " — "), h("span", {}, callee.short)),
    h("div", { class: "live-meta" }, `${clock(c.connectedAt ?? w.minute)} · ${left} min left${c.clickHeard ? " · they heard you" : ""}`),
    h(
      "div",
      { class: "live-actions" },
      h("button", { class: `act small${c.listening ? " active" : ""}`, title: "Monitor this line. Each minute carries a small chance of a tell-tale click.", onclick: () => ui.dispatch({ type: "listen", callId: c.listening ? null : c.id }) }, c.listening ? "Stop listening" : "Listen"),
      h("button", { class: "act small act-refuse", title: "Pull the cord. Both parties will notice.", onclick: () => ui.dispatch({ type: "cut", callId: c.id }) }, "Cut"),
    ),
  );
}

/** How many lines of each call have already been shown, so only new lines animate in. */
const shown = new Map<string, number>();

function transcriptLines(w: World, c: Call): HTMLElement[] {
  const from = c.heardFrom ?? 0;
  const lines = c.transcript.slice(from, c.spoken);
  const seen = shown.get(c.id) ?? from;
  const out: HTMLElement[] = [];
  out.push(h("div", { class: "transcript-head" }, `${w.actors[c.callerId]!.short} and ${w.actors[c.connectedToId!]!.short}`, from > 0 ? h("span", { class: "muted" }, " · you joined late") : null));
  if (lines.length === 0) out.push(h("div", { class: "muted" }, "Line crackle. Nobody has spoken yet."));
  lines.forEach((l, i) => {
    const who = l.speakerId === "operator" ? "You" : w.actors[l.speakerId]?.short ?? "?";
    const fresh = from + i >= seen;
    out.push(h("div", { class: `line${l.speakerId === "operator" ? " line-operator" : ""}` }, h("span", { class: "speaker" }, who), h("span", { class: `said${fresh ? " fresh" : ""}` }, l.text)));
  });
  shown.set(c.id, c.spoken);
  if (c.spoken >= c.transcript.length && c.state === "connected") out.push(h("div", { class: "muted" }, "They are ringing off."));
  return out;
}
