/* ------------------------------------------------------------------------------------------------
 * Voices. Index matches Actor.voice.
 * 0 military, 1 bureaucratic, 2 fervent, 3 anxious citizen, 4 urbane, 5 clerical
 * ---------------------------------------------------------------------------------------------- */

interface Voice {
  greet: (self: Actor) => string;
  agree: string[];
  refuse: string[];
  stall: string[];
  alarmed: string[];
  noted: string[];
  unknown: string[];
  close: string[];
}

