function voice(a: Actor): Voice {
  return VOICES[a.voice] ?? VOICES[1]!;
}

/** Deterministic pick from a list using call id and offset, so transcripts are stable. */
function pickLine(list: string[], salt: string, n: number): string {
  let h = n * 31;
  for (let i = 0; i < salt.length; i++) h = (h * 33 + salt.charCodeAt(i)) >>> 0;
  return list[h % list.length] ?? list[0] ?? "";
}

/* ------------------------------------------------------------------------------------------------
 * Claims as speech
 * ---------------------------------------------------------------------------------------------- */

export function speakClaim(world: World, speaker: Actor, claim: Claim): string {
  const v = claim.value;
  const side = speaker.loyalty === "plotter" ? "plotters" : speaker.loyalty === "loyalist" ? "government" : speaker.faction;
  const loc = (id: unknown) => world.locations[id as string]?.name ?? String(id);

  if (claim.key.startsWith("control:")) {
    const name = loc(claim.key.slice(8));
    if (v === side && side !== "civil") return `${cap(name)} is in our hands.`;
    if (v === "plotters") return side === "civil" ? `${cap(name)} has been taken by the army.` : `${cap(name)} has been taken by the rebels.`;
    if (v === "government") return side === "plotters" ? `${cap(name)} is still in the government's hands.` : `${cap(name)} is held by loyal troops.`;
    return `${cap(name)} is unguarded.`;
  }
  if (claim.key.startsWith("unit:")) {
    const unit = world.units[claim.key.slice(5)];
    const uname = unit?.name ?? "a unit";
    const moving = unit?.moving && unit.moving.to === v;
    return moving ? `${cap(uname)} is moving on ${loc(v)}.` : `${cap(uname)} is at ${loc(v)}.`;
  }
  if (claim.key === K.president) {
    if (speaker.role === "president") {
      if (v === "loc_embassy") return `I am at the Embassy.`;
      if (v === "loc_palace") return `I am still at the Palace, and I am staying.`;
      return `I am at ${loc(v)}.`;
    }
    if (v === "loc_fled") return `The President has left the country.`;
    if (v === "loc_embassy") return `The President has taken refuge at the Embassy.`;
    return `The President is at ${loc(v)}.`;
  }
  if (claim.key === K.radio) {
    if (v === side && side !== "civil") return `The radio is ours.`;
    if (v === "plotters") return `The rebels have the radio.`;
    if (v === "government") return `Radio House is still broadcasting for the government.`;
    if (v === "music") return `The radio is playing dance music as if nothing were happening.`;
    return `The radio has gone silent.`;
  }
  if (claim.key === K.bridge) return v === "yes" ? `The Lantern Bridge is open.` : `The Lantern Bridge is closed.`;
  if (claim.key.startsWith("loyalty:")) {
    if (claim.key.slice(8) === speaker.id) {
      if (v === "plotter") return side === "plotters" ? `I am with the Colonel.` : `I have gone over to the Colonel. Make of that what you like.`;
      if (v === "loyalist") return `I am with the government, and with the oath.`;
      return `I have not decided, and I will not be rushed.`;
    }
    const who = world.actors[claim.key.slice(8)]?.short ?? "someone";
    if ((v === "plotter" && side === "plotters") || (v === "loyalist" && side === "government")) return `${who} is with us.`;
    if (v === "plotter") return `${who} has gone over to the rebels.`;
    if (v === "loyalist") return `${who} stands with the government.`;
    return `${who} has not declared.`;
  }
  if (claim.key === K.curfew) return v === "yes" ? `A curfew has been declared.` : `No curfew has been declared.`;
  if (claim.key === K.coup) {
    if (v !== "yes") return side === "civil" ? `Nothing is happening tonight. The radio is playing.` : `Nothing is happening tonight.`;
    if (side === "plotters") return `It has begun.`;
    if (side === "government") return `The Regiment is in revolt.`;
    return `There are soldiers on the streets and nobody will say whose.`;
  }
  if (claim.key.startsWith("crowd:")) return `There are some ${v} people at ${loc(claim.key.slice(6))}.`;
  return `${claim.key} is ${String(v)}.`;
}

export function speakWant(world: World, speaker: Actor, want: NonNullable<Intent["want"]>): string {
  const loc = (id: unknown) => world.locations[id as string]?.name ?? String(id);
  const unit = want.unitId ? world.units[want.unitId] : undefined;
  const plotter = speaker.loyalty === "plotter";
  switch (want.action) {
    case "move":
      return speaker.role === "colonel"
        ? `Move ${unit?.name ?? "your men"} to ${loc(want.target)} and secure it. Nobody fires unless fired upon. I want that understood before a single engine starts.`
        : `Move ${unit?.name ?? "your men"} to ${loc(want.target)} and secure it.`;
    case "hold":
      return `Hold ${unit?.name ?? "your men"} where they are. Nobody moves without my word.`;
    case "close_bridge":
      return `Close the Lantern Bridge to all traffic. Nothing crosses tonight.`;
    case "open_bridge":
      return `Keep the bridge open. The Regiment will be crossing within the hour.`;
    case "broadcast":
      return plotter
        ? `You will put the proclamation on the air at the hour I give you, and nothing else.`
        : `Put out a bulletin at once: the government is in full control and a curfew is in force.`;
    case "arrest":
      if (want.target === "list") return `At first light, take the names on the list: ${listNames(world)}. Quietly, before the trams start.`;
      if (want.target === "government") return `Take the Interior Minister and the Prefect. Alive, and quietly, and before the trams start. Put them in the Fort.`;
      if (want.target === "a_colonel") return `Take ${world.actors["a_colonel"]!.short} at the Fort tonight. The Regiment will not fight for him now. Send a company and a warrant.`;
      return `Place him under arrest. Quietly.`;
    case "stand_down":
      return `Stand your men down. There is no need for blood tonight.`;
    case "mobilise":
      return `Get everyone you can to the Palace square. Now. Bring the lamps.`;
    case "shelter":
      return `Go to the Embassy. Tonight. Do not wait for morning.`;
  }
}

/* ------------------------------------------------------------------------------------------------
 * Openings: what the caller says to the operator when the lamp lights.
 * ---------------------------------------------------------------------------------------------- */

export function opening(world: World, caller: Actor, requestedId: Id, intent: Omit<Intent, "opening">): string {
  const target = world.actors[requestedId];
  const place = target ? world.locations[target.locationId]?.name ?? "" : "";
  const who = target ? target.short : "the operator";
  const urgent = intent.urgency > 0.7;
  const surname = caller.name.split(" ").pop() ?? caller.short;
  const hePron = target ? he(target) : "he";
  const himPron = target ? him(target) : "him";
  // Each role has its own way of asking. Variant by the call's tag, so the same person does not repeat himself.
  const byRole: Partial<Record<Actor["role"], string[]>> = {
    president: [`Operator, this is the President. ${who}, and quickly, please. I am sorry to keep you up.`, `The President speaking. Put me through to ${who}, and do not announce me; ${hePron} will know the voice.`],
    minister: [`Operator, the Interior Minister. ${cap(place)}, ${who}. Government priority, and I should like it noted that I said so.`, `Interior Ministry. Get me ${who}, stay off the line, and write down that I asked you to.`],
    prefect: [`Prefecture. Put me through to ${who}.`, `Operator, the Prefect. ${who}, and if the line is engaged, break in.`],
    radio_director: [`Radio House here, the Director. ${who}, please. It is rather urgent.`, `Operator, this is Radio House. I need ${who} before the next bulletin.`],
    general: [`General ${surname}. Get me ${who}.`, `Operator. ${cap(place)}, ${who}. This is the Garrison.`],
    colonel: [`Operator. ${cap(place)}, ${who}. Priority. Now.`, `${cap(place)}. ${who}. Don't make me say it twice.`],
    airfield_major: [`Airfield. Major ${surname}. ${who}, please.`, `Operator, the Airfield. Put me through to ${who}.`],
    bridge_captain: [`Bridge Company guardroom, Captain ${surname}. I need ${who}.`, `Operator, this is the bridge. ${who}, please. It's about the barriers.`],
    guard_commandant: [`Palace guardroom, the Commandant. ${who}, now.`, `Operator, the Commandant of the Guard. Get me ${who}.`],
    student_chair: [`Operator, can you get me ${place}? ${cap(who)}, if ${hePron}'s there.`, `${cap(place)}, please. Quick. ${cap(who)}.`],
    union_boss: [`The yards here. Get me ${who}.`, `Operator, this is the union hall. ${cap(place)}, ${who}. Tell ${himPron} it's the yards.`],
    archbishop: [`Operator, this is the Archbishop's residence. ${cap(who)}, if you please.`, `The Archbishop's residence. His Grace would like ${who}.`],
    editor: [`The Courier, night desk. ${cap(who)}, please. I'll hold.`, `Operator, the Courier. I need ${who} before we go to press.`],
    hospital_director: [`St. Oda's, the Director. ${cap(who)}, please. It's about the ward.`, `Operator, the hospital. Get me ${who}.`],
    ambassador: [`Good evening, operator. The Embassy. ${cap(who)}, please. ${cap(place)}.`, `The Embassy here. Would you be kind enough to connect me with ${who}.`],
  };
  const variants = byRole[caller.role];
  if (variants && variants.length) {
    if (urgent) return variants[0]!;
    return pickLine(variants, intent.tag, 1);
  }
  switch (caller.voice) {
    case 0:
      return urgent ? `Operator. ${cap(place)}, ${who}. Priority. Now.` : `Operator. Get me ${who} at ${place}.`;
    case 1:
      return urgent ? `Operator, this is ${caller.short}. ${cap(place)}, immediately, this cannot wait.` : `Operator, ${caller.short}. Put me through to ${who}, please.`;
    case 2:
      return urgent ? `Operator! ${cap(place)}, quick, I need ${who}!` : `Operator, can you get me ${place}? ${cap(who)}, if ${target ? he(target) : "he"}'s there.`;
    case 4:
      return urgent ? `Operator, ${caller.short}. I need ${who} at once, if you would.` : `Good evening, operator. ${cap(who)}, please. ${cap(place)}.`;
    case 5:
      return `Operator, this is the Archbishop's residence. ${cap(who)}, if you please.`;
    default:
      return urgent ? `Operator, please, ${place}, I need ${who}, it's urgent.` : `Operator? ${cap(place)}, please. ${cap(who)}.`;
  }
}

/* ------------------------------------------------------------------------------------------------
 * Transcripts
 * ---------------------------------------------------------------------------------------------- */

export function composeTranscript(world: World, call: Call, response: Response): Line[] {
  const caller = world.actors[call.callerId]!;
  const callee = world.actors[call.connectedToId!]!;
  const lines: Line[] = [];
  const salt = call.id;
  const cv = voice(caller);
  const kv = voice(callee);
  // Lines are spaced so that a call can be read: the greeting in the minute of connection, then one line every
  // two minutes. The beat number passed in is kept for the order of lines only.
  const say = (_beat: number, speakerId: Id, text: string, claims?: Claim[]) => {
    const offset = lines.length === 0 ? 0 : 2 * lines.length - 1;
    const l: Line = { offset, speakerId, text };
    if (claims && claims.length) l.claims = claims;
    lines.push(l);
  };

  // People sound like themselves: a verbal habit shows in the greeting about half the time.
  const tic = callee.dossier?.tic;
  say(0, callee.id, tic && pickLine(["y", "n"], salt, 9) === "y" ? `${kv.greet(callee)} ${tic}` : kv.greet(callee));

  if (call.misrouted) {
    const first = call.intent.claims.slice(0, 2);
    const stated = first.map((c) => speakClaim(world, caller, c)).join(" ");
    const requested = world.actors[call.requestedId]?.short ?? "the party I asked for";
    say(0, caller.id, `${caller.short}. ${stated} ${stated ? "" : "Listen carefully. "}Now, as to tonight—`, first);
    say(1, callee.id, `This is ${callee.short}. Who is speaking?`);
    say(1, caller.id, `This isn't ${requested}. Operator! Operator, you have put me through to the wrong line.`);
    say(2, callee.id, pickLine(kv.alarmed, salt, 7));
    return lines;
  }

  const claimsText = (cs: Claim[]) => cs.map((c) => speakClaim(world, caller, c)).join(" ");
  const want = call.intent.want;

  switch (call.intent.kind) {
    case "order": {
      const situ = call.intent.claims.slice(0, 2);
      say(0, caller.id, `${selfIntro(world, caller)} ${claimsText(situ)}`.trim(), situ);
      const argued = caller.role === "minister" && callee.role === "general" ? `${world.story.ministerCase} ` : "";
      const tail =
        caller.role === "minister"
          ? "That is an order from the Ministry. You will have it in writing by morning, if there is a morning."
          : caller.role === "president"
            ? "I am asking you as your President, and I will not ask twice."
            : "Acknowledge.";
      say(1, caller.id, `${argued}${want ? speakWant(world, caller, want) : ""} ${tail}`.trim());
      say(2, callee.id, stanceLine(kv, response, salt, 2));
      const close =
        caller.role === "minister"
          ? response.stance === "agree"
            ? "Good. I have written down the time. Ring me when it is done, and ring me, not the Palace."
            : response.stance === "stall"
              ? "There is no time for that, and I shall note that there was no time for that."
              : "Then I shall remember this conversation, and I remember everything, which is my misfortune."
          : caller.role === "president"
            ? response.stance === "agree"
              ? "Thank you. Go carefully. I would like to still have a General in the morning."
              : response.stance === "stall"
                ? "Think, then. But think quickly, for my sake, and for your own."
                : "Then I have nothing to offer you but the morning, and I am not sure I have that."
            : caller.role === "colonel"
              ? response.stance === "agree"
                ? pickLine(["Good. Nobody gets hurt. Out.", "Good. Ring me when it is done, and tell me nobody was hurt."], salt, 3)
                : response.stance === "stall"
                  ? "There is no time. I would give you time if I had it."
                  : "Then stay where you are and keep your men indoors, and nothing will happen to them. That is a promise, not a threat."
              : response.stance === "agree"
                ? pickLine(["Good. Out.", "Good. You will hear from me.", "Very well. Out.", "Good. Ring me when it is done."], salt, 3)
                : response.stance === "stall"
                  ? pickLine(["There is no time for that. Do it.", "Confirmed by whom? There is nobody else. Do it."], salt, 3)
                  : pickLine(["You will answer for that in the morning.", "Then I have nothing more to say to you tonight."], salt, 3);
      say(3, caller.id, close);
      break;
    }
    case "persuade": {
      const cs = call.intent.claims.slice(0, 3);
      say(0, caller.id, `${selfIntro(world, caller)} Listen to me carefully. ${claimsText(cs)}`.trim(), cs);
      say(1, caller.id, appeal(world, caller, callee, want));
      say(2, callee.id, stanceLine(kv, response, salt, 2));
      const pclose =
        caller.role === "colonel"
          ? response.stance === "agree"
            ? "Then we understand each other, and nobody will be hurt. Goodnight."
            : response.stance === "stall"
              ? "Take the hour. I will still be here, and so will the gates."
              : "Then I am sorry for it. Keep your men indoors and nobody will come through your door tonight. You have my word."
          : caller.role === "president"
            ? response.stance === "agree"
              ? "Thank you. I shall not forget it, which is the only thing I can promise anyone tonight."
              : response.stance === "stall"
                ? "Think, then. I have been thinking for three years; I know how little it helps."
                : "I see. Then I was wrong about you, and I have been wrong about better men."
            : response.stance === "agree"
              ? "Then we understand each other. Goodnight."
              : response.stance === "stall"
                ? "Do not take too long. The city will not wait for you."
                : pickLine(["So be it.", "Then God help you.", "I had hoped for better."], salt, 4);
      say(3, caller.id, pclose);
      break;
    }
    case "inform": {
      const cs = call.intent.claims.slice(0, 3);
      say(0, caller.id, `${selfIntro(world, caller)} ${claimsText(cs)}`.trim(), cs);
      say(1, callee.id, stanceLine(kv, response, salt, 1));
      if (cs.length > 1) say(2, caller.id, pickLine(["I thought you should know.", "Do with that what you will.", "That is all I have."], salt, 2));
      say(3, callee.id, pickLine(kv.close, salt, 3));
      break;
    }
    case "ask": {
      const q =
        call.intent.askKey === K.loyalty(callee.id)
          ? `I need to know where you stand tonight. I will not ask you twice, and I will not tell anyone you were asked.`
          : call.intent.askKey
            ? describeQuestion(world, call.intent.askKey)
            : "What is happening?";
      say(0, caller.id, `${caller.short}. ${q}`);
      if (response.stance === "answer" && response.answerClaims?.length) {
        say(1, callee.id, response.answerClaims.map((c) => speakClaim(world, callee, c)).join(" "), response.answerClaims);
        say(2, caller.id, pickLine(["I see. Thank you.", "That is what I feared.", "Understood."], salt, 2));
      } else {
        say(1, callee.id, pickLine(kv.unknown, salt, 1));
        say(2, caller.id, pickLine(["Nobody does.", "Then we wait.", "If you hear anything, call me."], salt, 2));
      }
      say(3, callee.id, pickLine(kv.close, salt, 3));
      break;
    }
    case "request": {
      const cs = call.intent.claims.slice(0, 2);
      say(0, caller.id, `${caller.short}. ${claimsText(cs)}`.trim(), cs);
      say(1, caller.id, want ? `${speakWant(world, caller, want)} I am asking, not ordering. I have no right to order you.` : "I need your help tonight.");
      say(2, callee.id, stanceLine(kv, response, salt, 2));
      say(3, caller.id, response.stance === "agree" ? pickLine(["Thank you. I will not forget it.", "Thank you. Go carefully."], salt, 3) : pickLine(cv.close, salt, 3));
      break;
    }
    case "plead": {
      say(0, caller.id, plea(caller, callee));
      say(2, callee.id, pleaReply(callee, response, kv, salt));
      say(3, caller.id, pickLine(cv.close, salt, 3));
      break;
    }
    case "personal": {
      const cs = call.intent.claims.slice(0, 1);
      const spec = CITIZEN_NEEDS.find((n) => n.need === caller.need);
      say(0, caller.id, `${personalLead(caller)} ${spec?.speech ?? ""} ${claimsText(cs)}`.replace(/\s+/g, " ").trim(), cs);
      const resolution = spec?.resolution ?? personalResolution(callee);
      if (response.stance === "answer" && response.answerClaims?.length) {
        say(1, callee.id, `${resolution} ${response.answerClaims.map((c) => speakClaim(world, callee, c)).join(" ")}`.trim(), response.answerClaims);
      } else {
        say(1, callee.id, resolution);
      }
      say(2, caller.id, pickLine(["Thank you. Thank you.", "God bless you.", "All right. All right, I'll wait.", "Yes. Yes, I understand."], salt, 2));
      say(2, callee.id, pickLine(["Goodnight.", "Go to bed now.", "That is all I can tell you. Goodnight."], salt, 3));
      break;
    }
  }
  return lines;
}

/** How a caller names himself once the line is open. */
function selfIntro(world: World, caller: Actor): string {
  const loc = world.locations[caller.locationId]?.name ?? "";
  switch (caller.role) {
    case "colonel":
      return caller.locationId === "loc_palace" ? `${caller.short}, from the square.` : `${caller.short}, at ${loc}.`;
    case "minister":
      return `This is the Minister.`;
    case "president":
      return `This is the President.`;
    case "prefect":
      return `Prefecture. ${caller.short}.`;
    case "general":
      return `${caller.short}.`;
    case "archbishop":
      return `This is the Archbishop.`;
    default:
      return `${caller.short}.`;
  }
}

function stanceLine(v: Voice, r: Response, salt: string, n: number): string {
  switch (r.stance) {
    case "agree":
      return pickLine(v.agree, salt, n);
    case "refuse":
      return pickLine(v.refuse, salt, n);
    case "stall":
      return pickLine(v.stall, salt, n);
    case "alarmed":
      return pickLine(v.alarmed, salt, n);
    case "noted":
      return pickLine(v.noted, salt, n);
    case "unknown":
      return pickLine(v.unknown, salt, n);
    case "answer":
      return pickLine(v.noted, salt, n);
    case "confused":
      return "Who is this? What are you talking about?";
  }
}

function appeal(world: World, caller: Actor, callee: Actor, want: Intent["want"]): string {
  const plotter = caller.loyalty === "plotter";
  const wantText = want ? ` ${speakWant(world, caller, want)}` : "";
  if (plotter) {
    if (caller.role === "airfield_major" && callee.role === "general") {
      return `The Colonel asked me to tell you what he told you, General, and to add that Radio House is ours and the proclamation goes out on the hour. Hold the Garrison where it is and nobody at the barracks will be asked a single question in the morning.`;
    }
    switch (callee.role) {
      case "general":
        return `${world.story.colonelCase} Keep your men in barracks, General, and by morning you will have the Ministry of Defence. Nobody who stays in barracks tonight will be asked a single question tomorrow. You have my word on that, and you know what my word is worth, because we were in the same year.${wantText}`;
      case "guard_commandant":
        return `No one wants to fire on the Guard. The President will be treated with every courtesy. Open the gates and your men go home to their families.${wantText}`;
      case "bridge_captain":
        return `You are a soldier, Captain, and soldiers obey. The Regiment crosses at midnight on the President's own request to restore order.${wantText}`;
      case "radio_director":
        return `Your building will be in the hands of the army within the hour. Cooperate, and you will still have a job tomorrow.${wantText}`;
      default:
        return `Think of your position tomorrow, not tonight.${wantText}`;
    }
  }
  if (caller.role === "president" && callee.role === "general") {
    return `I did not ask for this office twice, General. I was given it once and I have kept it because every alternative I was shown had tanks in it. Stand with the Republic. I am not asking you to stand with me.${wantText}`;
  }
  switch (callee.role) {
    case "general":
      return `${world.story.ministerCase} Stand with the President, General. You are the only force in the city that can stop him.${wantText}`;
    case "bridge_captain":
      return `Captain, the Regiment is not acting on anyone's orders but its own. Hold the bridge and history will remember your name kindly.${wantText}`;
    case "union_boss":
      return `If the tanks reach the Palace there will be no unions by Monday. Get your people into the streets.${wantText}`;
    default:
      return `I am asking you to do the right thing while there is still time to do it.${wantText}`;
  }
}

/** The Colonel's answer to a plea tells the operator when a plea would work. */
export function pleaReply(callee: Actor, response: Response, kv: Voice, salt: string): string {
  if (callee.role === "colonel") {
    if (response.stance === "agree") return `Your Grace. I have been looking at the gates for an hour and I find I do not want to do it. Tell them to open them and nobody will be hurt. If they do not open them, I am going home.`;
    if (!(callee.done["standoff_palace"] ?? 0)) return `Not from the Fort, Your Grace. If you want to talk to me about blood, find me when I am looking at it.`;
    return `I hear you, Your Grace. I have only just arrived. Ask me again when I have had time to count the rifles on the gate.`;
  }
  return stanceLine(kv, response, salt, 2);
}

function plea(caller: Actor, callee: Actor): string {
  if (caller.role === "archbishop" && callee.role === "minister") {
    return `Minister. The names on your card. Two of them were baptised in my cathedral and the third I buried his father. It is over; you have won. Let the morning be quiet.`;
  }
  if (caller.role === "archbishop") {
    return callee.role === "colonel" || callee.role === "guard_commandant" || callee.role === "general"
      ? `My son, I beg you in God's name: whatever happens tonight, let there be no shooting. The city will remember who fired first.`
      : `I am calling everyone I can reach. Whatever is decided tonight, let it be decided without blood.`;
  }
  if (caller.role === "president") return `I am asking you as one man to another. Do not do this to your country.`;
  return `Please. I am begging you.`;
}

function personalLead(caller: Actor): string {
  return `This is ${caller.name}. I'm sorry to call so late.`;
}

function personalResolution(callee: Actor): string {
  switch (callee.role) {
    case "hospital_director":
      return `Your father is stable and sleeping. Come in the morning, and come by the Prefecture side, not the bridge.`;
    case "student_chair":
      return `He's here and he's safe. I'll tell him to call you. I can't promise he'll come home.`;
    case "prefect":
      return `Thank you. We'll send a car. Stay indoors and keep your lights off.`;
    case "guard_commandant":
      return `He's on the gate and he's well. I'll tell him you called. Now get off the line, madam, please.`;
    case "editor":
      return `Nobody knows yet. If you hear anything, call me back, I'll pay for it.`;
    case "ambassador":
      return `Stay where you are and keep your passport by the door. We will send for our nationals if we must.`;
    case "union_boss":
      return `Be at the yards at six whatever happens. If the whistle goes, we walk.`;
    case "archbishop":
      return `We shall ring the bells at the right moment, Father, and not before.`;
    default:
      return `I understand. I'll do what I can.`;
  }
}

export function describeQuestion(world: World, key: string): string {
  if (key === K.coup) return "Is it true? Is something happening tonight?";
  if (key === K.president) return "Where is the President? Is he safe?";
  if (key === K.bridge) return "Is the bridge open? Can I get across?";
  if (key === K.radio) return "Who has the radio?";
  if (key === K.curfew) return "Is there a curfew?";
  if (key.startsWith("control:")) return `Who holds ${world.locations[key.slice(8)]?.name ?? "it"} right now?`;
  if (key.startsWith("unit:")) return `Where is ${world.units[key.slice(5)]?.name ?? "the unit"}?`;
  if (key.startsWith("loyalty:")) return `Where does ${world.actors[key.slice(8)]?.short ?? "he"} stand tonight?`;
  return "What is happening?";
}

/** The operator relays a message taken earlier. */
export function composeRelay(world: World, call: Call, callee: Actor, claims: Claim[], want: Intent["want"], response: Response): Line[] {
  const caller = world.actors[call.callerId]!;
  const kv = voice(callee);
  const lines: Line[] = [];
  lines.push({ offset: 0, speakerId: callee.id, text: callee.dossier?.tic ? `${kv.greet(callee)} ${callee.dossier.tic}` : kv.greet(callee) });
  const body = claims.map((c) => speakClaim(world, caller, c)).join(" ");
  const wantText = want ? ` ${speakWant(world, caller, want)}` : "";
  const said =
    call.intent.kind === "plead"
      ? `${cap(he(caller))} asked me to say this, and to say it in ${his(caller)} words: "${plea(caller, callee)}"`
      : body || want
        ? `${cap(he(caller))} asked me to say: ${body}${wantText}`
        : `${cap(he(caller))} asked me to tell you ${he(caller)} called, and that it mattered.`;
  lines.push({ offset: 1, speakerId: "operator", text: `Operator here. I have a message for you from ${caller.short}. ${said}`.replace(/\s+/g, " ").trim(), claims });
  lines.push({ offset: 3, speakerId: callee.id, text: call.intent.kind === "plead" ? pleaReply(callee, response, kv, call.id) : stanceLine(kv, response, call.id, 5) });
  lines.push({ offset: 5, speakerId: "operator", text: `I'll note that you received it.` });
  return lines;
}

/** Brief line for the chronicle when a claim changes someone's mind. */
export function beliefChangeText(world: World, actor: Actor, claim: Claim): string {
  return `${actor.short} now believes ${describeBelief(world, actor, claim)}.`;
}

function describeBelief(world: World, actor: Actor, claim: Claim): string {
  const s = speakClaim(world, actor, claim);
  return s.charAt(0).toLowerCase() + s.slice(1).replace(/\.$/, "");
}

export function cap(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

/** Pronouns for a generated actor. */
export function he(a: Actor): string {
  return a.gender === "f" ? "she" : "he";
}
export function him(a: Actor): string {
  return a.gender === "f" ? "her" : "him";
}
export function his(a: Actor): string {
  return a.gender === "f" ? "her" : "his";
}

export function clock(minute: number): string {
  const total = (22 * 60 + Math.max(0, Math.floor(minute))) % (24 * 60);
  const h = Math.floor(total / 60);
  const m = total % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

export function knows(actor: Actor, key: string, value: string | number): boolean {
  return believed(actor, key) === value;
}
