import type { Grievance, Id, Story, World } from "./types";
import type { Rng } from "./rng";

/**
 * The grievance that gives the night its argument. One per night. The Colonel's case is real; so is the
 * Minister's answer. Text here is spoken in calls, read on the radio and printed in the morning edition.
 */

interface Spec {
  context: (colonelSurname: string) => string;
  colonelCase: (colonelSurname: string) => string;
  ministerCase: string;
  /** Clause in the proclamation after "the armed forces have assumed responsibility for the nation". */
  proclamation: string;
  /** Clause in the government bulletin. */
  bulletin: string;
  /** What the morning edition says about the promise, if the coup wins. */
  promise: string;
  /** Two things people are saying at ten o'clock. Rumour; never the word coup. */
  rumours: (colonelSurname: string) => string[];
}

const SPECS: Record<Grievance, Spec> = {
  election: {
    context: () => `It is three weeks since the President postponed the spring election for the second time, "until order is restored". The posters are still up on the Via Marina.`,
    colonelCase: () => `The man in the Palace has cancelled two elections and calls it order. The army will hold one in ninety days and go back to barracks.`,
    ministerCase: `A colonel with tanks does not hold elections. He holds the country.`,
    proclamation: `elections will be held within ninety days`,
    bulletin: `the election will be held when the streets are safe for it, and not before`,
    promise: `The proclamation says ninety days. Nobody in the city has a calendar that goes that far.`,
    rumours: () => [
      `The Regiment's weekend leave was cancelled on Thursday and nobody at the Fort will say why.`,
      `The posters for the election that is not being held have been torn down on the Via Marina and put back up twice.`,
    ],
  },
  tannery: {
    context: () => `In March the Prefecture's police fired on strikers on the Tannery Row. Eleven dead. The inquiry closed in June without a name in it.`,
    colonelCase: () => `Eleven people were shot in the street by the Prefect's men and nobody has answered for it. Somebody will answer for it tonight.`,
    ministerCase: `He is not avenging the Tannery Row. He is using it. Ask him what he will do with the Prefect's men once he has them.`,
    proclamation: `those responsible for the Tannery Row will be brought before a court`,
    bulletin: `the Tannery Row inquiry is closed and will not be reopened by men with rifles`,
    promise: `A court is promised for the Tannery Row. The judges have not been named.`,
    rumours: () => [
      `A lorry of the Regiment was seen on the Tannery Row on Sunday with its lights off, and the men in it were not in uniform.`,
      `The Prefect has moved his family to the lake. The night desk says it is for the air.`,
    ],
  },
  treaty: {
    context: () => `Last month the government signed the basing treaty. The Embassy's money is in the newspapers, the railways and, people say, the Ministry. The officer corps feels sold.`,
    colonelCase: () => `They have sold the harbour and the airfield to a foreign power for a loan. An army that permits that is not an army. It is a doorman.`,
    ministerCase: `Without the treaty there is no bread in the spring and he knows it. He would rather be a patriot in a famine.`,
    proclamation: `the basing treaty is void`,
    bulletin: `the treaty stands, and with it the loan that feeds the city`,
    promise: `The treaty is declared void. The Embassy has not yet said what it thinks of that.`,
    rumours: () => [
      `The Colonel sent his regrets to the Embassy's dinner on Thursday. He has never sent them before.`,
      `An Aldermark survey party has been measuring the harbour wall with a tape, and the harbour pilots have stopped talking to them.`,
    ],
  },
  brother: {
    context: (s) => `Deputy ${s}, the Colonel's brother, has been held at the Prefecture since July without a charge. His wife stands outside it every morning.`,
    colonelCase: (s) => `My brother has been in a cell since July for a speech. Tonight the cells open, one way or the other.`,
    ministerCase: `His brother was taken because the speech was a call to mutiny. Tonight is the proof of the charge.`,
    proclamation: `political prisoners are released tonight`,
    bulletin: `persons held under the emergency decree remain held`,
    promise: `The cells at the Prefecture are opened at seven. The Colonel's brother walks out first.`,
    rumours: (s) => [
      `The lights at Fort Saint-Aurel have been on past midnight all week.`,
      `Deputy ${s}'s wife was turned away from the Prefecture this morning with a different excuse from yesterday's.`,
    ],
  },
};

export function makeStory(rng: Rng, colonelSurname: string, candidates: Id[], mustInclude?: Id): Story {
  const grievance = rng.pick(["election", "tannery", "treaty", "brother"] as Grievance[]);
  const s = SPECS[grievance];
  let list = rng.shuffle([...candidates]).slice(0, rng.int(2, 3));
  if (mustInclude && !list.includes(mustInclude)) list = [mustInclude, ...list.slice(0, 2)];
  list.sort();
  return {
    grievance,
    context: s.context(colonelSurname),
    colonelCase: s.colonelCase(colonelSurname),
    ministerCase: s.ministerCase,
    proclamation: s.proclamation,
    bulletin: s.bulletin,
    promise: s.promise,
    rumours: s.rumours(colonelSurname),
    list,
  };
}

export function listNames(world: World): string {
  const names = world.story.list.map((id) => world.actors[id]?.short ?? id);
  if (names.length <= 1) return names.join("");
  return `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;
}
