import type { Actor, Call, World } from "../sim/types";
import { K, describeValue } from "../sim/beliefs";
import { describePlace } from "../sim/people";
import { clock } from "../sim/text";
import { h } from "./dom";
import { roleName } from "./callcard";
import type { UiActions, UiState } from "./state";

/**
 * The dossier: the back pages of the logbook. Who everyone is as the exchange knows them, what the operator
 * has heard tonight, every call of theirs she handled, the places, the city, and her own notes. Opening it
 * pauses the night.
 */

const GROUPS: { label: string; ids: (w: World) => string[] }[] = [
  { label: "The State", ids: () => ["a_president", "a_minister", "a_prefect", "a_commandant", "a_radio"] },
  { label: "The Army", ids: () => ["a_general", "a_colonel", "a_major", "a_captain"] },
  { label: "The City", ids: () => ["a_students", "a_union", "a_archbishop", "a_editor", "a_hospital", "a_ambassador"] },
  {
    label: "Subscribers",
    ids: (w) =>
      Object.values(w.actors)
        .filter((a) => a.role === "citizen" && a.id !== "a_family")
        .map((a) => a.id)
        .sort(),
  },
];

export function renderDossier(st: UiState, ui: UiActions): HTMLElement {
  const w = st.world;
  const page = st.dossier ?? "city";
  const nav = h(
    "nav",
    { class: "dossier-nav" },
    h("button", { class: `dossier-tab${page === "city" ? " active" : ""}`, onclick: () => ui.openDossier("city") }, "The city"),
    h("button", { class: `dossier-tab${page === "places" ? " active" : ""}`, onclick: () => ui.openDossier("places") }, "Places"),
    h("button", { class: `dossier-tab${page === "notes" ? " active" : ""}`, onclick: () => ui.openDossier("notes") }, "Your notes"),
    GROUPS.map((g) => [
      h("div", { class: "dossier-group" }, g.label),
      g.ids(w).map((id) => {
        const a = w.actors[id]!;
        const touched = callsOf(w, id).length > 0;
        return h("button", { class: `dossier-tab person${page === id ? " active" : ""}${touched ? " touched" : ""}${a.status !== "free" ? " gone" : ""}`, onclick: () => ui.openDossier(id) }, a.short);
      }),
    ]),
  );
  let body: HTMLElement;
  if (page === "city") body = cityPage(w);
  else if (page === "places") body = placesPage(w);
  else if (page === "notes") body = notesPage(st, ui);
  else body = personPage(w, w.actors[page]!);

  return h(
    "div",
    { class: "modal-back" },
    h(
      "section",
      { class: "dossier paper", role: "dialog", "aria-modal": "true", "aria-label": "Dossier" },
      h("div", { class: "dossier-head" }, h("h1", { class: "dossier-title" }, "The back pages"), h("span", { class: "muted" }, `${clock(w.minute)} · the night is paused`), h("button", { class: "act", onclick: () => ui.openDossier(null) }, "Back to the board")),
      h("div", { class: "dossier-body" }, nav, h("div", { class: "dossier-page" }, body)),
    ),
  );
}

function callsOf(w: World, id: string): Call[] {
  return Object.values(w.calls)
    .filter((c) => (c.callerId === id || c.requestedId === id || c.connectedToId === id) && c.state !== "ringing" && c.state !== "held")
    .sort((a, b) => a.placedAt - b.placedAt);
}

function personPage(w: World, a: Actor): HTMLElement {
  const loc = w.locations[a.locationId];
  const heard: HTMLElement[] = [];
  const kLoy = w.player.knowledge[K.loyalty(a.id)];
  if (kLoy) heard.push(h("li", {}, `${clock(kLoy.minute)}: ${a.short} is ${describeValue(w, K.loyalty(a.id), kLoy.value)}.`));
  const unit = Object.values(w.units).find((u) => u.commanderId === a.id);
  if (unit) {
    const kU = w.player.knowledge[K.unit(unit.id)];
    if (kU) heard.push(h("li", {}, `${clock(kU.minute)}: ${unit.name} at ${describeValue(w, K.unit(unit.id), kU.value)}.`));
  }
  if (a.role === "president") {
    const kP = w.player.knowledge[K.president];
    if (kP) heard.push(h("li", {}, `${clock(kP.minute)}: the President is ${describeValue(w, K.president, kP.value)}.`));
  }
  for (const e of w.chronicle) {
    if (e.secret || !e.actorIds.includes(a.id) || e.kind === "call") continue;
    heard.push(h("li", {}, `${clock(e.minute)}: ${e.text.replace(/^\d\d:\d\d\.?\s+/, "")}`));
  }
  const calls = callsOf(w, a.id).map((c) => {
    const caller = w.actors[c.callerId]!;
    const other = c.callerId === a.id ? (w.actors[c.requestedId]?.short ?? "you") : caller.short;
    const dir = c.callerId === a.id ? `rang ${other}` : `was rung by ${other}`;
    const what =
      c.state === "connected"
        ? "on the line now"
        : c.state === "ended" && c.misrouted
          ? `put through to ${w.actors[c.connectedToId!]?.short} instead`
          : c.state === "ended" && c.relayed
            ? "a message, passed on"
            : c.state === "ended"
              ? "connected"
              : c.state === "refused"
                ? "told the line was down"
                : c.state === "abandoned"
                  ? "rang off unanswered"
                  : c.state === "cut"
                    ? "cut"
                    : c.state === "message"
                      ? "a message, not yet passed on"
                      : c.state;
    const heardLine = c.heardFrom !== undefined && c.transcript[c.heardFrom] ? ` “${c.transcript[Math.min(c.spoken - 1, c.transcript.length - 1)]?.text ?? ""}”` : "";
    return h("li", {}, `${clock(c.placedAt)}: ${dir}. ${cap(what)}.`, c.heardFrom !== undefined ? h("span", { class: "muted" }, ` You listened.${heardLine}`) : null);
  });
  return h(
    "div",
    {},
    h("h2", { class: "dossier-name" }, a.short, h("span", { class: "card-role" }, `${roleName(a.role)}${loc ? `, ${loc.name}` : ""}${a.status === "arrested" ? " · under arrest" : a.locationId === "loc_embassy" && a.role !== "ambassador" ? " · at the Embassy" : ""}`)),
    h("p", { class: "dossier-portrait" }, a.dossier?.portrait ?? ""),
    a.dossier?.detail ? h("p", { class: "dossier-detail" }, a.dossier.detail) : null,
    h("h3", {}, "Heard tonight"),
    heard.length ? h("ul", { class: "dossier-list" }, heard) : h("p", { class: "muted" }, "Nothing yet."),
    h("h3", {}, "On the board"),
    calls.length ? h("ul", { class: "dossier-list" }, calls) : h("p", { class: "muted" }, "No calls yet."),
  );
}

function placesPage(w: World): HTMLElement {
  const named = Object.values(w.locations).filter((l) => l.kind !== "district");
  const districts = Object.values(w.locations).filter((l) => l.kind === "district");
  return h(
    "div",
    {},
    h("h2", { class: "dossier-name" }, "Castellane"),
    h("p", { class: "dossier-portrait" }, "Four hundred thousand people who have learned not to ask. The Oriel runs through the middle and the Lantern Bridge is the only way across. West: the Fort, the Airfield, Radio House, the yards, the University, the tanneries. East: the Palace, the Ministries, the Prefecture, the Barracks, the Cathedral, the Embassy, the hospital, the better streets. You are on the east bank, looking at the bridge."),
    h("ul", { class: "dossier-list places" }, named.map((l) => h("li", {}, h("b", {}, cap(l.name.replace(/^the /, ""))), ` ${describePlace(l)}`))),
    h("h3", {}, "Districts with subscribers tonight"),
    h("p", { class: "muted" }, districts.map((d) => cap(d.name.replace(/^the /, ""))).join(" · ")),
  );
}

function cityPage(w: World): HTMLElement {
  const s = w.story;
  return h(
    "div",
    {},
    h("h2", { class: "dossier-name" }, w.nightTitle),
    h("h3", {}, "The decree"),
    h("p", { class: "dossier-portrait" }, "In its third year. Declared for six months after the Tram Depot bomb in 1959 and renewed every six months since. The Prefecture may hold anyone for ninety days without charge, renewable. The Courier passes a censor. Unions need a licence. The radio belongs to the state. The night operator's logbook goes to the Prefecture every morning."),
    h("h3", {}, "What people are saying"),
    h("p", { class: "dossier-portrait" }, s.context),
    h("p", { class: "dossier-portrait" }, `${s.rumours[0]} ${s.rumours[1]} None of it is in the Courier, which is how you know it is true, or that somebody wants it believed.`),
    h("h3", {}, "Ten years of promises"),
    h("p", { class: "dossier-portrait" }, "1952: Marshal Vidal's Government of Public Order, after the food riots. Promised elections in a year; held them in three. 1955: the elected Reform Ministry, remembered by the students as the good one and by the officers as the weak one; fell in 1958 when the Compact banks called the loans. 1958: the Caretaker Ministry, which held an election the opposition boycotted and produced the present President. The Colonel's junta would be the fourth government in ten years. The last three also promised elections."),
    h("h3", {}, "The wider world"),
    h("p", { class: "dossier-portrait" }, "Seventeen years after the Northern War, two blocs and Meridia between them. The Compact, led by Aldermark: shipyards, banks, a navy, the academy that trained the officer corps, the Embassy on the east bank and the loan in its safe. It keeps friendly governments friendly and does not look closely at their Prefectures. The Union, across the eastern mountains: one party, land and justice promised, the Voice of the Mountains on the shortwave, and money in the rail union's strike fund. Neither wants Meridia. Both want the other not to have it. The harbour can hold a fleet; the Airfield is forty minutes' flying from the passes."),
    h("h3", {}, "Yours"),
    h("p", { class: "dossier-portrait" }, familyLine(w)),
  );
}

function familyLine(w: World): string {
  const f = w.family;
  if (f.knownAt === null) return `${w.operator.name}. Six years on the night board. Somebody you love is out in the night somewhere; you have not heard from them yet.`;
  const rel = f.relation === "brother" ? "your brother" : f.relation === "son" ? "your son" : "your lodger";
  const where = f.where === "bridge" ? "with the Bridge Company on the bridge" : f.where === "square" ? "at the University, and will go to the square if the union calls" : "asleep in the back room, and on a list at the Prefecture";
  return `${w.operator.name}. Six years on the night board. ${f.name}, ${rel}, is ${where}.`;
}

function notesPage(st: UiState, ui: UiActions): HTMLElement {
  const ta = h("textarea", { class: "dossier-notes", placeholder: "Pencil, in the margin. Nobody reads these but you. (The logbook is another matter.)", spellcheck: "false" }) as HTMLTextAreaElement;
  ta.value = st.notes;
  ta.addEventListener("input", () => ui.setNotes(ta.value));
  return h("div", {}, h("h2", { class: "dossier-name" }, "Your notes"), h("p", { class: "muted" }, "Kept for this night's seed. Who lied, who you owe, what you mean to do at the top of the hour."), ta);
}

function cap(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}
