/**
 * Procedural sounds for the board: relay click, plug, buzzer ring.
 * Everything is synthesised; there are no audio files. The context is created on the first user gesture.
 */
export class BoardAudio {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  muted = false;

  /** Call from a user gesture handler. */
  unlock(): void {
    if (this.ctx) {
      if (this.ctx.state === "suspended") void this.ctx.resume();
      return;
    }
    try {
      this.ctx = new AudioContext();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.5;
      this.master.connect(this.ctx.destination);
    } catch {
      this.ctx = null;
    }
  }

  private get out(): { ctx: AudioContext; master: GainNode } | null {
    if (!this.ctx || !this.master || this.muted) return null;
    return { ctx: this.ctx, master: this.master };
  }

  /** A relay closing: short filtered noise burst. */
  click(volume = 0.5): void {
    const o = this.out;
    if (!o) return;
    const { ctx, master } = o;
    const len = Math.floor(ctx.sampleRate * 0.03);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.exp(-i / (len * 0.18));
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const bp = ctx.createBiquadFilter();
    bp.type = "bandpass";
    bp.frequency.value = 1800;
    bp.Q.value = 0.9;
    const g = ctx.createGain();
    g.gain.value = volume;
    src.connect(bp).connect(g).connect(master);
    src.start();
  }

  /** A plug seated in a jack: two clicks, the second lower. */
  plug(): void {
    const o = this.out;
    if (!o) return;
    this.click(0.6);
    const { ctx, master } = o;
    const osc = ctx.createOscillator();
    osc.type = "triangle";
    osc.frequency.setValueAtTime(220, ctx.currentTime + 0.03);
    osc.frequency.exponentialRampToValueAtTime(90, ctx.currentTime + 0.09);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, ctx.currentTime + 0.03);
    g.gain.exponentialRampToValueAtTime(0.25, ctx.currentTime + 0.04);
    g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.1);
    osc.connect(g).connect(master);
    osc.start(ctx.currentTime + 0.03);
    osc.stop(ctx.currentTime + 0.11);
  }

  /** A cord pulled: a soft pop. */
  unplug(): void {
    const o = this.out;
    if (!o) return;
    const { ctx, master } = o;
    const osc = ctx.createOscillator();
    osc.type = "sine";
    osc.frequency.setValueAtTime(140, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(60, ctx.currentTime + 0.08);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.3, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.09);
    osc.connect(g).connect(master);
    osc.start();
    osc.stop(ctx.currentTime + 0.1);
  }

  /** The board buzzer: a low square wave with a 20 Hz tremolo. */
  ring(): void {
    const o = this.out;
    if (!o) return;
    const { ctx, master } = o;
    const t0 = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = "square";
    osc.frequency.value = 330;
    const trem = ctx.createOscillator();
    trem.type = "square";
    trem.frequency.value = 22;
    const tremGain = ctx.createGain();
    tremGain.gain.value = 0.5;
    const g = ctx.createGain();
    g.gain.value = 0.0;
    const lp = ctx.createBiquadFilter();
    lp.type = "lowpass";
    lp.frequency.value = 1400;
    trem.connect(tremGain).connect(g.gain);
    osc.connect(lp).connect(g).connect(master);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(0.12, t0 + 0.02);
    g.gain.setValueAtTime(0.12, t0 + 0.42);
    g.gain.linearRampToValueAtTime(0.0001, t0 + 0.48);
    osc.start(t0);
    trem.start(t0);
    osc.stop(t0 + 0.5);
    trem.stop(t0 + 0.5);
  }

  /** Something happened in the city: a low thud, used for shots and the proclamation. */
  thud(): void {
    const o = this.out;
    if (!o) return;
    const { ctx, master } = o;
    const osc = ctx.createOscillator();
    osc.type = "sine";
    osc.frequency.setValueAtTime(70, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(30, ctx.currentTime + 0.4);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.5, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.5);
    osc.connect(g).connect(master);
    osc.start();
    osc.stop(ctx.currentTime + 0.5);
  }
}
