import type { Actor, Call, ChronicleEntry, ChronicleKind, Claim, Faction, Id, Intent, NightOutcome, Unit, World } from "./types";
import { listNames } from "./story";
import { Rng } from "./rng";
import { K, adopt, believed, believedWinner, setTrust, trustIn } from "./beliefs";
import { commit, decideResponse, effectiveSide, travelsWithUnit, unitOf, wantsToCall, willComply } from "./ai";
import { clock, composeTranscript, him, his, speakClaim } from "./text";
import { crossesRiver, travelMinutes } from "./worldgen";

/* ------------------------------------------------------------------------------------------------
 * Chronicle helpers
 * ---------------------------------------------------------------------------------------------- */

export function log(world: World, kind: ChronicleKind, text: string, actorIds: Id[] = [], opts: { secret?: boolean; fingerprint?: boolean; discovery?: boolean; hand?: boolean } = {}): void {
  const e: ChronicleEntry = { minute: world.minute, kind, text, actorIds };
  if (opts.secret) e.secret = true;
  if (opts.fingerprint) e.fingerprint = true;
  if (opts.discovery) e.discovery = true;
  if (opts.hand) e.hand = true;
  world.chronicle.push(e);
}

/** What the radio is playing: the dance music is the night's clock. */
export function musicNow(world: World): string {
  const voice = world.facts[K.radio];
  if (voice === "plotters") return "a ballet, between readings of the proclamation";
  if (voice === "government") return "a waltz, between bulletins";
  if (voice === "silent") return "nothing. The dial hums";
  const m = world.minute;
  if (m < 90) return "the southern stations' dance music, the fast kind, the kind the Old Quay dances to";
  if (m < 180) return "waltzes now, slower, as if the band had been told something";
  if (m < 300) return "something orchestral and European, with a lot of strings";
  return "a slow symphony that nobody asked for";
}

export function newId(world: World, prefix: string): Id {
  return `${prefix}${world.nextId++}`;
}

/** The operator learns a fact: from a caller's words, the radio, or the window. */
export function operatorLearns(world: World, claim: Claim, source: string): void {
  adopt(
    { beliefs: world.player.knowledge } as unknown as Actor,
    claim,
    1,
    source as never,
    world.minute,
  );
}

/* ------------------------------------------------------------------------------------------------
 * Beliefs: hearing and seeing
 * ---------------------------------------------------------------------------------------------- */

/** A listener hears a claim from a speaker. */
export function hear(world: World, listener: Actor, claim: Claim, speakerId: Id | "exchange" | "radio" | "runner", confidence: number, callId?: Id): boolean {
  const changed = adopt(listener, claim, confidence, speakerId, world.minute, callId);
  if (changed) {
    const who = speakerId === "exchange" ? "the exchange" : speakerId === "radio" ? "the radio" : speakerId === "runner" ? "a runner" : world.actors[speakerId]?.short ?? speakerId;
    log(world, "call", `${listener.short} now believes: ${lower(speakClaim(world, listener, claim))} (from ${who}).`, [listener.id], { secret: true });
  }
  return changed;
}

/** An actor sees the truth of a fact. Contradictions cost someone trust. */
function see(world: World, actor: Actor, key: string, rng: Rng): void {
  const value = world.facts[key];
  if (value === undefined) return;
  const prior = actor.beliefs[key];
  if (prior && prior.value !== value && prior.source !== "seen") {
    deceived(world, actor, prior.source, prior.callId, key, rng);
  }
  actor.beliefs[key] = { key, value, confidence: 1, source: "seen", minute: world.minute };
}

function deceived(world: World, actor: Actor, source: Actor["beliefs"][string]["source"], callId: Id | undefined, key: string, rng: Rng): void {
  const call = callId ? world.calls[callId] : undefined;
  if (source === "exchange") {
    actor.suspicion = Math.min(100, actor.suspicion + 25);
    setTrust(actor, "exchange", trustIn(actor, "exchange") - 0.3);
    log(world, "exchange", `${actor.short} has caught the exchange in a lie about ${describeKeyShort(world, key)}.`, [actor.id], { fingerprint: true, discovery: true });
    return;
  }
  if (source === "radio") {
    setTrust(actor, "radio", trustIn(actor, "radio") - 0.2);
    return;
  }
  if (source === "runner" || source === "seen") return;
  const speaker = world.actors[source];
  if (!speaker) return;
  // Was the line tampered with, or did the speaker lie? Paranoid people blame the operator.
  const tampered = call && (call.misrouted || call.clickHeard || (call.relayed && call.relayed.altered));
  const blameExchange = tampered || rng.chance(actor.traits.paranoia * 0.35);
  if (blameExchange) {
    actor.suspicion = Math.min(100, actor.suspicion + (tampered ? 20 : 10));
    log(world, "exchange", `${actor.short} suspects the line was tampered with: what ${speaker.short} supposedly said about ${describeKeyShort(world, key)} was false.`, [actor.id, speaker.id], { secret: !tampered, discovery: true, fingerprint: !!tampered });
  } else {
    setTrust(actor, speaker.id, trustIn(actor, speaker.id) - 0.25);
    log(world, "call", `${actor.short} no longer trusts ${speaker.short}: the truth about ${describeKeyShort(world, key)} was otherwise.`, [actor.id, speaker.id], { secret: true });
  }
}

function describeKeyShort(world: World, key: string): string {
  if (key.startsWith("control:")) return world.locations[key.slice(8)]?.name ?? key;
  if (key.startsWith("unit:")) return world.units[key.slice(5)]?.name ?? key;
  if (key === K.president) return "the President";
  if (key === K.radio) return "the radio";
  if (key === K.bridge) return "the bridge";
  if (key.startsWith("loyalty:")) return world.actors[key.slice(8)]?.short ?? key;
  return key;
}

function observe(world: World, actor: Actor, rng: Rng): void {
  if (actor.status === "dead") return;
  const here = actor.locationId;
  see(world, actor, K.control(here), rng);
  see(world, actor, K.radio, rng);
  if (here === "loc_bridge") see(world, actor, K.bridge, rng);
  if (here === "loc_palace") see(world, actor, K.president, rng);
  for (const u of Object.values(world.units)) {
    if (!u.moving && u.at === here) see(world, actor, K.unit(u.id), rng);
    if (u.moving && u.moving.to === here && u.moving.eta - world.minute < 6) see(world, actor, K.unit(u.id), rng);
  }
  // Police patrols report movement on the streets after a few minutes.
  if (actor.role === "prefect") {
    for (const u of Object.values(world.units)) {
      if (u.moving && world.minute - (u.moving.eta - travelMinutes(world, u.moving.from, u.moving.to)) >= 5) {
        const key = K.unit(u.id);
        const prior = actor.beliefs[key];
        if (!prior || prior.value !== u.moving.to) {
          actor.beliefs[key] = { key, value: u.moving.to, confidence: 0.9, source: "seen", minute: world.minute };
          if (u.id === "u_regiment") actor.beliefs[K.coup] = { key: K.coup, value: "yes", confidence: 0.9, source: "seen", minute: world.minute };
          log(world, "move", `A police patrol reports ${u.name} on the move toward ${world.locations[u.moving.to]!.name}.`, [actor.id], { secret: true });
        }
      }
    }
  }
}

/* ------------------------------------------------------------------------------------------------
 * Units
 * ---------------------------------------------------------------------------------------------- */

export function sideOfUnit(world: World, unit: Unit): Faction {
  const cmd = world.actors[unit.commanderId]!;
  return effectiveSide(cmd) ?? (cmd.faction === "plotters" ? "plotters" : "government");
}

export function startMove(world: World, unit: Unit, target: Id, reason: string): void {
  if (unit.at === target) return;
  // Already on the way there: a second order does not restart the journey.
  if (unit.moving && (unit.moving.to === target || unit.moving.then === target)) return;
  const cross = crossesRiver(world, unit.at, target) && unit.at !== "loc_bridge" && target !== "loc_bridge";
  const firstLeg = cross ? "loc_bridge" : target;
  unit.moving = { from: unit.at, to: firstLeg, eta: world.minute + travelMinutes(world, unit.at, firstLeg), reason };
  if (cross) unit.moving.then = target;
  unit.orders = "secure";
  const cmd = world.actors[unit.commanderId]!;
  log(world, "move", `${cap(unit.name)} leaves ${world.locations[unit.at]!.name} for ${world.locations[target]!.name}. ${reason}`, [cmd.id], { secret: true });
  if (unit.id === "u_regiment") cmd.done["left_fort"] = world.minute;
}

function arrive(world: World, unit: Unit, rng: Rng): void {
  const m = unit.moving!;
  unit.at = m.to;
  unit.moving = null;
  const cmd = world.actors[unit.commanderId]!;
  if (travelsWithUnit(cmd)) cmd.locationId = unit.at;
  world.facts[K.unit(unit.id)] = unit.at;
  const side = sideOfUnit(world, unit);

  if (m.then) {
    // At the bridge, on the way somewhere else.
    const open = world.facts[K.bridge] === "yes";
    const defenders = unitsAt(world, "loc_bridge").filter((u) => u.id !== unit.id && sideOfUnit(world, u) !== side);
    if (open || defenders.length === 0) {
      let delay = 0;
      if (!open) {
        world.facts[K.bridge] = "yes";
        delay = 6;
        log(world, "move", `${cap(unit.name)} lifts the barriers and crosses the Lantern Bridge.`, [cmd.id], { secret: true });
        operatorSeesBridge(world);
      } else {
        log(world, "move", `${cap(unit.name)} crosses the Lantern Bridge.`, [cmd.id], { secret: true });
      }
      if (unit.id === "u_regiment") {
        log(world, "move", `From the window you see headlamps in column on the Lantern Bridge. Armour, by the sound of it.`, [], { hand: true });
        operatorLearns(world, { key: K.unit("u_regiment"), value: m.then }, "seen");
        operatorLearns(world, { key: K.coup, value: "yes" }, "seen");
      }
      unit.moving = { from: "loc_bridge", to: m.then, eta: world.minute + delay + travelMinutes(world, "loc_bridge", m.then), reason: m.reason };
      return;
    }
    confront(world, unit, "loc_bridge", m.then, rng);
    return;
  }
  const controller = world.facts[K.control(unit.at)] as Faction;
  if (controller === side || controller === "civil") {
    takeControl(world, unit, unit.at, side);
    return;
  }
  confront(world, unit, unit.at, null, rng);
}

function unitsAt(world: World, locId: Id): Unit[] {
  return Object.values(world.units).filter((u) => !u.moving && u.at === locId && u.strength > 0);
}

function takeControl(world: World, unit: Unit, locId: Id, side: Faction): void {
  const prev = world.facts[K.control(locId)];
  world.facts[K.control(locId)] = side;
  world.locations[locId]!.control = side;
  const cmd = world.actors[unit.commanderId]!;
  if (cmd.loyalty === "undecided") commit(world, cmd, side);
  if (prev !== side) {
    log(world, "control", `${cap(unit.name)} secures ${world.locations[locId]!.name} for ${side === "plotters" ? "the coup" : "the government"}.`, [cmd.id], { secret: true });
  }
  if (locId === "loc_radio") {
    const dir = world.actors["a_radio"]!;
    if (side === "plotters") {
      world.facts["radio:pending"] = "plotters";
      world.nextBulletinAt = Math.min(world.nextBulletinAt, Math.max(world.minute + 8, world.plan.proclamationAt));
      dir.done["under_guns"] = world.minute;
    } else {
      world.facts["radio:pending"] = "government";
      world.nextBulletinAt = Math.min(world.nextBulletinAt, world.minute + 8);
    }
  }
  if (locId === "loc_palace" && side === "plotters") {
    const pres = world.actors["a_president"]!;
    if (pres.locationId === "loc_palace") {
      pres.status = "arrested";
      log(world, "control", `The President is taken into custody in his own study.`, [pres.id], { secret: true });
    }
  }
  if (locId === "loc_bridge") {
    world.facts[K.bridge] = side === "plotters" ? "yes" : (world.facts[K.bridge] ?? "yes");
    operatorSeesBridge(world);
  }
}

function operatorSeesBridge(world: World): void {
  const open = world.facts[K.bridge] === "yes";
  const prev = world.player.knowledge[K.bridge]?.value;
  if (prev !== (open ? "yes" : "no")) {
    log(world, "move", open ? `From the window: the barriers on the Lantern Bridge are up again.` : `From the window: the barriers come down on the Lantern Bridge. Soldiers with lamps.`, [], { hand: true });
  }
  operatorLearns(world, { key: K.bridge, value: open ? "yes" : "no" }, "seen");
}

/** A unit arrives somewhere held by the other side. */
function confront(world: World, unit: Unit, locId: Id, then: Id | null, rng: Rng): void {
  const side = sideOfUnit(world, unit);
  const cmd = world.actors[unit.commanderId]!;
  const defenders = unitsAt(world, locId).filter((u) => u.id !== unit.id && sideOfUnit(world, u) !== side);
  const allies = unitsAt(world, locId).filter((u) => u.id !== unit.id && sideOfUnit(world, u) === side);
  const D = defenders.reduce((s, u) => s + u.strength, 0);
  const A = unit.strength + allies.reduce((s, u) => s + u.strength, 0);
  const crowd = Number(world.facts[K.crowd(locId)] ?? 0);
  const locName = world.locations[locId]!.name;

  // Defenders may stand aside. The undecided follow who they think is winning; the committed only if they
  // are not brave and believe their side has already lost. A loyalist Guard commandant holds the gates.
  const defCmd = defenders.length ? world.actors[defenders.sort((a, b) => b.strength - a.strength)[0]!.commanderId]! : null;
  // A Guard with no President behind the gates has nothing left to guard.
  const presidentGone = locId === "loc_palace" && world.facts[K.president] !== "loc_palace";
  const firmGuard = defCmd?.role === "guard_commandant" && defCmd.loyalty === "loyalist" && defCmd.traits.boldness >= 0.4 && !presidentGone;
  const standsAside =
    defCmd &&
    ((defCmd.done["stand_down"] ?? 0) > 0 ||
      (defCmd.loyalty === "undecided" && (believedWinner(defCmd) === side || A > 2.5 * D)) ||
      (defCmd.loyalty !== "undecided" && believedWinner(defCmd) === side && (defCmd.traits.boldness < 0.5 || presidentGone) && !firmGuard) ||
      (defCmd.traits.boldness < 0.3 && A > 2 * D && !firmGuard));

  if (defenders.length === 0 || standsAside) {
    if (defCmd) {
      log(world, "clash", `At ${locName}, ${defCmd.short} orders ${world.units[defenders[0]!.id]!.name} to stand aside. Not a shot is fired.`, [cmd.id, defCmd.id], { secret: true });
      if (defCmd.loyalty === "undecided") commit(world, defCmd, side);
      for (const d of defenders) d.orders = "hold";
    }
    if (crowd >= 300 && cmd.traits.boldness < 0.5 && locId === "loc_palace") {
      standoff(world, unit, locId, then, `A crowd of some ${crowd} fills the square and ${cmd.short} will not drive through them.`);
      return;
    }
    takeControl(world, unit, locId, side);
    if (then) {
      unit.moving = { from: locId, to: then, eta: world.minute + travelMinutes(world, locId, then), reason: unit.moving?.reason ?? "" };
    }
    return;
  }

  const peace = (cmd.done["peace"] ?? 0) > 0;
  const crowdBlocks = (crowd >= 300 && cmd.traits.boldness < 0.85) || crowd >= 500;
  // Firing on the Presidential Guard at the Palace gates is a bigger step than clearing a bridge. A colonel
  // who has sat in the square for over an hour with his proclamation on the air runs out of patience.
  const standoffSince = cmd.done[`standoff_${locId.slice(4)}`];
  const impatient = unit.id === "u_regiment" && standoffSince !== undefined && world.minute - standoffSince >= 75 && world.facts[K.radio] === "plotters" && cmd.traits.boldness > 0.6;
  const ratio = peace ? 3 : locId === "loc_palace" ? (impatient ? 1.5 : 2.0) : 1.6;
  const willForce = A > ratio * D && cmd.traits.boldness > 0.45 && !crowdBlocks;

  if (willForce) {
    world.facts["shots"] = Number(world.facts["shots"] ?? 0) + 1;
    world.casualties.push({ minute: world.minute, locId, unitId: unit.id, defenderUnitId: defenders[0]!.id });
    familyHarm(world, locId, defenders.map((d) => d.id), rng);
    for (const d of defenders) d.strength = Math.round(d.strength * 0.5);
    unit.strength = Math.max(5, Math.round(unit.strength - D * 0.3));
    const Dafter = defenders.reduce((s, u) => s + u.strength, 0);
    log(world, "clash", `You hear shots from the direction of ${locName}. Then more.`, []);
    operatorLearns(world, { key: K.coup, value: "yes" }, "seen");
    if (unit.strength > Dafter) {
      log(world, "clash", `${cap(unit.name)} forces ${locName}. ${defCmd!.short}'s men fall back. There are dead on the cobbles.`, [cmd.id, defCmd!.id], { secret: true });
      for (const d of defenders) d.orders = "hold";
      takeControl(world, unit, locId, side);
      // Clearing a fought-over bridge takes time.
      if (then) unit.moving = { from: locId, to: then, eta: world.minute + 12 + travelMinutes(world, locId, then), reason: unit.moving?.reason ?? "" };
    } else {
      log(world, "clash", `${cap(unit.name)} is repulsed at ${locName} and falls back toward ${world.locations[unitHome(unit)]!.name}.`, [cmd.id, defCmd!.id], { secret: true });
      unit.moving = { from: locId, to: unitHome(unit), eta: world.minute + travelMinutes(world, locId, unitHome(unit)), reason: "Repulsed." };
      unit.orders = "hold";
      cmd.done["repulsed"] = world.minute;
    }
    return;
  }
  standoff(world, unit, locId, then, crowdBlocks ? `A crowd of some ${crowd} stands between the armour and the gates.` : `${defCmd!.short} refuses to yield and ${cmd.short} will not fire first.`);
}

function unitHome(unit: Unit): Id {
  switch (unit.id) {
    case "u_regiment":
      return "loc_fort";
    case "u_airfield":
      return "loc_airfield";
    case "u_garrison":
      return "loc_barracks";
    case "u_bridge":
      return "loc_bridge";
    case "u_guard":
      return "loc_palace";
    default:
      return "loc_prefecture";
  }
}

function standoff(world: World, unit: Unit, locId: Id, then: Id | null, why: string): void {
  const cmd = world.actors[unit.commanderId]!;
  unit.orders = "secure";
  cmd.done[`standoff_${locId.slice(4)}`] = cmd.done[`standoff_${locId.slice(4)}`] ?? world.minute;
  if (then) cmd.done[`then_${locId.slice(4)}`] = 1;
  // Keyed by unit: two units can face each other in the same square, each with its own standoff.
  world.facts[`standoff:${unit.id}`] = then ?? "stay";
  // Units reconsider every quarter hour; only log when the situation is new or the reason has changed.
  const whyKey = `standoff:why:${unit.id}`;
  if (world.facts[whyKey] !== why) {
    world.facts[whyKey] = why;
    log(world, "clash", `Standoff at ${world.locations[locId]!.name}. ${why}`, [cmd.id], { secret: true });
  }
}

/** Every quarter hour, units in a standoff reconsider. */
function reconsiderStandoffs(world: World, rng: Rng): void {
  for (const unit of Object.values(world.units)) {
    if (unit.moving || unit.orders !== "secure") continue;
    const key = `standoff:${unit.id}`;
    const pending = world.facts[key];
    if (pending === undefined) continue;
    const side = sideOfUnit(world, unit);
    if (world.facts[K.control(unit.at)] === side) {
      delete world.facts[key];
      continue;
    }
    const cmd = world.actors[unit.commanderId]!;
    const started = cmd.done[`standoff_${unit.at.slice(4)}`] ?? world.minute;
    // Only the undecided take their cue from who seems to be winning; the committed look at the guns.
    const winner = cmd.loyalty === "undecided" ? believedWinner(cmd) : null;
    const defenders = unitsAt(world, unit.at).filter((u) => u.id !== unit.id && sideOfUnit(world, u) !== side);
    const allies = unitsAt(world, unit.at).filter((u) => u.id !== unit.id && sideOfUnit(world, u) === side);
    const D = defenders.reduce((s, u) => s + u.strength, 0);
    const A = unit.strength + allies.reduce((s, u) => s + u.strength, 0);
    const outgunned = D > 1.3 * A;
    const since = world.minute - started;
    const crowd = Number(world.facts[K.crowd(unit.at)] ?? 0);
    const peace = (cmd.done["peace"] ?? 0) > 0;
    const givesUp =
      (winner !== null && winner !== side) ||
      // A word given to the Archbishop is kept: with no way through without blood, he goes home.
      (peace && (outgunned || crowd >= 300 || since >= 60)) ||
      (outgunned && since >= 45 && rng.chance(0.4)) ||
      (crowd >= 300 && since >= 120 && rng.chance(0.3)) ||
      (since > 100 && cmd.traits.boldness < 0.55) ||
      (since > 150 && rng.chance(0.25 * (1 - cmd.traits.boldness))) ||
      (cmd.done["repulsed"] ?? 0) > 0;
    if (givesUp) {
      delete world.facts[key];
      unit.orders = "hold";
      const home = unitHome(unit);
      if (unit.id === "u_regiment") {
        cmd.done["stood_down"] = world.minute;
        const why = peace ? `He gave the Archbishop his word, and there is no way through the gates without breaking it.` : crowd >= 300 ? `${cmd.short} will not drive through the crowd, and the crowd will not go home.` : outgunned ? `The Garrison is in the square and the arithmetic is against him.` : `The night is going nowhere.`;
        log(world, "clash", `${cmd.short} orders the Regiment to stand down. ${why} The engines idle, then one by one they turn for the Fort.`, [cmd.id], { secret: true });
      } else {
        log(world, "clash", `${cmd.short} pulls ${unit.name} back from ${world.locations[unit.at]!.name}.`, [cmd.id], { secret: true });
      }
      unit.moving = { from: unit.at, to: home, eta: world.minute + travelMinutes(world, unit.at, home), reason: "Stood down." };
      continue;
    }
    delete world.facts[key];
    const then = pending === "stay" ? null : (pending as Id);
    confront(world, unit, unit.at, then, rng);
  }
}

/* ------------------------------------------------------------------------------------------------
 * Orders and requests being carried out
 * ---------------------------------------------------------------------------------------------- */

export function applyWant(world: World, actor: Actor, want: NonNullable<Intent["want"]>, fromId: Id, reason: string): void {
  const from = world.actors[fromId];
  const fromSide = from ? (effectiveSide(from) ?? from.faction) : "government";
  const unit = want.unitId ? world.units[want.unitId] : unitOf(world, actor);
  const commands = unit && unit.commanderId === actor.id;
  switch (want.action) {
    case "move":
      if (!commands || !want.target) return;
      if (actor.loyalty === "undecided" && fromSide !== "civil") commit(world, actor, fromSide);
      startMove(world, unit, want.target, reason);
      return;
    case "hold":
      if (!commands) return;
      if (actor.loyalty === "undecided" && fromSide !== "civil") commit(world, actor, fromSide);
      if (unit.moving) {
        log(world, "move", `${cap(unit.name)} turns back to ${world.locations[unit.moving.from]!.name}.`, [actor.id], { secret: true });
        unit.moving = { from: unit.moving.to, to: unit.moving.from, eta: world.minute + Math.max(5, Math.round((unit.moving.eta - world.minute) * 0.5)), reason: "Recalled." };
      }
      unit.orders = "hold";
      actor.done["holding"] = world.minute;
      return;
    case "close_bridge":
      if (actor.role !== "bridge_captain") return;
      if (actor.loyalty === "undecided") commit(world, actor, "government");
      if (world.facts[K.bridge] !== "no") {
        world.facts[K.bridge] = "no";
        log(world, "move", `The Bridge Company closes the Lantern Bridge. ${reason}`, [actor.id], { secret: true });
        operatorSeesBridge(world);
      }
      return;
    case "open_bridge":
      if (actor.role !== "bridge_captain") return;
      actor.done["let_cross"] = world.minute;
      if (world.facts[K.bridge] !== "yes") {
        world.facts[K.bridge] = "yes";
        log(world, "move", `The Bridge Company lifts the barriers on the Lantern Bridge. ${reason}`, [actor.id], { secret: true });
        operatorSeesBridge(world);
      }
      return;
    case "broadcast":
      if (actor.role !== "radio_director") return;
      if (fromSide === "plotters" && world.facts[K.control("loc_radio")] !== "plotters") {
        // Agreed in principle; the proclamation goes out when soldiers hold the building.
        actor.done["will_broadcast_plotters"] = world.minute;
        return;
      }
      world.facts["radio:pending"] = fromSide;
      world.nextBulletinAt = Math.min(world.nextBulletinAt, world.minute + 6);
      return;
    case "stand_down":
      if (!commands) return;
      actor.done["stand_down"] = world.minute;
      unit.orders = "hold";
      if (actor.loyalty === "undecided") commit(world, actor, "plotters");
      log(world, "move", `${actor.short} tells ${his(actor)} officers there will be no resistance at ${world.locations[unit.at]!.name}.`, [actor.id], { secret: true });
      return;
    case "mobilise":
      if (actor.role !== "union_boss" && actor.role !== "student_chair") return;
      world.facts["mobilise"] = world.minute;
      world.facts["mobilise:cap"] = actor.role === "union_boss" ? 600 : 250;
      log(world, "civil", `${actor.short} sends word along the yards: everyone to the Palace square.`, [actor.id], { secret: true });
      return;
    case "shelter":
      if (actor.locationId === "loc_embassy" || actor.status !== "free") return;
      if (actor.role === "president") {
        if (actor.locationId !== "loc_palace") return;
        actor.locationId = "loc_embassy";
        world.facts[K.president] = "loc_embassy";
        log(world, "control", `A black car leaves the Palace by the garden gate. The President is going to the Embassy.`, [actor.id], { secret: true });
        return;
      }
      actor.locationId = "loc_embassy";
      log(world, "control", `${actor.short} arrives at the Embassy with one suitcase and is shown to a room on the second floor.`, [actor.id], { secret: true });
      return;
    case "arrest": {
      if (want.target === "list") {
        if (actor.role !== "prefect") return;
        if (world.facts["list:ordered"] === undefined) {
          world.facts["list:ordered"] = world.minute;
          log(world, "civil", `The Prefect writes ${world.story.list.length} names on a card and puts it in his breast pocket. ${reason}`, [actor.id], { secret: true });
        }
        return;
      }
      // Named arrests take men and time. The Major sends a lorry; the General sends a company to the Fort.
      if (want.target === "government" && actor.role === "airfield_major") {
        world.facts["arrest:a_minister"] = world.minute + 35;
        world.facts["arrest:a_prefect"] = world.minute + 45;
        log(world, "move", `A lorry with eight men leaves Radio House for the Ministry. ${reason}`, [actor.id], { secret: true });
      } else if (want.target === "a_colonel" && actor.role === "general") {
        world.facts["arrest:a_colonel"] = world.minute + 40;
        log(world, "move", `A company of the Garrison leaves for Fort Saint-Aurel with a warrant. ${reason}`, [actor.id], { secret: true });
      }
      return;
    }
  }
}

/** Arrests ordered earlier are carried out. The operator sees a line go dead; the rest she learns at dawn. */
function arrests(world: World): void {
  for (const id of ["a_minister", "a_prefect", "a_colonel"]) {
    const key = `arrest:${id}`;
    const due = world.facts[key];
    if (due === undefined || world.minute < Number(due)) continue;
    delete world.facts[key];
    const a = world.actors[id]!;
    if (a.status !== "free") continue;
    if (id === "a_prefect" && world.facts["prefect:offered"] !== undefined) {
      log(world, "control", `The lorry does not stop at the Prefecture. ${a.short} has brought his lists to the new government and keeps his office.`, [a.id], { secret: true });
      continue;
    }
    const loc = world.locations[a.locationId]!;
    if (a.locationId === "loc_embassy") {
      log(world, "control", `They come for ${a.short} and find the room empty. The Embassy says nothing.`, [a.id], { secret: true });
      log(world, "exchange", `${clock(world.minute)} Somebody tries the ${id === "a_colonel" ? "Fort" : "Ministry"} line three times in ten minutes. Nobody answers.`, []);
      continue;
    }
    a.status = "arrested";
    const call = a.busyWith ? world.calls[a.busyWith] : undefined;
    if (call && call.state === "connected") {
      endCall(world, call, "cut");
      log(world, "exchange", `${clock(world.minute)} The line from ${loc.name} goes dead mid-sentence. Then the lamp goes out.`, [a.id]);
    } else {
      log(world, "exchange", `${clock(world.minute)} The lamp for ${loc.name} flickers and goes dead. Whoever was on that line is not on it any more.`, [a.id]);
    }
    log(world, "control", `${a.short} is arrested at ${loc.name}.`, [a.id], { secret: true });
  }
}

/* ------------------------------------------------------------------------------------------------
 * Calls
 * ---------------------------------------------------------------------------------------------- */

export function connectedCount(world: World): number {
  return Object.values(world.calls).filter((c) => c.state === "connected").length;
}

/** Connect a call (or misroute it). Returns false if it could not be connected. */
export function connectCall(world: World, call: Call, toId: Id, rng: Rng): boolean {
  const target = world.actors[toId];
  const caller = world.actors[call.callerId]!;
  if (!target || target.status !== "free" || target.busyWith || connectedCount(world) >= world.player.cordPairs) return false;
  const unit = unitOf(world, target);
  if (unit?.moving && travelsWithUnit(target)) return false;
  call.connectedToId = toId;
  call.misrouted = toId !== call.requestedId;
  call.state = "connected";
  call.connectedAt = world.minute;
  call.spoken = 0;
  const response = decideResponse(world, call, rng);
  call.response = response;
  call.transcript = composeTranscript(world, call, response);
  const last = call.transcript.reduce((m, l) => Math.max(m, l.offset), 0);
  call.endsAt = world.minute + last + 2;
  target.busyWith = call.id;
  caller.busyWith = call.id;
  if (call.misrouted) {
    caller.suspicion = Math.min(100, caller.suspicion + 12);
    target.suspicion = Math.min(100, target.suspicion + 6);
    log(world, "exchange", `${clock(world.minute)} You put ${caller.short} through to ${target.short} instead of ${world.actors[call.requestedId]?.short ?? "the party asked for"}.`, [caller.id, target.id], { fingerprint: true, discovery: true });
  }
  return true;
}

function endCall(world: World, call: Call, state: Call["state"]): void {
  call.state = state;
  const caller = world.actors[call.callerId];
  const callee = call.connectedToId ? world.actors[call.connectedToId] : undefined;
  if (caller && caller.busyWith === call.id) caller.busyWith = null;
  if (callee && callee.busyWith === call.id) callee.busyWith = null;
  if (caller) caller.nextCallAt = world.minute + 4;
  if (callee) callee.nextCallAt = Math.max(callee.nextCallAt, world.minute + 2);
  call.listening = false;
}

function speakLines(world: World, call: Call, rng: Rng): void {
  const caller = world.actors[call.callerId]!;
  const callee = world.actors[call.connectedToId!]!;
  const elapsed = world.minute - (call.connectedAt ?? world.minute);
  while (call.spoken < call.transcript.length) {
    const line = call.transcript[call.spoken]!;
    if (line.offset > elapsed) break;
    call.spoken++;
    const speaker = line.speakerId === "operator" ? null : world.actors[line.speakerId]!;
    const listener = speaker && speaker.id === caller.id ? callee : caller;
    if (line.claims && speaker) {
      const conf = trustIn(listener, speaker.id) * (call.misrouted ? 0.8 : 1);
      for (const c of line.claims) hear(world, listener, c, speaker.id, conf, call.id);
      if (call.listening) for (const c of line.claims) operatorLearns(world, c, speaker.id);
    }
    // The callee's stance line: carry out what was agreed.
    if (speaker && speaker.id === callee.id && call.response && call.spoken >= 3 && !call.wantApplied) {
      call.wantApplied = true;
      const r = call.response;
      if (!call.misrouted) {
        if (r.stance === "agree" && call.intent.want) {
          applyWant(world, callee, call.intent.want, caller.id, `On ${caller.short}'s word.`);
        }
        if (r.stance === "agree" && call.intent.kind === "plead") {
          callee.done["peace"] = world.minute;
          if (callee.role === "minister" && world.facts["list:ordered"] !== undefined && world.facts["list:cancelled"] === undefined) {
            world.facts["list:cancelled"] = world.minute;
            log(world, "civil", `The Minister rings the Prefecture and tells them to tear up the card. The Archbishop has his word.`, [callee.id], { secret: true });
          }
        }
        if (r.stance === "agree" && call.intent.kind === "persuade" && callee.loyalty === "undecided") {
          const side = effectiveSide(caller) ?? caller.faction;
          if (side !== "civil") commit(world, callee, side);
        }
      }
    }
  }
}

function listenRisk(world: World, call: Call, rng: Rng): void {
  if (!call.listening || call.clickHeard) return;
  call.listenedMinutes++;
  const mult = world.watchers.length ? 2 : 1;
  for (const id of [call.callerId, call.connectedToId!]) {
    const a = world.actors[id]!;
    if (rng.chance((0.004 + a.traits.paranoia * 0.012) * mult)) {
      call.clickHeard = true;
      a.suspicion = Math.min(100, a.suspicion + 15);
      const other = world.actors[id === call.callerId ? call.connectedToId! : call.callerId]!;
      other.suspicion = Math.min(100, other.suspicion + 6);
      call.transcript.splice(call.spoken, 0, { offset: world.minute - (call.connectedAt ?? 0), speakerId: a.id, text: `...Wait. Did you hear that? There is someone on this line.` });
      log(world, "exchange", `${clock(world.minute)} ${a.short} heard the click. "There is someone on this line."`, [a.id], { fingerprint: true, discovery: true });
      return;
    }
  }
}

function placeCalls(world: World, rng: Rng): void {
  const ids = Object.keys(world.actors).sort();
  for (const id of ids) {
    const actor = world.actors[id]!;
    const w = wantsToCall(world, actor, rng);
    if (!w) continue;
    const tag = w.intent.tag;
    actor.done[tag] = world.minute;
    actor.done[`${tag}#n`] = (actor.done[`${tag}#n`] ?? 0) + 1;
    actor.nextCallAt = world.minute + 6;
    if (actor.role === "citizen") actor.done["citizenDone"] = 1;

    // Someone who no longer trusts the exchange sends a runner instead.
    if (w.requestedId !== "operator" && (actor.suspicion >= 70 || trustIn(actor, "exchange") < 0.2) && actor.role !== "citizen") {
      const target = world.actors[w.requestedId]!;
      const mins = Math.round(travelMinutes(world, actor.locationId, target.locationId) * 1.5) + 10;
      world.runners.push({ fromId: actor.id, toId: target.id, claims: w.intent.claims, want: w.intent.want, arriveAt: world.minute + mins, tag });
      log(world, "move", `${actor.short} no longer trusts the telephone and sends a runner to ${target.short}.`, [actor.id], { secret: true });
      continue;
    }

    const call: Call = {
      id: newId(world, "call"),
      callerId: actor.id,
      requestedId: w.requestedId,
      connectedToId: null,
      intent: w.intent,
      state: "ringing",
      placedAt: world.minute,
      connectedAt: null,
      endsAt: null,
      transcript: [],
      spoken: 0,
      listening: false,
      listenedMinutes: 0,
      misrouted: false,
      clickHeard: false,
    };
    world.calls[call.id] = call;
    actor.busyWith = call.id;
    // Citizens blurt what they have seen to the operator.
    if (actor.role === "citizen") for (const c of w.intent.claims) operatorLearns(world, c, actor.id);
  }
}

function ageCalls(world: World, rng: Rng): void {
  for (const call of Object.values(world.calls)) {
    const caller = world.actors[call.callerId]!;
    if (call.state === "ringing" || call.state === "held") {
      const waited = world.minute - call.placedAt;
      const patience = call.state === "held" ? 10 + Math.round(call.intent.urgency * 8) : 12 + Math.round((1 - call.intent.urgency) * 6);
      caller.frustration = waited;
      if (waited >= patience) {
        endCall(world, call, "abandoned");
        caller.suspicion = Math.min(100, caller.suspicion + (call.state === "held" ? 5 : 3));
        caller.nextCallAt = world.minute + 8;
        log(world, "exchange", `${clock(world.minute)} ${caller.short} hangs up. The lamp for ${world.locations[caller.locationId]!.name} goes dark.`, [caller.id]);
        if (call.intent.kind === "order" && (caller.done[`${call.intent.tag}#n`] ?? 0) >= 2) sendRunnerFor(world, call);
      }
      continue;
    }
    if (call.state === "connected") {
      speakLines(world, call, rng);
      listenRisk(world, call, rng);
      if (call.endsAt !== null && world.minute >= call.endsAt) {
        finishCall(world, call);
      }
    }
  }
}

function sendRunnerFor(world: World, call: Call): void {
  const caller = world.actors[call.callerId]!;
  const target = world.actors[call.requestedId];
  if (!target) return;
  const mins = Math.round(travelMinutes(world, caller.locationId, target.locationId) * 1.5) + 10;
  world.runners.push({ fromId: caller.id, toId: target.id, claims: call.intent.claims, want: call.intent.want, arriveAt: world.minute + mins, tag: call.intent.tag });
  log(world, "move", `${caller.short} gives up on the telephone and sends a runner to ${target.short}.`, [caller.id], { secret: true });
}

function finishCall(world: World, call: Call): void {
  const caller = world.actors[call.callerId]!;
  const callee = world.actors[call.connectedToId!]!;
  endCall(world, call, "ended");
  const r = call.response;
  if (!call.misrouted && r && r.stance !== "refuse") caller.done[`${call.intent.tag}#ok`] = 1;
  if (!call.misrouted && call.intent.tag === "prefect_offer" && r && r.stance !== "refuse") {
    world.facts["prefect:offered"] = world.minute;
    log(world, "civil", `${caller.short} has offered the Prefecture's files to ${callee.short}. ${callee.short} did not say no.`, [caller.id, callee.id], { secret: true });
  }
  if (!call.misrouted && call.intent.kind === "personal" && call.connectedToId === call.requestedId) {
    world.player.tally.smallMercies++;
    log(world, "civil", `${clock(world.minute)} ${caller.short} got through to ${callee.short} to ${caller.need ?? "say what needed saying"}.`, [caller.id], { fingerprint: true });
  }
  if (call.misrouted) {
    log(world, "call", `${clock(world.minute)} ${caller.short} rang off, swearing at the exchange.`, [caller.id]);
  }
}

function deliverRunners(world: World, rng: Rng): void {
  const left: World["runners"] = [];
  for (const r of world.runners) {
    if (world.minute < r.arriveAt) {
      left.push(r);
      continue;
    }
    const from = world.actors[r.fromId]!;
    const to = world.actors[r.toId]!;
    for (const c of r.claims) hear(world, to, c, "runner", trustIn(to, from.id) * 0.9);
    if (r.want) {
      const fake: Intent = { kind: "order", claims: r.claims, want: r.want, opening: "", urgency: 1, tag: r.tag ?? "runner" };
      const stance = willComply(world, from, to, fake, rng);
      if (stance === "agree") applyWant(world, to, r.want, from.id, `By runner from ${from.short}.`);
    }
    if (r.tag) from.done[`${r.tag}#ok`] = 1;
    log(world, "move", `A runner from ${from.short} reaches ${to.short}.`, [from.id, to.id], { secret: true });
  }
  world.runners = left;
}

/* ------------------------------------------------------------------------------------------------
 * Radio, crowds, watchers
 * ---------------------------------------------------------------------------------------------- */

function radio(world: World): void {
  if (world.minute < world.nextBulletinAt) return;
  world.nextBulletinAt = world.minute + 45;
  const pending = world.facts["radio:pending"] as Faction | undefined;
  const holder = world.facts[K.control("loc_radio")] as Faction;
  let voice: string = world.facts[K.radio] as string;
  if (pending === "plotters" && holder === "plotters" && world.minute >= world.plan.proclamationAt - 5) voice = "plotters";
  else if (pending === "government" && holder === "government") voice = "government";
  else if (holder === "plotters" && world.minute >= world.plan.proclamationAt) voice = "plotters";
  if (voice === "music") return;
  world.facts[K.radio] = voice;
  const claims: Claim[] =
    voice === "plotters"
      ? [
          { key: K.coup, value: "yes" },
          { key: K.radio, value: "plotters" },
          { key: K.control("loc_radio"), value: "plotters" },
          { key: K.president, value: world.facts[K.president] === "loc_palace" ? "loc_fled" : world.facts[K.president]! },
          { key: K.curfew, value: "yes" },
        ]
      : [
          { key: K.radio, value: "government" },
          { key: K.control("loc_palace"), value: "government" },
          { key: K.president, value: "loc_palace" },
          { key: K.curfew, value: "yes" },
          { key: K.coup, value: world.facts[K.coup]! },
        ];
  for (const a of Object.values(world.actors)) {
    if (a.status === "dead") continue;
    const conf = trustIn(a, "radio") * (voice === "plotters" ? 0.9 : 0.8);
    for (const c of claims) hear(world, a, c, "radio", conf);
  }
  for (const c of claims) operatorLearns(world, c, "radio");
  const countKey = `radio:count:${voice}`;
  const n = Number(world.facts[countKey] ?? 0);
  world.facts[countKey] = n + 1;
  const text =
    voice === "plotters"
      ? n === 0
        ? `The music stops. A man's voice reads a proclamation: the armed forces have assumed responsibility for the nation; ${world.story.proclamation}; the President has left the capital; citizens are to remain indoors.`
        : n === 1
          ? `The proclamation again, read more slowly this time, and then a ballet. Nobody in the city needs to be told what it means when the radio plays a ballet.`
          : `The ballet continues between readings of the proclamation.`
      : n === 0
        ? `The music stops for a bulletin: the government is in full control, the President is at the Palace, a curfew is in force until dawn, and ${world.story.bulletin}.`
        : n === 1
          ? `Another bulletin: the government remains in control and the curfew stands. The announcer sounds tired.`
          : `The radio repeats the government bulletin, then returns to the music.`;
  log(world, "radio", `${clock(world.minute)} ${text}`, []);
}

/* ------------------------------------------------------------------------------------------------
 * The operator's own: harm, news, breaks, removal
 * ---------------------------------------------------------------------------------------------- */

/** Fire somewhere the operator's person is standing. Reported, never shown; the news comes up the stairs later. */
function familyHarm(world: World, locId: Id, defenderIds: Id[], rng: Rng): void {
  const f = world.family;
  if (f.status !== "safe") return;
  let hit = false;
  if (f.where === "bridge" && locId === "loc_bridge" && defenderIds.includes("u_bridge")) hit = true;
  if (f.where === "square" && locId === "loc_palace" && world.facts["mobilise"] !== undefined && Number(world.facts[K.crowd("loc_palace")] ?? 0) > 0) hit = rng.chance(0.6);
  if (!hit) return;
  f.status = rng.chance(0.6) ? "wounded" : "dead";
  world.facts["family:news_at"] = world.minute + 18 + rng.int(0, 12);
  log(world, "clash", `${f.name} is ${f.status === "wounded" ? "hit" : "among the dead"} at ${world.locations[locId]!.name}.`, [f.actorId], { secret: true });
}

/** The news reaches the exchange on foot. */
function familyNews(world: World): void {
  const f = world.family;
  const at = world.facts["family:news_at"];
  if (at === undefined || world.minute < Number(at)) return;
  delete world.facts["family:news_at"];
  f.newsAt = world.minute;
  const where = f.where === "bridge" ? "the bridge" : "the square";
  log(
    world,
    "civil",
    f.status === "wounded"
      ? `${clock(world.minute)} A porter from St. Oda's comes up the stairs with a note. ${f.name} was on ${where}. He is on the ward with a bullet in him and he is asking for you. You cannot leave the board.`
      : `${clock(world.minute)} A porter from St. Oda's comes up the stairs with a note. It says only that you should come when your shift ends, and that ${f.name} was on ${where}.`,
    [f.actorId],
    { hand: true },
  );
}

/** One minute with the relief on the board: connect what rings, answer nothing. Returns what she connected. */
export function reliefMinute(world: World): string[] {
  const made: string[] = [];
  const rng = Rng.fromState(world.rng);
  for (const call of Object.values(world.calls)) {
    if (call.state !== "ringing" && call.state !== "held") continue;
    const caller = world.actors[call.callerId]!;
    if (call.requestedId === "operator") {
      // "This is the relief. The operator is away from the board. Ring back in five minutes."
      call.state = "abandoned";
      caller.busyWith = null;
      caller.nextCallAt = world.minute + 6;
      if (call.intent.tag === "family") caller.done["family"] = 0;
      continue;
    }
    if (connectCall(world, call, call.requestedId, rng)) {
      made.push(`${world.operator.relief} put ${caller.short} through to ${world.actors[call.requestedId]!.short}.`);
      world.player.tally.connected++;
    }
  }
  world.rng = rng.state();
  tick(world);
  return made;
}

const HOUR_LINES: Record<number, string> = {
  60: "Eleven. The trams have stopped, as they do at eleven, and the river is black under the bridge lamps. Somebody on the Old Quay is playing an accordion to the sailors, badly, and the sailors do not mind.",
  120: "Midnight. The first cold is under the door. Across the street a window is lit and a man stands at it in his vest, smoking something imported, looking at the bridge the way you are looking at it.",
  180: "One. The street below is empty in the way it is never empty, and the tiles on the Post and Telegraph are sweating in the damp. The relief has brought up two bottles of beer, which is against the regulations, and two glasses, which is worse.",
  240: "Two. The cold has come in properly. Coffee that tastes of the tin, and a cigarette you did not ask for and did not refuse.",
  300: "Three. The hour when nobody in the city is telling the truth, including the clocks. The harbour wind has turned and brought the tanneries with it.",
  360: "Four. A dog on the Old Quay has been barking for an hour at something that is not there, or is.",
  420: "Five. A grey line over the Rail Yards. The bakers on Varga Street will be deciding now whether to light the ovens. The Lantern Market will not open today, or it will, which would be worse.",
};

/** The hourly break: what she hears while the relief has the board. Gossip is hearsay and sometimes wrong. */
function composeBreak(world: World, rng: Rng): void {
  const lines: string[] = [];
  const base = HOUR_LINES[world.minute] ?? `${clock(world.minute)}.`;
  const bridgeClosed = world.facts[K.bridge] === "no";
  const shots = Number(world.facts["shots"] ?? 0) > 0;
  lines.push(`${base}${bridgeClosed ? " The barriers are still down on the bridge." : ""}${shots ? " The smell of cordite comes and goes on the wind." : ""}`);

  // Irena's gossip: a true thing from the last hour, or a rumour.
  const relief = world.operator.relief;
  // Never about hers: that news comes up the stairs on its own.
  const recent = world.chronicle.filter(
    (e) =>
      e.secret &&
      e.minute > world.minute - 60 &&
      (e.kind === "move" || e.kind === "control" || e.kind === "clash" || e.kind === "civil") &&
      !e.text.includes("believes") &&
      !e.text.includes("runner") &&
      !e.actorIds.includes(world.family.actorId) &&
      !e.actorIds.includes("a_family"),
  );
  if (recent.length && !rng.chance(0.3)) {
    const e = rng.pick(recent);
    // The first sentence only: gossip carries the event, not the reason.
    const first = e.text.split(/(?<=\.)\s/)[0]!.replace(/\.$/, "");
    lines.push(`${relief}, whose brother-in-law drives the last tram, says with the cigarette in the corner of her mouth: "${first}. Or so he says." She says everything that way.`);
  } else {
    const keys = [K.loyalty("a_general"), K.president, K.radio, K.loyalty("a_captain")];
    const key = rng.pick(keys);
    const alts = ["loc_palace", "loc_embassy", "loc_fled", "government", "plotters", "music", "loyalist", "plotter", "undecided"];
    const options = key === K.president ? ["loc_embassy", "loc_fled", "loc_palace"] : key === K.radio ? ["plotters", "government", "silent"] : ["plotter", "loyalist"];
    void alts;
    const value = rng.pick(options);
    const speaker = world.actors["a_editor"]!;
    lines.push(`${relief}'s cousin at the Ministry rang her at home before she came up. He says: "${speakClaim(world, speaker, { key, value })}" ${relief} believes him. You have never met the cousin.`);
  }

  // The supervisor's radio: the dance music is the night's clock.
  lines.push(`The radio in the supervisor's office is playing ${musicNow(world)}.`);

  // Her own.
  const f = world.family;
  if (f.knownAt !== null && f.newsAt === null) {
    lines.push(
      f.where === "bridge"
        ? `You stand at the window and look at the bridge, where ${f.name} is, and cannot see anything but the lamps.`
        : f.where === "square"
          ? `You think about ${f.name}, who is nineteen and thinks he is twenty-five, and you do not look at the telephone, because if you look at it you will ring the union office, and he would never forgive you.`
          : `You think about ${f.name} asleep in the back room, and about the two men who asked which room it was.`,
    );
  }
  world.breaks.push({ minute: world.minute, lines, reliefConnected: [] });
}

/** Blatant manipulation ends the night early. The rest plays out without her. */
function checkRemoval(world: World): void {
  if (world.facts["removed"] !== undefined) return;
  const leaders: Record<Faction, Id[]> = { government: ["a_minister", "a_prefect", "a_commandant"], plotters: ["a_colonel", "a_major"], civil: [] };
  for (const faction of ["government", "plotters"] as const) {
    const ids = leaders[faction];
    const worst = Math.max(...ids.map((id) => world.actors[id]?.suspicion ?? 0));
    const watcher = world.watchers.find((w) => w.faction === faction && w.arrivedAt <= world.minute);
    let remove = false;
    if (watcher) {
      const side = new Set(Object.values(world.actors).filter((a) => (a.loyalty === "plotter" ? "plotters" : a.loyalty === "loyalist" ? "government" : a.faction) === faction).map((a) => a.id));
      const since = world.chronicle.filter((e) => e.discovery && e.minute >= watcher.arrivedAt && e.actorIds.some((id) => side.has(id))).length;
      if (since >= 2 || worst >= 70) remove = true;
    } else if (worst >= 90) remove = true;
    if (!remove) continue;
    world.facts["removed"] = world.minute;
    world.facts["removed:by"] = faction;
    const who = watcher ? watcher.name : faction === "government" ? "two men from the Prefecture" : "a sergeant and two soldiers";
    log(
      world,
      "exchange",
      `${clock(world.minute)} ${cap(who)} ${watcher ? "puts a hand on the cord you are holding" : "come up the stairs without knocking"}. "That will do for tonight." ${world.operator.relief} is told to take the board. You are told to get your coat.`,
      [],
      { fingerprint: true },
    );
    return;
  }
}

/** After removal: the night plays out with the relief on the board, and the ending is rewritten around it. */
function playOut(world: World): void {
  const removedAt = Number(world.facts["removed"]);
  let guard = 0;
  while (world.status === "playing" && guard++ < 600) reliefMinute(world);
  if (!world.ending) return;
  const by = world.facts["removed:by"] === "plotters" ? "the Colonel's people" : "the Prefecture";
  world.ending.removedAt = removedAt;
  world.ending.fate = "taken";
  world.ending.summary = `At ${clock(removedAt)} ${by} took you off the board. You learned how the night ended from the morning edition, like everyone else. ${world.ending.summary.split(". ").slice(0, 1).join(". ")}. Where they took you, the edition does not say.`;
}

/** Twice in the night the wider world is heard through somebody's window. Neither station is on the board. */
function shortwave(world: World): void {
  const coup = world.facts[K.coup] === "yes";
  if (world.minute === world.plan.startAt + 70 && coup) {
    log(world, "radio", `${clock(world.minute)} Through the window, from a flat across the street, the Southern Service on the shortwave: "unconfirmed reports of troop movements in Castellane", and that Aldermark "continues to follow events with close attention".`, []);
  }
  if (world.minute === world.plan.startAt + 190 && coup) {
    const voice = world.facts[K.radio];
    const line =
      voice === "plotters"
        ? `The Voice of the Mountains, from across the passes, greets "the patriotic forces of Meridia" and hopes they will "reconsider the foreign bases". It has never been in favour of a colonel before.`
        : `The Voice of the Mountains, from across the passes, reports "the crisis of the Castellane regime" and sends "fraternal greetings to the workers of the Rail Yards". It does not say which side it means.`;
    log(world, "radio", `${clock(world.minute)} ${line}`, []);
  }
}

function crowds(world: World): void {
  const started = world.facts["mobilise"];
  if (started === undefined) return;
  if (world.minute - Number(started) < 25) return;
  if (world.minute % 10 !== 0) return;
  const cap_ = Number(world.facts["mobilise:cap"] ?? 250);
  const cur = Number(world.facts[K.crowd("loc_palace")] ?? 0);
  if (cur >= cap_) return;
  const next = Math.min(cap_, cur + 80);
  world.facts[K.crowd("loc_palace")] = next;
  if (cur === 0) log(world, "civil", `Singing, faint, from the direction of the Palace. People are gathering.`, []);
  if (next >= 300 && cur < 300) operatorLearns(world, { key: K.crowd("loc_palace"), value: next }, "seen");
}

function watchers(world: World): void {
  if (world.minute % 5 !== 0) return;
  // One furious official is enough to send somebody.
  const worst = (ids: Id[]) => Math.max(...ids.map((id) => world.actors[id]?.suspicion ?? 0));
  const gov = worst(["a_minister", "a_prefect", "a_commandant"]);
  const plot = worst(["a_colonel", "a_major"]);
  if (gov >= 45 && !world.watchers.some((w) => w.faction === "government")) {
    world.watchers.push({ faction: "government", arrivedAt: world.minute + 20, name: "a police lieutenant" });
    log(world, "exchange", `${clock(world.minute)} The Prefecture rings the supervisor's line. Someone is being sent to "assist" you.`, [], { fingerprint: true });
  }
  if (plot >= 45 && world.facts[K.coup] === "yes" && !world.watchers.some((w) => w.faction === "plotters")) {
    world.watchers.push({ faction: "plotters", arrivedAt: world.minute + 25, name: "a sergeant and two soldiers" });
    log(world, "exchange", `${clock(world.minute)} A lorry stops in the street below. Boots on the stairs.`, [], { fingerprint: true });
  }
  for (const w of world.watchers) {
    if (w.arrivedAt === world.minute) {
      log(world, "exchange", `${clock(world.minute)} ${cap(w.name)} ${w.faction === "government" ? "takes a chair behind you and lights a cigarette. He is here to watch the board." : "stand in the doorway with their rifles. The sergeant tells you to carry on, and to connect his calls first."}`, []);
    }
  }
}

/* ------------------------------------------------------------------------------------------------
 * Ending
 * ---------------------------------------------------------------------------------------------- */

/** The Palace question is settled. The night is not: everything after this is the aftermath, still through her. */
function decide(world: World, outcome: NightOutcome, text: string): void {
  world.facts["decided"] = outcome;
  world.facts["decided:at"] = world.minute;
  log(world, "system", `${clock(world.minute)} ${text}`, [], { hand: true });
}

function checkEnding(world: World): void {
  const palace = world.facts[K.control("loc_palace")];
  const regiment = world.units["u_regiment"]!;
  const colonel = world.actors["a_colonel"]!;
  const decided = world.facts["decided"] as NightOutcome | undefined;
  if (!decided) {
    if (palace === "plotters") {
      decide(world, "coup_succeeded", `From the window: the engines in the Palace square have stopped. The lamps in the Palace go out, floor by floor, and come on again. ${colonel.short}'s armour holds the Palace.`);
    } else if (((colonel.done["stood_down"] ?? 0) > 0 || (colonel.done["repulsed"] ?? 0) > 0) && regiment.moving && regiment.moving.to === "loc_fort") {
      decide(world, "coup_failed", `From the window: headlamps in column on the bridge again, going the other way. The Regiment is returning to Fort Saint-Aurel.`);
    }
  }
  if (world.minute < world.endMinute) return;

  let outcome: NightOutcome;
  let why: string;
  const final = world.facts["decided"] as NightOutcome | undefined;
  if (final === "coup_succeeded") {
    outcome = "coup_succeeded";
    why = `${colonel.short}'s armour holds the Palace.`;
  } else if (final === "coup_failed") {
    outcome = "coup_failed";
    why = `The Regiment is back at Fort Saint-Aurel. The Palace stands.`;
  } else if (regiment.orders === "secure" && regiment.at === "loc_palace") {
    outcome = "standoff";
    why = `Dawn finds the Regiment in the Palace square and the Guard behind the gates. Nobody has fired. Everybody is waiting for someone else.`;
  } else {
    outcome = "coup_failed";
    why = `The Palace stands. The Regiment never took it.`;
  }
  world.status = "ended";
  const winner: Faction = outcome === "coup_succeeded" ? "plotters" : "government";
  const leaders = winner === "plotters" ? ["a_colonel", "a_major"] : ["a_minister", "a_prefect", "a_commandant"];
  const suspicions = leaders.map((id) => world.actors[id]?.suspicion ?? 0);
  const susp = Math.max(suspicions.reduce((s, v) => s + v, 0) / leaders.length, Math.max(...suspicions) * 0.7);
  const t = world.player.tally;
  const fingerprints = world.chronicle.filter((e) => e.fingerprint).map((e) => e.text);
  // What the winning side's people noticed. The rest they never knew. Each discovery is a line in a file.
  const winners = new Set(Object.values(world.actors).filter((a) => (a.loyalty === "plotter" ? "plotters" : a.loyalty === "loyalist" ? "government" : a.faction) === winner).map((a) => a.id));
  const discovered = world.chronicle.filter((e) => e.discovery && e.actorIds.some((id) => winners.has(id))).map((e) => e.text);
  let fate: NonNullable<World["ending"]>["fate"];
  if (susp >= 55 || discovered.length >= 4 || world.watchers.some((w) => w.faction === winner && w.arrivedAt <= world.minute)) fate = "taken";
  else if (susp >= 25 || discovered.length >= 2) fate = "questioned";
  else if (t.smallMercies >= 3 && t.connected >= 8) fate = "thanked";
  else fate = "unnoticed";
  const whoWon = winner === "plotters" ? "the Colonel's people" : "the Prefecture";
  const fateText = {
    unnoticed: "Nobody comes for you. You sign the log, hand it to the shift manager, put on your coat, and walk home up the Salt Stairs past the shuttered shops, with the bakers' smoke just starting. Nobody will ever know what the night owed to a woman at a switchboard.",
    thanked: "At a quarter to seven a boy brings up a note from the hospital, and another from the Prefecture. Thank you, they say, for keeping the lines open. You put them in your coat pocket with the tobacco and do not read them again.",
    questioned: `At seven two men in raincoats ask you to accompany them. They are polite. They are ${whoWon}, they have a list of calls, and they want to know why some of them never went through. You are home by noon, and you will not sleep.`,
    taken: `They are waiting at the foot of the stairs when your shift ends. They are ${whoWon}, and they do not say where they are taking you.`,
  }[fate];
  const morning = morningAfter(world, outcome);
  // The night that did not happen.
  // It takes the Archbishop's word reaching the Colonel at the right moment, which only the operator can time.
  const ideal =
    outcome === "coup_failed" &&
    (colonel.done["peace"] ?? 0) > 0 &&
    world.casualties.length === 0 &&
    world.family.status === "safe" &&
    world.facts["list:ordered"] === undefined &&
    (fate === "unnoticed" || fate === "thanked") &&
    Object.values(world.actors).every((a) => a.status === "free");
  world.ending = {
    outcome,
    fate,
    summary: ideal
      ? `${why} Nothing has happened tonight that the morning edition can print. The list is in the Minister's drawer. ${fateText} At seven the Archbishop has the bells rung, and the city does not know why.`
      : `${why} ${fateText}`,
    fingerprints,
    cost: humanCost(world),
    morning,
    discovered,
    herWord: herWord(world, outcome),
  };
  if (ideal) world.ending.ideal = true;
  log(world, "system", `${clock(world.minute)} ${why}`, []);
}

/** Her word at the end, in her own hand: about her son, and the world he will or will not live in. */
function herWord(world: World, outcome: NightOutcome): string {
  const f = world.family;
  const son = f.name;
  const removed = world.facts["removed"] !== undefined;
  const open = removed ? `They let me write this much before they took the book. ` : "";
  switch (f.status) {
    case "dead":
      return `${open}${son} was nineteen in June. His father went north in 1943 and I kept a photograph by the board for nineteen years so that the boy would know what a man who kept his word looked like. I will put the photograph away now. There is nobody left to show it to, and the country can keep its word to somebody else.`;
    case "wounded":
      return `${open}${son} is on the ward at St. Oda's with a bullet in him, and the Director says he will walk. Whoever is in the Palace this morning, he will walk in their city. I have decided to be grateful for the walking and to think about the city later. I have been thinking about the city later for nineteen years.`;
    case "taken":
      return `${open}They took ${son} from the square at six. His father was taken north in 1943 and I was told it was for the country, and I believed them, and I believe them still, because I have a son and I have to believe something. He will be home by Thursday or he will not. I will be on the board either way.`;
    default:
      break;
  }
  switch (outcome) {
    case "coup_succeeded":
      return `${open}${son} is asleep, or he is telling me he is asleep, which at his age is the same courtesy. There is a colonel in the Palace and a ballet on the radio and tomorrow there will be a different list with different names, and his will not be on it, and I will go on making sure of that for as long as there are lists. His father would have called this a disgrace. His father is not here. I am.`;
    case "coup_failed":
      return `${open}${son} is asleep. The Regiment is back at the Fort and the President is in the Palace and the decree is in its third year this morning as it was last night. Nothing has changed, and I have spent eight hours making sure nothing changed, and I would do it again, because the boy is asleep. His father would not have understood that. He kept his word to a king. I keep mine to a boy.`;
    default:
      return `${open}${son} is asleep, and the tanks are in the square, and the Guard is behind the gates, and the trams are running past all of it as if it were weather. Perhaps it is. His father went north to settle something and it was not settled. I am going home to sleep in the daylight, which is the only time I can.`;
  }
}

/** What the winner does next, by name. */
function morningAfter(world: World, outcome: NightOutcome): string[] {
  const out: string[] = [];
  const minister = world.actors["a_minister"]!;
  const prefect = world.actors["a_prefect"]!;
  const colonel = world.actors["a_colonel"]!;
  const president = world.actors["a_president"]!;
  const editor = world.actors["a_editor"]!;
  const names = listNames(world);
  const crowd = Number(world.facts[K.crowd("loc_palace")] ?? 0);
  const f = world.family;
  // The square is cleared at six and some of the people in it are taken. Whether he is one of them is luck.
  const fork = Rng.fromState(world.rng);
  if (outcome === "coup_succeeded" && f.where === "square" && f.status === "safe" && crowd >= 300 && Number(world.facts["mobilise"] ?? -1) >= 0 && fork.chance(0.45)) f.status = "taken";
  if (outcome === "coup_failed" && f.where === "list" && f.status === "safe" && world.facts["list:ordered"] !== undefined && world.facts["list:cancelled"] === undefined) f.status = "taken";
  const where = (a: Actor, arrested: string, fled: string, free: string) => (a.status === "arrested" ? arrested : a.locationId === "loc_embassy" ? fled : free);
  if (outcome === "coup_succeeded") {
    out.push(where(minister, `${minister.short} was taken from the Ministry in the night and is at the Fort.`, `${minister.short} is at the Embassy, in a room on the second floor, and the Embassy has not decided what he is.`, `${minister.short} is still at his desk at dawn. Nobody has come for him yet. He is burning paper.`));
    out.push(
      world.facts["prefect:offered"] !== undefined
        ? `${prefect.short} keeps his office. He brought his lists to the new government before it asked for them.`
        : where(prefect, `${prefect.short} was taken from the Prefecture. His own men did not stop the lorry.`, `${prefect.short} is at the Embassy.`, `${prefect.short} is at the Prefecture with the doors locked, waiting to see who knocks.`),
    );
    out.push(president.status === "arrested" ? `The President is driven to the Airfield under escort. The proclamation will say he asked to go.` : president.locationId === "loc_embassy" ? `The President is at the Embassy, which has not yet decided whether to admit it.` : `The President is "at a location outside the capital".`);
    out.push(`The Courier does not print this morning. ${editor.short} is told to come back on Thursday.`);
    if (crowd >= 300) out.push(`The square is cleared at six. Some of the people in it are taken to the barracks.`);
    out.push(world.story.promise);
  } else if (outcome === "coup_failed") {
    out.push(where(colonel, `${colonel.short} was taken at the Fort in the night by a company of the Garrison. The Regiment's officers are confined to quarters.`, `${colonel.short} is at the Embassy, which is "studying his request". The Regiment's officers are confined to quarters.`, `${colonel.short} is at the Fort with the gates shut. He will be arrested before noon, or he will not be.`));
    if (world.facts["list:cancelled"] !== undefined) {
      out.push(`The Minister's list, ${names}, is torn up. The Archbishop has his word, and will hold him to it for as long as that lasts.`);
    } else if (world.facts["list:ordered"] !== undefined) {
      out.push(`At first light the Prefecture takes ${names}. The Minister's order went through the exchange at ${clock(Number(world.facts["list:ordered"]))}.`);
      for (const id of world.story.list) world.actors[id]!.status = "arrested";
    } else {
      out.push(`The Minister's list, ${names}, stays in his drawer. For now.`);
    }
    if (crowd >= 300) out.push(`The crowd in the square goes home singing. The Prefecture photographs it leaving.`);
    out.push(`The radio plays the anthem at seven, and then the dance music again.`);
  } else {
    out.push(`Nobody is arrested, yet. The lists are still in both men's pockets.`);
    out.push(`The Embassy, the Archbishop and the General are all said to be "in contact with both sides".`);
    out.push(`The trams run. People go to work past the tanks and do not look at them.`);
  }
  return out;
}

/** Who paid for the night, by name. Reported, never shown. Hers first. */
function humanCost(world: World): string[] {
  const out: string[] = [];
  const f = world.family;
  const famActor = world.actors[f.actorId]!;
  const rel = f.relation === "brother" ? "your brother" : f.relation === "son" ? "your son" : "your lodger";
  const place = f.where === "bridge" ? "with the Bridge Company on the bridge" : f.where === "square" ? "at the University" : "on the Minister's list";
  const knew = f.knownAt === null ? ` ${f.where === "list" ? "Mother" : "He"} rang you at ${clock(world.plan.startAt + (f.where === "list" ? 55 : 9))} and the lamp went dark before you picked up.` : "";
  switch (f.status) {
    case "dead":
      out.push(`${f.name}, ${rel}, was ${place} tonight and is dead.${knew}`);
      break;
    case "wounded":
      out.push(`${f.name}, ${rel}, was ${place} tonight and is on the ward at St. Oda's with a bullet in ${him(famActor)}.${knew}`);
      break;
    case "taken":
      out.push(`${f.name}, ${rel}, was ${place} and was taken ${f.where === "list" ? "from the back room at six. Mother was in the kitchen when they came." : "from the square at six and driven to the barracks."}${knew}`);
      break;
    default:
      out.push(`${f.name}, ${rel}, was ${place} tonight and is unhurt.${knew}`);
  }
  for (const c of world.casualties) {
    const attacker = world.units[c.unitId]!;
    const defender = world.units[c.defenderUnitId]!;
    const defCmd = world.actors[defender.commanderId]!;
    out.push(`${clock(c.minute)}, ${world.locations[c.locId]!.name}: ${attacker.name} opened fire on ${defCmd.short}'s ${defender.name.replace(/^the /, "")}. The morning edition will carry the names.`);
  }
  for (const a of Object.values(world.actors)) {
    if (a.status === "arrested") out.push(`${a.short} is under arrest.`);
    if (a.status === "dead") out.push(`${a.short} is dead.`);
  }
  for (const a of Object.values(world.actors)) {
    if (a.role !== "citizen" || !a.need) continue;
    const call = Object.values(world.calls).find((c) => c.callerId === a.id);
    if (!call) continue;
    const reached = call.state === "ended" && !call.misrouted && (call.connectedToId === call.requestedId || call.relayed !== undefined);
    if (!reached) {
      const how = call.state === "refused" ? "You told her the line was down." : call.state === "abandoned" ? "Nobody answered the lamp." : call.state === "cut" ? "You pulled the cord." : call.misrouted ? "You put her through to the wrong line." : call.state === "ringing" || call.state === "held" ? "The lamp was still burning at dawn." : "The message went in the drawer.";
      out.push(`${a.short} never got to ${a.need}. ${how.replace(/\bher\b/g, him(a))}`);
    }
  }
  return out;
}

/* ------------------------------------------------------------------------------------------------
 * The minute
 * ---------------------------------------------------------------------------------------------- */

export function tick(world: World): void {
  if (world.status !== "playing") return;
  const rng = Rng.fromState(world.rng);
  world.minute++;

  if (world.minute === world.plan.startAt) {
    world.facts[K.coup] = "yes";
    world.facts[K.control("loc_fort")] = "plotters";
    world.locations["loc_fort"]!.control = "plotters";
    world.facts[K.control("loc_airfield")] = "plotters";
    world.locations["loc_airfield"]!.control = "plotters";
    log(world, "system", `At Fort Saint-Aurel the Colonel puts down his coffee and picks up the telephone.`, ["a_colonel"], { secret: true });
  }
  // The Colonel leaves the Fort with the Regiment once his calls are made or have failed.
  const colonel = world.actors["a_colonel"]!;
  const regiment = world.units["u_regiment"]!;
  if (!colonel.done["left_fort"] && world.minute >= world.plan.startAt + 40 && !colonel.busyWith && regiment.at === "loc_fort" && !regiment.moving) {
    startMove(world, regiment, "loc_palace", "The Colonel rides in the lead tank.");
  }

  for (const unit of Object.values(world.units)) {
    if (unit.moving && world.minute >= unit.moving.eta) {
      arrive(world, unit, rng);
      // The commander sees where he has arrived; dusk beliefs about the place yield to his own eyes.
      observe(world, world.actors[unit.commanderId]!, rng);
    }
  }
  if (world.minute % 15 === 0) reconsiderStandoffs(world, rng);

  ageCalls(world, rng);
  deliverRunners(world, rng);
  placeCalls(world, rng);
  radio(world);
  shortwave(world);
  crowds(world);
  watchers(world);
  familyNews(world);
  arrests(world);

  if (world.minute % 5 === 0) {
    for (const a of Object.values(world.actors)) observe(world, a, rng);
  }
  if (world.minute % 10 === 0) {
    for (const a of Object.values(world.actors)) a.suspicion = Math.max(0, a.suspicion - 1);
  }
  if (world.minute % 60 === 0 && world.minute >= 60 && world.minute < world.endMinute && world.facts["removed"] === undefined) composeBreak(world, rng);
  if (world.minute % 5 === 0) checkRemoval(world);

  checkEnding(world);
  world.rng = rng.state();
  if (world.facts["removed"] !== undefined && world.facts["removed"] === world.minute && world.status === "playing") playOut(world);
}

function cap(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}
function lower(s: string): string {
  return s.charAt(0).toLowerCase() + s.slice(1).replace(/\.$/, "");
}

export { believed };
