import type { Actor, Call, Id, World } from "../sim/types";
import { reachable } from "../sim/game";
import { s, clear } from "./dom";
import type { UiActions, UiState } from "./state";

/**
 * The switchboard: one jack per line, a lamp above each, cords for connected calls.
 * The jack field is built once; lamps, labels and cords are updated on every render.
 */

const W = 820;
const H = 440;

interface JackPos {
  id: Id;
  x: number;
  y: number;
}

interface RowSpec {
  label: string;
  ids: (world: World) => Id[];
}

const ROWS: RowSpec[] = [
  { label: "STATE", ids: () => ["a_president", "a_commandant", "a_minister", "a_prefect", "a_radio"] },
  { label: "ARMY", ids: () => ["a_general", "a_colonel", "a_major", "a_captain"] },
  { label: "CITY", ids: () => ["a_students", "a_union", "a_archbishop", "a_editor", "a_hospital", "a_ambassador"] },
  {
    label: "SUBSCRIBERS",
    ids: (w) =>
      Object.values(w.actors)
        .filter((a) => a.role === "citizen")
        .map((a) => a.id)
        .sort(),
  },
];

const CORD_COLOURS = ["#c9a66b", "#8f3b2e", "#4f6b4a", "#5b5e8a", "#a4553f", "#6b7f8a"];

export class Board {
  readonly svg: SVGSVGElement;
  private jacks = new Map<Id, JackPos>();
  private lampEls = new Map<Id, SVGCircleElement>();
  private jackGroups = new Map<Id, SVGGElement>();
  private labelEls = new Map<Id, SVGTextElement>();
  private subEls = new Map<Id, SVGTextElement>();
  private cords: SVGGElement;
  private plugs: SVGGElement;
  private hint: SVGTextElement;

  constructor(world: World, private readonly ui: UiActions) {
    this.svg = s("svg", { viewBox: `0 0 ${W} ${H}`, class: "board", role: "img", "aria-label": "Switchboard" });
    const defs = s("defs");
    defs.appendChild(
      s(
        "radialGradient",
        { id: "lampGlow", cx: "50%", cy: "50%", r: "50%" },
        s("stop", { offset: "0%", "stop-color": "#ffd27a", "stop-opacity": "0.9" }),
        s("stop", { offset: "100%", "stop-color": "#ffb347", "stop-opacity": "0" }),
      ),
    );
    defs.appendChild(
      s(
        "linearGradient",
        { id: "brass", x1: "0", y1: "0", x2: "0", y2: "1" },
        s("stop", { offset: "0%", "stop-color": "#e8c37a" }),
        s("stop", { offset: "55%", "stop-color": "#b8863b" }),
        s("stop", { offset: "100%", "stop-color": "#7a561f" }),
      ),
    );
    this.svg.appendChild(defs);

    // Panel.
    this.svg.appendChild(s("rect", { x: 0, y: 0, width: W, height: H, rx: 10, class: "board-panel" }));
    this.svg.appendChild(s("rect", { x: 8, y: 8, width: W - 16, height: H - 16, rx: 6, class: "board-inner" }));
    // Screws.
    for (const [x, y] of [
      [18, 18],
      [W - 18, 18],
      [18, H - 18],
      [W - 18, H - 18],
    ] as const) {
      this.svg.appendChild(s("circle", { cx: x, cy: y, r: 4, class: "screw" }));
    }

    const rowH = (H - 40) / ROWS.length;
    ROWS.forEach((row, ri) => {
      const ids = row.ids(world);
      const y = 30 + ri * rowH + rowH * 0.5;
      this.svg.appendChild(s("text", { x: 22, y: y - rowH * 0.32, class: "row-label" }, row.label));
      this.svg.appendChild(s("line", { x1: 22, y1: y - rowH * 0.26, x2: W - 22, y2: y - rowH * 0.26, class: "row-rule" }));
      const left = 70;
      const right = W - 50;
      const step = (right - left) / Math.max(1, ids.length);
      ids.forEach((id, i) => {
        const x = left + step * i + step / 2;
        this.jacks.set(id, { id, x, y: y + 4 });
        this.svg.appendChild(this.makeJack(world, id, x, y + 4));
      });
    });

    this.cords = s("g", { class: "cords" });
    this.plugs = s("g", { class: "plugs" });
    this.svg.appendChild(this.cords);
    this.svg.appendChild(this.plugs);
    this.hint = s("text", { x: W / 2, y: H - 14, class: "board-hint", "text-anchor": "middle" });
    this.svg.appendChild(this.hint);
  }

  private makeJack(world: World, id: Id, x: number, y: number): SVGGElement {
    const actor = world.actors[id]!;
    const g = s("g", { class: "jack", "data-id": id, tabindex: 0, role: "button" });
    const lamp = s("circle", { cx: x, cy: y - 26, r: 6, class: "lamp" });
    const glow = s("circle", { cx: x, cy: y - 26, r: 16, class: "lamp-glow", fill: "url(#lampGlow)" });
    const ring = s("circle", { cx: x, cy: y, r: 11, class: "jack-ring" });
    const hole = s("circle", { cx: x, cy: y, r: 6, class: "jack-hole" });
    const label = s("text", { x, y: y + 26, class: "jack-label", "text-anchor": "middle" }, actor.short);
    const sub = s("text", { x, y: y + 38, class: "jack-sub", "text-anchor": "middle" }, world.locations[actor.locationId]?.name ?? "");
    g.append(glow, lamp, ring, hole, label, sub);
    g.appendChild(s("title", {}, actor.short));
    this.lampEls.set(id, lamp);
    this.jackGroups.set(id, g);
    this.labelEls.set(id, label);
    this.subEls.set(id, sub);
    const act = () => this.onJack(id);
    g.addEventListener("click", act);
    g.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        act();
      }
    });
    return g;
  }

  private state: UiState | null = null;

  private onJack(id: Id): void {
    const st = this.state;
    if (!st) return;
    const w = st.world;
    if (st.misrouteFor) {
      const call = w.calls[st.misrouteFor];
      if (call && id !== call.callerId && id !== call.requestedId && !reachable(w, id)) {
        this.ui.dispatch({ type: "misroute", callId: call.id, toId: id });
        this.ui.beginMisroute(null);
      }
      return;
    }
    // Select a pending call from this line, else a live call this line is on.
    const pending = Object.values(w.calls).find((c) => c.callerId === id && (c.state === "ringing" || c.state === "held" || c.state === "message"));
    if (pending) {
      this.ui.selectCall(pending.id);
      return;
    }
    const live = Object.values(w.calls).find((c) => c.state === "connected" && (c.callerId === id || c.connectedToId === id));
    if (live) this.ui.dispatch({ type: "listen", callId: live.listening ? null : live.id });
  }

  render(st: UiState): void {
    this.state = st;
    const w = st.world;
    const calls = Object.values(w.calls);
    const misroute = st.misrouteFor ? w.calls[st.misrouteFor] : undefined;

    for (const [id, lamp] of this.lampEls) {
      const actor = w.actors[id]!;
      const pending = calls.find((c) => c.callerId === id && (c.state === "ringing" || c.state === "held" || c.state === "message"));
      const live = calls.find((c) => c.state === "connected" && (c.callerId === id || c.connectedToId === id));
      let cls = "lamp";
      if (pending?.state === "ringing") cls += " ringing";
      else if (pending?.state === "held") cls += " held";
      else if (pending?.state === "message") cls += " message";
      else if (live) cls += " busy";
      lamp.setAttribute("class", cls);
      const g = this.jackGroups.get(id)!;
      let gcls = "jack";
      if (pending && pending.id === st.selectedCallId) gcls += " selected";
      if (live?.listening) gcls += " listening";
      if (actor.status !== "free") gcls += " dead";
      if (misroute) {
        const ok = id !== misroute.callerId && id !== misroute.requestedId && !reachable(w, id);
        gcls += ok ? " targetable" : " untargetable";
      }
      g.setAttribute("class", gcls);
      // Location can change (the Colonel rides with the Regiment, the President goes to the Embassy): the label
      // shows where the line is, not where the person is, so only the title changes.
      this.subEls.get(id)!.textContent = lineLabel(w, actor);
    }

    // Cords.
    clear(this.cords);
    clear(this.plugs);
    const live = calls.filter((c) => c.state === "connected").sort((a, b) => (a.connectedAt ?? 0) - (b.connectedAt ?? 0));
    live.forEach((c, i) => {
      const a = this.jacks.get(c.callerId);
      const b = this.jacks.get(c.connectedToId ?? "");
      if (!a || !b) return;
      const colour = CORD_COLOURS[i % CORD_COLOURS.length]!;
      const sag = 40 + Math.abs(a.x - b.x) * 0.12;
      const path = `M ${a.x} ${a.y} C ${a.x} ${Math.max(a.y, b.y) + sag}, ${b.x} ${Math.max(a.y, b.y) + sag}, ${b.x} ${b.y}`;
      const g = s("g", { class: `cord${c.listening ? " cord-listening" : ""}` });
      g.appendChild(s("path", { d: path, class: "cord-shadow" }));
      g.appendChild(s("path", { d: path, class: "cord-line", stroke: colour }));
      g.appendChild(s("title", {}, `${w.actors[c.callerId]!.short} to ${w.actors[c.connectedToId!]!.short}`));
      g.addEventListener("click", () => this.ui.dispatch({ type: "listen", callId: c.listening ? null : c.id }));
      this.cords.appendChild(g);
      for (const p of [a, b]) {
        this.plugs.appendChild(s("circle", { cx: p.x, cy: p.y, r: 7, class: "plug", fill: colour }));
        this.plugs.appendChild(s("circle", { cx: p.x - 2, cy: p.y - 2, r: 2, class: "plug-shine" }));
      }
    });

    if (misroute) {
      this.hint.textContent = `Choose a jack for ${w.actors[misroute.callerId]!.short}. Esc to cancel.`;
    } else if (live.length === 0 && calls.every((c) => c.state !== "ringing")) {
      this.hint.textContent = w.minute < 10 ? "The board is quiet." : "";
    } else {
      this.hint.textContent = "";
    }
  }
}

function lineLabel(w: World, actor: Actor): string {
  const loc = w.locations[actor.locationId];
  if (actor.status === "arrested") return "line dead";
  if (actor.status === "fled") return "no answer";
  return loc?.name ?? "";
}

export function callsFor(world: World, id: Id): Call[] {
  return Object.values(world.calls).filter((c) => c.callerId === id || c.connectedToId === id);
}
