export interface CitizenNeed {
  /** Shown on the call card and in the logbook: "wants to ..." */
  need: string;
  target: import("./types").Role;
  opening: string[];
  /** Fixed by the need's wording; otherwise chosen at random. */
  gender?: "m" | "f";
  /** Replaces Mr or Mrs in the short name. */
  title?: string;
  /** What they say to the party once connected, after "I'm sorry to call so late." */
  speech: string;
  /** What the person they reach says to them. */
  resolution: string;
  /** Needs the night makes: they only ring once this has happened. */
  after?: "casualties" | "decided";
}

